INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000000','Apakah definisi utama dari ilmu petrofisika dalam konteks industri migas?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:78:"Studi mengenai sifat fisik dan kimia batuan serta interaksi fluida di dalamnya";i:1;s:61:"Studi mengenai pergerakan lempeng tektonik di bawah permukaan";i:2;s:59:"Ilmu yang mempelajari desain struktur anjungan lepas pantai";i:3;s:59:"Ilmu yang fokus pada manajemen pemasaran produk minyak bumi";}','','Studi mengenai sifat fisik dan kimia batuan serta interaksi fluida di dalamnya','What is the primary definition of petrophysics in the context of the oil and gas industry?','a:4:{i:0;s:79:"The study of physical and chemical rock properties and their fluid interactions";i:1;s:55:"The study of tectonic plate movements in the subsurface";i:2;s:53:"The science of designing offshore platform structures";i:3;s:62:"The science focusing on petroleum product marketing management";}','The study of physical and chemical rock properties and their fluid interactions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000001','Manakah parameter berikut yang termasuk dalam parameter utama batuan reservoar?','multi','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:12:"Saturasi air";i:3;s:22:"Sudut kemiringan sumur";}','','a:3:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:12:"Saturasi air";}','Which of the following parameters are included as the primary reservoir rock parameters?','a:4:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:16:"Water saturation";i:3;s:26:"Wellbore inclination angle";}','a:3:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:16:"Water saturation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000002','Apa fungsi utama dari analisis data core dalam evaluasi petrofisika?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:55:"Memberikan sampel fisik batuan untuk kalibrasi data log";i:1;s:53:"Mengukur tekanan aliran fluida di dalam pipa produksi";i:2;s:51:"Menentukan lokasi pengeboran sumur baru di lapangan";i:3;s:46:"Menghitung volume cadangan minyak secara makro";}','','Memberikan sampel fisik batuan untuk kalibrasi data log','What is the primary function of core data analysis in petrophysical evaluation?','a:4:{i:0;s:57:"To provide physical rock samples for calibrating log data";i:1;s:55:"To measure fluid flow pressure inside production tubing";i:2;s:48:"To determine new drilling locations in the field";i:3;s:49:"To calculate oil reserve volumes on a macro scale";}','To provide physical rock samples for calibrating log data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000003','Log wireline manakah yang paling umum digunakan untuk mengestimasi porositas batuan?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:28:"Log Densitas dan Log Neutron";i:1;s:13:"Log Gamma Ray";i:2;s:25:"Log Spontaneous Potential";i:3;s:16:"Log Resistivitas";}','','Log Densitas dan Log Neutron','Which wireline log is most commonly used to estimate rock porosity?','a:4:{i:0;s:27:"Density Log and Neutron Log";i:1;s:13:"Gamma Ray Log";i:2;s:25:"Spontaneous Potential Log";i:3;s:15:"Resistivity Log";}','Density Log and Neutron Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000004','Apakah yang dimaksud dengan permeabilitas dalam batuan reservoar?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:40:"Kemampuan batuan untuk meloloskan fluida";i:1;s:51:"Persentase volume pori terhadap total volume batuan";i:2;s:39:"Fraksi volume pori yang terisi oleh air";i:3;s:44:"Ketahanan batuan terhadap tekanan overburden";}','','Kemampuan batuan untuk meloloskan fluida','What is meant by permeability in reservoir rocks?','a:4:{i:0;s:39:"The ability of rock to allow fluid flow";i:1;s:59:"The percentage of pore volume relative to total rock volume";i:2;s:45:"The fraction of pore volume occupied by water";i:3;s:45:"The resistance of rock to overburden pressure";}','The ability of rock to allow fluid flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000005','Data apa yang dapat diperoleh langsung dari pengukuran log resistivitas?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:24:"Estimasi saturasi fluida";i:1;s:24:"Estimasi porositas total";i:2;s:36:"Identifikasi litologi batuan lempung";i:3;s:34:"Penentuan sudut kemiringan formasi";}','','Estimasi saturasi fluida','What data can be obtained directly from resistivity log measurements?','a:4:{i:0;s:27:"Fluid saturation estimation";i:1;s:25:"Total porosity estimation";i:2;s:33:"Identification of shale lithology";i:3;s:36:"Determination of formation dip angle";}','Fluid saturation estimation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000006','Mengapa Gamma Ray log digunakan sebagai indikator litologi?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:60:"Karena mampu mendeteksi radioaktivitas alami mineral lempung";i:1;s:39:"Karena mengukur hambatan listrik batuan";i:2;s:41:"Karena mengukur kecepatan gelombang suara";i:3;s:50:"Karena mendeteksi keberadaan minyak di pori batuan";}','','Karena mampu mendeteksi radioaktivitas alami mineral lempung','Why is the Gamma Ray log used as a lithology indicator?','a:4:{i:0;s:64:"Because it can detect the natural radioactivity of clay minerals";i:1;s:46:"Because it measures rock electrical resistance";i:2;s:39:"Because it measures sound wave velocity";i:3;s:52:"Because it detects the presence of oil in rock pores";}','Because it can detect the natural radioactivity of clay minerals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000007','Dalam konteks petrofisika, apa yang dimaksud dengan porositas efektif?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:69:"Pori-pori yang saling berhubungan sehingga memungkinkan aliran fluida";i:1;s:68:"Total volume pori di dalam batuan tanpa memperhitungkan konektivitas";i:2;s:45:"Volume air yang terjebak di dalam pori batuan";i:3;s:40:"Pori-pori yang terisi oleh mineral semen";}','','Pori-pori yang saling berhubungan sehingga memungkinkan aliran fluida','In the context of petrophysics, what is meant by effective porosity?','a:4:{i:0;s:42:"Interconnected pores that allow fluid flow";i:1;s:62:"Total pore volume in the rock without considering connectivity";i:2;s:41:"Volume of water trapped inside rock pores";i:3;s:32:"Pores filled with mineral cement";}','Interconnected pores that allow fluid flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000008','Manakah dari berikut ini yang merupakan perbedaan antara data log dan data core?','multi','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:53:"Log bersifat kontinu, sedangkan core bersifat diskret";i:1;s:64:"Log diukur secara in-situ, sedangkan core diukur di laboratorium";i:2;s:47:"Data log selalu lebih akurat daripada data core";i:3;s:37:"Data core tidak membutuhkan kalibrasi";}','','a:2:{i:0;s:53:"Log bersifat kontinu, sedangkan core bersifat diskret";i:1;s:64:"Log diukur secara in-situ, sedangkan core diukur di laboratorium";}','Which of the following are differences between log data and core data?','a:4:{i:0;s:45:"Logs are continuous, while cores are discrete";i:1;s:69:"Logs are measured in-situ, while cores are measured in the laboratory";i:2;s:47:"Log data is always more accurate than core data";i:3;s:38:"Core data does not require calibration";}','a:2:{i:0;s:45:"Logs are continuous, while cores are discrete";i:1;s:69:"Logs are measured in-situ, while cores are measured in the laboratory";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000009','Apa pengaruh utama dari peningkatan nilai saturasi air pada reservoar?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:45:"Mengurangi potensi perolehan minyak (net pay)";i:1;s:41:"Meningkatkan permeabilitas absolut batuan";i:2;s:47:"Meningkatkan porositas batuan secara signifikan";i:3;s:50:"Tidak memberikan pengaruh terhadap cadangan minyak";}','','Mengurangi potensi perolehan minyak (net pay)','What is the primary effect of increasing water saturation values in a reservoir?','a:4:{i:0;s:40:"Reduces potential oil recovery (net pay)";i:1;s:36:"Increases absolute rock permeability";i:2;s:37:"Significantly increases rock porosity";i:3;s:29:"Has no effect on oil reserves";}','Reduces potential oil recovery (net pay)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000010','Manakah dari berikut ini yang merupakan karakteristik utama dari batuan reservoar klastik?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:57:"Terbentuk dari akumulasi fragmen mineral atau batuan lain";i:1;s:48:"Terbentuk terutama dari proses presipitasi kimia";i:2;s:44:"Memiliki porositas primer yang sangat rendah";i:3;s:33:"Sering menunjukkan struktur karst";}','','Terbentuk dari akumulasi fragmen mineral atau batuan lain','Which of the following is the main characteristic of clastic reservoir rocks?','a:4:{i:0;s:63:"Formed from the accumulation of mineral or other rock fragments";i:1;s:54:"Formed primarily from chemical precipitation processes";i:2;s:35:"Possesses very low primary porosity";i:3;s:31:"Often exhibits karst structures";}','Formed from the accumulation of mineral or other rock fragments','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000011','Komponen utama yang menyusun batuan karbonat adalah?','multi','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:6:"Kalsit";i:1;s:7:"Dolomit";i:2;s:6:"Kuarsa";i:3;s:8:"Feldspar";}','','a:2:{i:0;s:6:"Kalsit";i:1;s:7:"Dolomit";}','The main components that make up carbonate rocks are?','a:4:{i:0;s:7:"Calcite";i:1;s:8:"Dolomite";i:2;s:6:"Quartz";i:3;s:8:"Feldspar";}','a:2:{i:0;s:7:"Calcite";i:1;s:8:"Dolomite";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000012','Apa yang dimaksud dengan sortasi (sorting) dalam konteks tekstur batuan klastik?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:48:"Derajat keseragaman ukuran butir penyusun batuan";i:1;s:36:"Bentuk kebulatan dari fragmen batuan";i:2;s:32:"Kekompakan butiran dalam matriks";i:3;s:31:"Jumlah ruang pori antar butiran";}','','Derajat keseragaman ukuran butir penyusun batuan','What is meant by sorting in the context of clastic rock texture?','a:4:{i:0;s:50:"The degree of uniformity of grain size in the rock";i:1;s:41:"The degree of roundness of rock fragments";i:2;s:43:"The compactness of grains within the matrix";i:3;s:39:"The amount of pore space between grains";}','The degree of uniformity of grain size in the rock','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000013','Batuan reservoar yang mengalami konsolidasi rendah dan memiliki butiran lepas disebut?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:19:"Unconsolidated sand";i:1;s:5:"Shale";i:2;s:9:"Limestone";i:3;s:14:"Tight gas sand";}','','Unconsolidated sand','A reservoir rock that has undergone low consolidation and has loose grains is called?','a:4:{i:0;s:19:"Unconsolidated sand";i:1;s:5:"Shale";i:2;s:9:"Limestone";i:3;s:14:"Tight gas sand";}','Unconsolidated sand','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000014','Manakah faktor yang paling mempengaruhi porositas sekunder pada batuan karbonat?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:35:"Proses pelarutan dan rekristalisasi";i:1;s:20:"Ukuran butir klastik";i:2;s:29:"Kecepatan pengendapan sedimen";i:3;s:35:"Kandungan tanah liat (clay content)";}','','Proses pelarutan dan rekristalisasi','Which factor most influences secondary porosity in carbonate rocks?','a:4:{i:0;s:43:"Dissolution and recrystallization processes";i:1;s:18:"Clastic grain size";i:2;s:24:"Sediment deposition rate";i:3;s:12:"Clay content";}','Dissolution and recrystallization processes','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000015','Lingkungan pengendapan mana yang biasanya menghasilkan reservoar batu pasir (sandstone) dengan sortasi yang baik?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:39:"Lingkungan pantai (Aeolian atau pantai)";i:1;s:48:"Lingkungan sungai (fluvial) dengan arus turbulen";i:2;s:35:"Lingkungan laut dalam (deep marine)";i:3;s:22:"Lingkungan rawa gambut";}','','Lingkungan pantai (Aeolian atau pantai)','Which depositional environment typically produces sandstone reservoirs with good sorting?','a:4:{i:0;s:39:"Coastal environments (Aeolian or beach)";i:1;s:40:"Fluvial environments with turbulent flow";i:2;s:24:"Deep marine environments";i:3;s:23:"Peat swamp environments";}','Coastal environments (Aeolian or beach)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000016','Dalam kerangka batuan (rock framework), apa fungsi utama dari semen?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:58:"Merekatkan butiran batuan sehingga meningkatkan kekompakan";i:1;s:32:"Menambah porositas primer batuan";i:2;s:34:"Meningkatkan permeabilitas absolut";i:3;s:41:"Mengurangi densitas batuan secara drastis";}','','Merekatkan butiran batuan sehingga meningkatkan kekompakan','In a rock framework, what is the primary function of cement?','a:4:{i:0;s:52:"Bonding rock grains together to increase compactness";i:1;s:32:"Increasing primary rock porosity";i:2;s:32:"Increasing absolute permeability";i:3;s:33:"Drastically reducing rock density";}','Bonding rock grains together to increase compactness','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000017','Mengapa batuan karbonat sering kali memiliki heterogenitas yang lebih tinggi dibandingkan batuan klastik?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:64:"Karena pengaruh proses diagenesa pasca-pengendapan yang kompleks";i:1;s:63:"Karena batuan karbonat selalu terbentuk di lingkungan air dalam";i:2;s:60:"Karena batuan karbonat hanya terdiri dari satu jenis mineral";i:3;s:48:"Karena batuan karbonat tidak memiliki ruang pori";}','','Karena pengaruh proses diagenesa pasca-pengendapan yang kompleks','Why do carbonate rocks often have higher heterogeneity compared to clastic rocks?','a:4:{i:0;s:70:"Due to the influence of complex post-depositional diagenetic processes";i:1;s:62:"Because carbonate rocks always form in deep-water environments";i:2;s:59:"Because carbonate rocks consist of only one type of mineral";i:3;s:46:"Because carbonate rocks do not have pore space";}','Due to the influence of complex post-depositional diagenetic processes','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000018','Istilah ''matriks'' dalam batuan klastik merujuk pada?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:74:"Material berukuran halus yang mengisi ruang antar butiran yang lebih besar";i:1;s:30:"Butiran kuarsa berukuran besar";i:2;s:27:"Semen kimiawi yang mengeras";i:3;s:36:"Fosil yang terperangkap dalam batuan";}','','Material berukuran halus yang mengisi ruang antar butiran yang lebih besar','The term ''matrix'' in clastic rocks refers to?','a:4:{i:0;s:61:"Fine-grained material filling the space between larger grains";i:1;s:19:"Large quartz grains";i:2;s:24:"Hardened chemical cement";i:3;s:31:"Fossils trapped within the rock";}','Fine-grained material filling the space between larger grains','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000019','Manakah pernyataan yang benar mengenai tekstur batuan reservoar?','multi','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:48:"Tekstur mempengaruhi porositas dan permeabilitas";i:1;s:56:"Kebulatan butir (roundness) mempengaruhi packing butiran";i:2;s:70:"Batuan dengan sortasi buruk selalu memiliki permeabilitas lebih tinggi";i:3;s:60:"Ukuran butir tidak mempengaruhi kapasitas penyimpanan fluida";}','','a:2:{i:0;s:48:"Tekstur mempengaruhi porositas dan permeabilitas";i:1;s:56:"Kebulatan butir (roundness) mempengaruhi packing butiran";}','Which statements are true regarding reservoir rock texture?','a:4:{i:0;s:44:"Texture influences porosity and permeability";i:1;s:40:"Grain roundness influences grain packing";i:2;s:51:"Poorly sorted rocks always have higher permeability";i:3;s:49:"Grain size does not affect fluid storage capacity";}','a:2:{i:0;s:44:"Texture influences porosity and permeability";i:1;s:40:"Grain roundness influences grain packing";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000020','Jenis batuan manakah yang paling umum berfungsi sebagai batuan induk (source rock) karena kandungan material organik yang tinggi?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:10:"Batu pasir";i:1;s:19:"Batu serpih (shale)";i:2;s:22:"Batu gamping kristalin";i:3;s:11:"Konglomerat";}','','Batu serpih (shale)','Which rock type most commonly acts as a source rock due to its high organic material content?','a:4:{i:0;s:9:"Sandstone";i:1;s:5:"Shale";i:2;s:21:"Crystalline limestone";i:3;s:12:"Conglomerate";}','Shale','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000021','Faktor apa saja yang memicu proses migrasi primer hidrokarbon dari batuan induk ke batuan reservoar?','multi','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:50:"Peningkatan tekanan akibat pembebanan (compaction)";i:1;s:37:"Peningkatan suhu (thermal maturation)";i:2;s:20:"Gaya gravitasi murni";i:3;s:27:"Perbedaan viskositas fluida";}','','a:2:{i:0;s:50:"Peningkatan tekanan akibat pembebanan (compaction)";i:1;s:37:"Peningkatan suhu (thermal maturation)";}','What factors trigger the primary migration of hydrocarbons from the source rock to the reservoir rock?','a:4:{i:0;s:36:"Increased pressure due to compaction";i:1;s:42:"Increased temperature (thermal maturation)";i:2;s:24:"Pure gravitational force";i:3;s:27:"Fluid viscosity differences";}','a:2:{i:0;s:36:"Increased pressure due to compaction";i:1;s:42:"Increased temperature (thermal maturation)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000022','Apa fungsi utama dari batuan penutup (seal rock) dalam suatu sistem jebakan hidrokarbon?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:35:"Menambah porositas batuan reservoar";i:1;s:56:"Menghambat migrasi hidrokarbon lebih lanjut ke permukaan";i:2;s:33:"Meningkatkan permeabilitas batuan";i:3;s:46:"Menyediakan material organik untuk hidrokarbon";}','','Menghambat migrasi hidrokarbon lebih lanjut ke permukaan','What is the primary function of a seal rock in a hydrocarbon trap system?','a:4:{i:0;s:32:"Increase reservoir rock porosity";i:1;s:52:"Prevent further hydrocarbon migration to the surface";i:2;s:26:"Increase rock permeability";i:3;s:41:"Provide organic material for hydrocarbons";}','Prevent further hydrocarbon migration to the surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000023','Jebakan hidrokarbon yang terbentuk akibat adanya pergeseran lapisan batuan yang memutus kesinambungan reservoar disebut?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:16:"Jebakan antiklin";i:1;s:26:"Jebakan sesar (fault trap)";i:2;s:19:"Jebakan stratigrafi";i:3;s:12:"Jebakan reef";}','','Jebakan sesar (fault trap)','Hydrocarbon traps formed by the displacement of rock layers that break the continuity of the reservoir are called?','a:4:{i:0;s:14:"Anticline trap";i:1;s:10:"Fault trap";i:2;s:18:"Stratigraphic trap";i:3;s:9:"Reef trap";}','Fault trap','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000024','Dalam akumulasi hidrokarbon pada reservoar yang mengandung air, di manakah posisi minyak biasanya berada?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:32:"Di bagian paling bawah reservoar";i:1;s:34:"Tepat di bawah gas dan di atas air";i:2;s:27:"Tercampur merata dengan air";i:3;s:31:"Di bagian paling atas reservoar";}','','Tepat di bawah gas dan di atas air','In hydrocarbon accumulation within a reservoir containing water, where is the oil usually located?','a:4:{i:0;s:35:"At the very bottom of the reservoir";i:1;s:38:"Just below the gas and above the water";i:2;s:23:"Evenly mixed with water";i:3;s:32:"At the very top of the reservoir";}','Just below the gas and above the water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000025','Manakah dari berikut ini yang merupakan contoh jebakan stratigrafi?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:31:"Ketidakselarasan (unconformity)";i:1;s:16:"Lipatan antiklin";i:2;s:12:"Sesar normal";i:3;s:10:"Sesar naik";}','','Ketidakselarasan (unconformity)','Which of the following is an example of a stratigraphic trap?','a:4:{i:0;s:12:"Unconformity";i:1;s:14:"Anticline fold";i:2;s:12:"Normal fault";i:3;s:13:"Reverse fault";}','Unconformity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000026','Proses migrasi hidrokarbon yang terjadi melalui lapisan batuan berpori setelah keluar dari batuan induk disebut?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:14:"Migrasi primer";i:1;s:16:"Migrasi sekunder";i:2;s:15:"Migrasi tersier";i:3;s:15:"Migrasi lateral";}','','Migrasi sekunder','The process of hydrocarbon migration that occurs through porous rock layers after leaving the source rock is called?','a:4:{i:0;s:17:"Primary migration";i:1;s:19:"Secondary migration";i:2;s:18:"Tertiary migration";i:3;s:17:"Lateral migration";}','Secondary migration','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000027','Apa syarat mutlak agar suatu batuan dapat menjadi reservoar yang baik?','multi','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:29:"Memiliki porositas yang cukup";i:1;s:33:"Memiliki permeabilitas yang cukup";i:2;s:28:"Tidak memiliki kandungan air";i:3;s:29:"Terletak di atas batuan induk";}','','a:2:{i:0;s:29:"Memiliki porositas yang cukup";i:1;s:33:"Memiliki permeabilitas yang cukup";}','What are the absolute requirements for a rock to become a good reservoir?','a:4:{i:0;s:26:"Having sufficient porosity";i:1;s:30:"Having sufficient permeability";i:2;s:23:"Having no water content";i:3;s:29:"Located above the source rock";}','a:2:{i:0;s:26:"Having sufficient porosity";i:1;s:30:"Having sufficient permeability";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000028','Gaya apa yang paling dominan menggerakkan migrasi sekunder hidrokarbon di dalam reservoar?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:21:"Gaya apung (buoyancy)";i:1;s:12:"Gaya kapiler";i:2;s:14:"Gaya molekuler";i:3;s:20:"Gaya elektromagnetik";}','','Gaya apung (buoyancy)','What force is most dominant in driving the secondary migration of hydrocarbons within the reservoir?','a:4:{i:0;s:14:"Buoyancy force";i:1;s:15:"Capillary force";i:2;s:15:"Molecular force";i:3;s:21:"Electromagnetic force";}','Buoyancy force','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000029','Batuan sumber (source rock) yang matang harus mengalami pemanasan dalam jendela suhu tertentu untuk mengubah kerogen menjadi minyak. Jendela minyak (oil window) umumnya berada pada kisaran suhu?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:21:"20-40 derajat Celcius";i:1;s:22:"60-120 derajat Celcius";i:2;s:23:"200-300 derajat Celcius";i:3;s:27:"Di atas 500 derajat Celcius";}','','60-120 derajat Celcius','Mature source rocks must undergo heating within a specific temperature window to convert kerogen into oil. The oil window generally occurs at what temperature range?','a:4:{i:0;s:21:"20-40 degrees Celsius";i:1;s:22:"60-120 degrees Celsius";i:2;s:23:"200-300 degrees Celsius";i:3;s:25:"Above 500 degrees Celsius";}','60-120 degrees Celsius','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000030','Apa perbedaan utama antara porositas total dan porositas efektif pada batuan reservoar?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:106:"Porositas total mencakup semua pori, sedangkan porositas efektif hanya mencakup pori yang saling terhubung";i:1;s:89:"Porositas total hanya mencakup pori yang terhubung, sedangkan efektif mencakup semua pori";i:2;s:75:"Porositas total diukur di laboratorium, sedangkan efektif diukur dengan log";i:3;s:35:"Tidak ada perbedaan antara keduanya";}','','Porositas total mencakup semua pori, sedangkan porositas efektif hanya mencakup pori yang saling terhubung','What is the main difference between total porosity and effective porosity in reservoir rocks?','a:4:{i:0;s:94:"Total porosity includes all pores, while effective porosity only includes interconnected pores";i:1;s:80:"Total porosity only includes connected pores, while effective includes all pores";i:2;s:74:"Total porosity is measured in the lab, while effective is measured by logs";i:3;s:35:"There is no difference between them";}','Total porosity includes all pores, while effective porosity only includes interconnected pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000031','Faktor apa saja yang secara signifikan dapat menurunkan nilai porositas batuan sedimen selama proses diagenesa?','multi','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:8:"Kompaksi";i:1;s:9:"Sementasi";i:2;s:17:"Pelarutan mineral";i:3;s:30:"Penyortiran butiran yang buruk";}','','a:2:{i:0;s:8:"Kompaksi";i:1;s:9:"Sementasi";}','Which factors can significantly decrease the porosity value of sedimentary rocks during diagenesis?','a:4:{i:0;s:10:"Compaction";i:1;s:11:"Cementation";i:2;s:19:"Mineral dissolution";i:3;s:18:"Poor grain sorting";}','a:2:{i:0;s:10:"Compaction";i:1;s:11:"Cementation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000032','Bagaimana pengaruh kemasan butir (grain packing) yang lebih rapat terhadap porositas batuan pasir yang tidak tersementasi?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:24:"Porositas akan meningkat";i:1;s:22:"Porositas akan menurun";i:2;s:23:"Porositas tetap konstan";i:3;s:31:"Porositas menjadi tidak terukur";}','','Porositas akan menurun','How does tighter grain packing affect the porosity of unconsolidated sandstone?','a:4:{i:0;s:22:"Porosity will increase";i:1;s:22:"Porosity will decrease";i:2;s:25:"Porosity remains constant";i:3;s:29:"Porosity becomes immeasurable";}','Porosity will decrease','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000033','Metode log sumur manakah yang paling umum digunakan untuk mengestimasi porositas berdasarkan densitas elektron batuan?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:13:"Log Gamma Ray";i:1;s:26:"Log Densitas (Density Log)";i:2;s:25:"Log Spontaneous Potential";i:3;s:14:"Log Temperatur";}','','Log Densitas (Density Log)','Which well logging method is most commonly used to estimate porosity based on the electron density of the rock?','a:4:{i:0;s:13:"Gamma Ray Log";i:1;s:11:"Density Log";i:2;s:25:"Spontaneous Potential Log";i:3;s:15:"Temperature Log";}','Density Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000034','Proses geologi apakah yang dapat meningkatkan porositas sekunder pada batuan karbonat?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:16:"Kompaksi mekanik";i:1;s:16:"Sementasi kalsit";i:2;s:41:"Pelarutan (dissolution) oleh air meteorik";i:3;s:32:"Rekristalisasi yang sangat padat";}','','Pelarutan (dissolution) oleh air meteorik','Which geological process can increase secondary porosity in carbonate rocks?','a:4:{i:0;s:21:"Mechanical compaction";i:1;s:19:"Calcite cementation";i:2;s:29:"Dissolution by meteoric water";i:3;s:30:"High-density recrystallization";}','Dissolution by meteoric water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000035','Jika sebuah sampel core memiliki volume total 100 cc dan volume butiran padat sebesar 75 cc, berapakah porositas sampel tersebut?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:3:"20%";i:1;s:3:"25%";i:2;s:3:"33%";i:3;s:3:"75%";}','','25%','If a core sample has a total volume of 100 cc and a solid grain volume of 75 cc, what is the porosity of the sample?','a:4:{i:0;s:3:"20%";i:1;s:3:"25%";i:2;s:3:"33%";i:3;s:3:"75%";}','25%','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000036','Pilih dua alat log yang sering dikombinasikan untuk mengidentifikasi efek porositas sekunder (seperti vuggy porosity) pada batuan karbonat?','multi','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:12:"Log Densitas";i:1;s:11:"Log Neutron";i:2;s:13:"Log Gamma Ray";i:3;s:6:"Log SP";}','','a:2:{i:0;s:12:"Log Densitas";i:1;s:11:"Log Neutron";}','Select two log tools often combined to identify secondary porosity effects (such as vuggy porosity) in carbonate rocks?','a:4:{i:0;s:11:"Density Log";i:1;s:11:"Neutron Log";i:2;s:13:"Gamma Ray Log";i:3;s:6:"SP Log";}','a:2:{i:0;s:11:"Density Log";i:1;s:11:"Neutron Log";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000037','Bagaimana pengaruh sortasi (pemilahan) butiran terhadap porositas batuan sedimen?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:49:"Sortasi buruk menghasilkan porositas lebih tinggi";i:1;s:48:"Sortasi baik menghasilkan porositas lebih tinggi";i:2;s:44:"Sortasi tidak berpengaruh terhadap porositas";i:3;s:54:"Semakin seragam ukuran butir, porositas semakin rendah";}','','Sortasi baik menghasilkan porositas lebih tinggi','How does grain sorting influence the porosity of sedimentary rocks?','a:4:{i:0;s:39:"Poor sorting results in higher porosity";i:1;s:39:"Good sorting results in higher porosity";i:2;s:33:"Sorting has no effect on porosity";i:3;s:55:"The more uniform the grain size, the lower the porosity";}','Good sorting results in higher porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000038','Apa fungsi utama dari pengukuran porositas menggunakan sampel core di laboratorium?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:36:"Menggantikan fungsi log secara total";i:1;s:51:"Sebagai data kalibrasi untuk interpretasi log sumur";i:2;s:41:"Hanya untuk mengetahui berat jenis batuan";i:3;s:42:"Mengukur tekanan reservoir secara langsung";}','','Sebagai data kalibrasi untuk interpretasi log sumur','What is the primary function of porosity measurement using core samples in the laboratory?','a:4:{i:0;s:33:"To replace log functions entirely";i:1;s:47:"As calibration data for well log interpretation";i:2;s:30:"Only to determine rock density";i:3;s:38:"To measure reservoir pressure directly";}','As calibration data for well log interpretation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000039','Manakah pernyataan yang benar mengenai porositas primer?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:53:"Porositas yang terbentuk setelah batuan terlitifikasi";i:1;s:68:"Porositas yang terbentuk bersamaan dengan proses pengendapan sedimen";i:2;s:47:"Porositas yang disebabkan oleh pelarutan batuan";i:3;s:47:"Porositas yang terbentuk akibat proses tektonik";}','','Porositas yang terbentuk bersamaan dengan proses pengendapan sedimen','Which statement is correct regarding primary porosity?','a:4:{i:0;s:40:"Porosity formed after rock lithification";i:1;s:54:"Porosity formed during the sediment deposition process";i:2;s:35:"Porosity caused by rock dissolution";i:3;s:41:"Porosity formed due to tectonic processes";}','Porosity formed during the sediment deposition process','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000040','Apa syarat utama agar Hukum Darcy dapat diaplikasikan dalam aliran fluida di batuan berpori?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:62:"Aliran tunak (steady state), laminer, dan fluida inkompresibel";i:1;s:48:"Aliran tidak tunak (unsteady state) dan turbulen";i:2;s:42:"Fluida kompresibel dengan aliran multifasa";i:3;s:56:"Aliran pada kondisi reservoir dengan saturasi air tinggi";}','','Aliran tunak (steady state), laminer, dan fluida inkompresibel','What is the main requirement for Darcy''s Law to be applied in fluid flow through porous media?','a:4:{i:0;s:52:"Steady state, laminar, and incompressible fluid flow";i:1;s:33:"Unsteady state and turbulent flow";i:2;s:39:"Compressible fluid with multiphase flow";i:3;s:51:"Reservoir condition flow with high water saturation";}','Steady state, laminar, and incompressible fluid flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000041','Faktor apa saja yang paling signifikan mempengaruhi permeabilitas batuan sedimen?','multi','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:30:"Ukuran butir dan sortasi butir";i:1;s:12:"Saturasi gas";i:2;s:18:"Tekanan overburden";i:3;s:17:"Viskositas fluida";}','','a:2:{i:0;s:30:"Ukuran butir dan sortasi butir";i:1;s:18:"Tekanan overburden";}','Which factors most significantly affect the permeability of sedimentary rocks?','a:4:{i:0;s:22:"Grain size and sorting";i:1;s:14:"Gas saturation";i:2;s:19:"Overburden pressure";i:3;s:15:"Fluid viscosity";}','a:2:{i:0;s:22:"Grain size and sorting";i:1;s:19:"Overburden pressure";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000042','Manakah pernyataan yang benar mengenai permeabilitas efektif?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:77:"Permeabilitas suatu fluida jika terdapat lebih dari satu fluida yang mengalir";i:1;s:59:"Permeabilitas batuan yang hanya mengandung satu fasa fluida";i:2;s:63:"Rasio antara permeabilitas efektif dengan permeabilitas absolut";i:3;s:58:"Nilai permeabilitas yang diukur pada kondisi tekanan vakum";}','','Permeabilitas suatu fluida jika terdapat lebih dari satu fluida yang mengalir','Which statement is correct regarding effective permeability?','a:4:{i:0;s:63:"The permeability of a fluid when more than one fluid is flowing";i:1;s:56:"The permeability of rock containing only one fluid phase";i:2;s:60:"The ratio of effective permeability to absolute permeability";i:3;s:61:"The permeability value measured at vacuum pressure conditions";}','The permeability of a fluid when more than one fluid is flowing','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000043','Apa yang dimaksud dengan permeabilitas relatif?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:69:"Rasio permeabilitas efektif suatu fasa terhadap permeabilitas absolut";i:1;s:54:"Hasil perkalian permeabilitas efektif dengan porositas";i:2;s:77:"Nilai permeabilitas yang diukur secara tegak lurus terhadap bidang perlapisan";i:3;s:57:"Permeabilitas total batuan pada kondisi saturasi air 100%";}','','Rasio permeabilitas efektif suatu fasa terhadap permeabilitas absolut','What is meant by relative permeability?','a:4:{i:0;s:79:"The ratio of the effective permeability of a phase to the absolute permeability";i:1;s:50:"The product of effective permeability and porosity";i:2;s:66:"The permeability value measured perpendicular to the bedding plane";i:3;s:52:"The total rock permeability at 100% water saturation";}','The ratio of the effective permeability of a phase to the absolute permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000044','Permeabilitas absolut didefinisikan sebagai permeabilitas batuan ketika...','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:45:"Batuan hanya dijenuhkan oleh satu fasa fluida";i:1;s:46:"Batuan dijenuhkan oleh campuran minyak dan air";i:2;s:49:"Batuan dalam kondisi kering sempurna tanpa fluida";i:3;s:37:"Batuan memiliki porositas sebesar nol";}','','Batuan hanya dijenuhkan oleh satu fasa fluida','Absolute permeability is defined as the rock permeability when...','a:4:{i:0;s:47:"The rock is saturated with only one fluid phase";i:1;s:53:"The rock is saturated with a mixture of oil and water";i:2;s:54:"The rock is in a perfectly dry condition with no fluid";i:3;s:26:"The rock has zero porosity";}','The rock is saturated with only one fluid phase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000045','Bagaimana pengaruh clay (lempung) terhadap permeabilitas batuan?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:70:"Dapat menurunkan permeabilitas secara signifikan karena menyumbat pori";i:1;s:55:"Meningkatkan permeabilitas karena sifatnya yang reaktif";i:2;s:46:"Tidak memiliki pengaruh terhadap permeabilitas";i:3;s:57:"Hanya mempengaruhi porositas tanpa mengubah permeabilitas";}','','Dapat menurunkan permeabilitas secara signifikan karena menyumbat pori','How does clay affect rock permeability?','a:4:{i:0;s:60:"It can significantly decrease permeability by plugging pores";i:1;s:52:"It increases permeability due to its reactive nature";i:2;s:32:"It has no effect on permeability";i:3;s:54:"It only affects porosity without altering permeability";}','It can significantly decrease permeability by plugging pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000046','Alat manakah yang umum digunakan di laboratorium untuk mengukur permeabilitas sampel batuan core?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:11:"Permeameter";i:1;s:11:"Porosimeter";i:2;s:12:"Viskosimeter";i:3;s:10:"Pycnometer";}','','Permeameter','Which instrument is commonly used in the laboratory to measure permeability of core samples?','a:4:{i:0;s:11:"Permeameter";i:1;s:11:"Porosimeter";i:2;s:12:"Viscosimeter";i:3;s:10:"Pycnometer";}','Permeameter','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000047','Mengapa permeabilitas bisa bersifat anisotropik di reservoir?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:67:"Karena adanya struktur perlapisan atau orientasi butir yang dominan";i:1;s:48:"Karena distribusi saturasi air yang tidak merata";i:2;s:53:"Karena pengaruh kedalaman reservoir yang sangat dalam";i:3;s:47:"Karena perbedaan jenis fluida yang mengisi pori";}','','Karena adanya struktur perlapisan atau orientasi butir yang dominan','Why can permeability be anisotropic in a reservoir?','a:4:{i:0;s:71:"Due to the presence of bedding structures or dominant grain orientation";i:1;s:46:"Due to uneven distribution of water saturation";i:2;s:46:"Due to the effect of very deep reservoir depth";i:3;s:58:"Due to differences in the type of fluids filling the pores";}','Due to the presence of bedding structures or dominant grain orientation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000048','Dalam Hukum Darcy, manakah parameter yang berbanding terbalik dengan laju alir (Q)?','multi','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:17:"Viskositas fluida";i:1;s:23:"Panjang lintasan aliran";i:2;s:14:"Luas penampang";i:3;s:7:"Tekanan";}','','a:2:{i:0;s:17:"Viskositas fluida";i:1;s:23:"Panjang lintasan aliran";}','In Darcy''s Law, which parameters are inversely proportional to the flow rate (Q)?','a:4:{i:0;s:15:"Fluid viscosity";i:1;s:16:"Flow path length";i:2;s:20:"Cross-sectional area";i:3;s:8:"Pressure";}','a:2:{i:0;s:15:"Fluid viscosity";i:1;s:16:"Flow path length";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000049','Apa yang dimaksud dengan Klinkenberg effect dalam pengukuran permeabilitas?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:62:"Koreksi permeabilitas akibat slippage gas pada pori-pori kecil";i:1;s:58:"Koreksi akibat tekanan kapiler tinggi pada batuan karbonat";i:2;s:59:"Fenomena penurunan permeabilitas akibat pengendapan mineral";i:3;s:45:"Koreksi akibat adanya distorsi pada alat ukur";}','','Koreksi permeabilitas akibat slippage gas pada pori-pori kecil','What is the Klinkenberg effect in permeability measurement?','a:4:{i:0;s:58:"Permeability correction due to gas slippage in small pores";i:1;s:60:"Correction due to high capillary pressure in carbonate rocks";i:2;s:62:"Phenomenon of permeability reduction due to mineral deposition";i:3;s:53:"Correction due to distortion in measuring instruments";}','Permeability correction due to gas slippage in small pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000050','Berapakah definisi dari saturasi air (Sw) dalam suatu sistem pori batuan reservoir?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:60:"Rasio volume pori yang terisi air terhadap total volume pori";i:1;s:44:"Rasio volume air terhadap volume bulk batuan";i:2;s:53:"Persentase air yang dapat bergerak di dalam reservoir";i:3;s:61:"Volume air yang terikat secara kimiawi pada permukaan butiran";}','','Rasio volume pori yang terisi air terhadap total volume pori','What is the definition of water saturation (Sw) in a reservoir rock pore system?','a:4:{i:0;s:59:"Ratio of pore volume occupied by water to total pore volume";i:1;s:41:"Ratio of water volume to bulk rock volume";i:2;s:43:"Percentage of mobile water in the reservoir";i:3;s:50:"Volume of water chemically bound to grain surfaces";}','Ratio of pore volume occupied by water to total pore volume','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000051','Manakah pernyataan yang paling tepat mengenai hubungan antara porositas dan permeabilitas pada batuan klastik?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:79:"Permeabilitas cenderung meningkat seiring dengan bertambahnya porositas efektif";i:1;s:82:"Permeabilitas selalu berbanding lurus dengan porositas tanpa pengaruh ukuran butir";i:2;s:53:"Porositas tinggi selalu menjamin permeabilitas tinggi";i:3;s:56:"Permeabilitas tidak memiliki korelasi dengan ukuran pori";}','','Permeabilitas cenderung meningkat seiring dengan bertambahnya porositas efektif','Which statement best describes the relationship between porosity and permeability in clastic rocks?','a:4:{i:0;s:65:"Permeability tends to increase with increasing effective porosity";i:1;s:81:"Permeability is always directly proportional to porosity regardless of grain size";i:2;s:49:"High porosity always guarantees high permeability";i:3;s:46:"Permeability has no correlation with pore size";}','Permeability tends to increase with increasing effective porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000052','Apa yang dimaksud dengan Net Pay dalam perhitungan cadangan hidrokarbon?','multi','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:72:"Bagian dari reservoir yang mampu memproduksi hidrokarbon secara ekonomis";i:1;s:58:"Ketebalan total formasi dari puncak hingga dasar reservoir";i:2;s:55:"Ketebalan batuan dengan porositas di atas batas minimum";i:3;s:60:"Ketebalan batuan dengan saturasi air di bawah batas maksimum";}','','a:3:{i:0;s:72:"Bagian dari reservoir yang mampu memproduksi hidrokarbon secara ekonomis";i:1;s:55:"Ketebalan batuan dengan porositas di atas batas minimum";i:2;s:60:"Ketebalan batuan dengan saturasi air di bawah batas maksimum";}','What is meant by Net Pay in hydrocarbon reserve calculations?','a:4:{i:0;s:75:"The portion of the reservoir capable of producing hydrocarbons economically";i:1;s:67:"Total formation thickness from the top to the base of the reservoir";i:2;s:51:"Rock thickness with porosity above a minimum cutoff";i:3;s:59:"Rock thickness with water saturation below a maximum cutoff";}','a:3:{i:0;s:75:"The portion of the reservoir capable of producing hydrocarbons economically";i:1;s:51:"Rock thickness with porosity above a minimum cutoff";i:2;s:59:"Rock thickness with water saturation below a maximum cutoff";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000053','Faktor apa yang paling signifikan mempengaruhi kompresibilitas batuan (rock compressibility)?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:47:"Porositas batuan dan tekanan efektif overburden";i:1;s:34:"Warna batuan dan komposisi mineral";i:2;s:37:"Laju alir fluida saat pengujian sumur";i:3;s:38:"Suhu reservoir pada kedalaman tertentu";}','','Porositas batuan dan tekanan efektif overburden','What factor most significantly influences rock compressibility?','a:4:{i:0;s:47:"Rock porosity and effective overburden pressure";i:1;s:34:"Rock color and mineral composition";i:2;s:35:"Fluid flow rate during well testing";i:3;s:38:"Reservoir temperature at a given depth";}','Rock porosity and effective overburden pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000054','Dalam kondisi reservoir, berapakah jumlah total saturasi fluida dalam pori batuan?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:15:"1.0 (atau 100%)";i:1;s:14:"0.5 (atau 50%)";i:2;s:30:"Sesuai dengan porositas batuan";i:3;s:33:"Tergantung pada viskositas minyak";}','','1.0 (atau 100%)','Under reservoir conditions, what is the total sum of fluid saturations in the rock pores?','a:4:{i:0;s:13:"1.0 (or 100%)";i:1;s:12:"0.5 (or 50%)";i:2;s:22:"Equal to rock porosity";i:3;s:24:"Depends on oil viscosity";}','1.0 (or 100%)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000055','Mengapa permeabilitas absolut berbeda dengan permeabilitas efektif?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:82:"Permeabilitas efektif dipengaruhi oleh keberadaan fluida lain (saturasi multipasa)";i:1;s:45:"Permeabilitas absolut hanya berlaku untuk gas";i:2;s:50:"Permeabilitas efektif hanya diukur di laboratorium";i:3;s:58:"Permeabilitas absolut tidak dipengaruhi oleh struktur pori";}','','Permeabilitas efektif dipengaruhi oleh keberadaan fluida lain (saturasi multipasa)','Why is absolute permeability different from effective permeability?','a:4:{i:0;s:92:"Effective permeability is influenced by the presence of other fluids (multiphase saturation)";i:1;s:41:"Absolute permeability applies only to gas";i:2;s:57:"Effective permeability is only measured in the laboratory";i:3;s:57:"Absolute permeability is not influenced by pore structure";}','Effective permeability is influenced by the presence of other fluids (multiphase saturation)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000056','Apa dampak peningkatan tekanan reservoir terhadap kompresibilitas batuan?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:59:"Batuan cenderung mengalami pemampatan (penurunan porositas)";i:1;s:53:"Batuan mengalami pengembangan (peningkatan porositas)";i:2;s:41:"Tidak ada perubahan pada porositas batuan";i:3;s:58:"Permeabilitas akan meningkat secara drastis secara drastis";}','','Batuan cenderung mengalami pemampatan (penurunan porositas)','What is the impact of increasing reservoir pressure on rock compressibility?','a:4:{i:0;s:55:"Rock tends to undergo compaction (decrease in porosity)";i:1;s:47:"Rock undergoes expansion (increase in porosity)";i:2;s:26:"No change in rock porosity";i:3;s:38:"Permeability will increase drastically";}','Rock tends to undergo compaction (decrease in porosity)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000057','Manakah parameter yang digunakan untuk membedakan antara Net Sand dan Net Pay?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:66:"Cut-off properti petrofisika (porositas, saturasi air, dan Vshale)";i:1;s:21:"Hanya kedalaman sumur";i:2;s:26:"Hanya permeabilitas mutlak";i:3;s:23:"Jumlah lubang perforasi";}','','Cut-off properti petrofisika (porositas, saturasi air, dan Vshale)','Which parameters are used to distinguish between Net Sand and Net Pay?','a:4:{i:0;s:72:"Petrophysical property cut-offs (porosity, water saturation, and Vshale)";i:1;s:15:"Only well depth";i:2;s:26:"Only absolute permeability";i:3;s:27:"Number of perforation holes";}','Petrophysical property cut-offs (porosity, water saturation, and Vshale)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000058','Jika sebuah batuan memiliki saturasi air (Sw) sebesar 20%, berapakah saturasi hidrokarbonnya?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:3:"80%";i:1;s:3:"20%";i:2;s:4:"100%";i:3;s:3:"40%";}','','80%','If a rock has a water saturation (Sw) of 20%, what is its hydrocarbon saturation?','a:4:{i:0;s:3:"80%";i:1;s:3:"20%";i:2;s:4:"100%";i:3;s:3:"40%";}','80%','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000059','Bagaimana pengaruh ukuran butiran terhadap permeabilitas pada batuan pasir yang terpilah baik (well-sorted)?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:82:"Ukuran butiran yang lebih besar umumnya memberikan permeabilitas yang lebih tinggi";i:1;s:55:"Ukuran butiran tidak berpengaruh terhadap permeabilitas";i:2;s:64:"Ukuran butiran kecil selalu memberikan permeabilitas lebih besar";i:3;s:54:"Permeabilitas hanya bergantung pada tekanan overburden";}','','Ukuran butiran yang lebih besar umumnya memberikan permeabilitas yang lebih tinggi','How does grain size influence permeability in well-sorted sandstone?','a:4:{i:0;s:56:"Larger grain size generally provides higher permeability";i:1;s:40:"Grain size has no effect on permeability";i:2;s:54:"Smaller grain size always provides higher permeability";i:3;s:48:"Permeability depends only on overburden pressure";}','Larger grain size generally provides higher permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000060','Pada diagram fase hidrokarbon, titik manakah yang mewakili kondisi di mana fase cair dan fase gas memiliki sifat yang identik?','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:12:"Titik kritis";i:1;s:20:"Titik cricondentherm";i:2;s:18:"Titik cricondenbar";i:3;s:18:"Titik bubble point";}','','Titik kritis','On a hydrocarbon phase diagram, which point represents the condition where liquid and gas phases have identical properties?','a:4:{i:0;s:14:"Critical point";i:1;s:20:"Cricondentherm point";i:2;s:18:"Cricondenbar point";i:3;s:12:"Bubble point";}','Critical point','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000061','Jenis reservoir fluida yang komposisinya didominasi oleh fraksi berat (C7+) dan mengalami penurunan tekanan signifikan di bawah bubble point adalah:','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:9:"Black oil";i:1;s:12:"Volatile oil";i:2;s:13:"Gas kondensat";i:3;s:7:"Dry gas";}','','Black oil','The type of reservoir fluid dominated by heavy fractions (C7+) that experiences significant pressure drop below the bubble point is:','a:4:{i:0;s:9:"Black oil";i:1;s:12:"Volatile oil";i:2;s:14:"Gas condensate";i:3;s:7:"Dry gas";}','Black oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000062','Manakah pernyataan berikut yang benar mengenai karakteristik reservoir gas kondensat?','multi','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:48:"Terjadi kondensasi retrograde di dalam reservoir";i:1;s:62:"Suhu reservoir berada di antara suhu kritis dan cricondentherm";i:2;s:41:"Hanya memproduksi gas kering di permukaan";i:3;s:31:"Memiliki GOR yang sangat rendah";}','','a:2:{i:0;s:48:"Terjadi kondensasi retrograde di dalam reservoir";i:1;s:62:"Suhu reservoir berada di antara suhu kritis dan cricondentherm";}','Which of the following statements are true regarding the characteristics of a gas condensate reservoir?','a:4:{i:0;s:51:"Retrograde condensation occurs within the reservoir";i:1;s:72:"Reservoir temperature is between critical temperature and cricondentherm";i:2;s:36:"Produces only dry gas at the surface";i:3;s:18:"Has a very low GOR";}','a:2:{i:0;s:51:"Retrograde condensation occurs within the reservoir";i:1;s:72:"Reservoir temperature is between critical temperature and cricondentherm";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000063','Apa yang dimaksud dengan cricondentherm dalam diagram fase hidrokarbon?','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:42:"Suhu maksimum di mana dua fase dapat eksis";i:1;s:45:"Tekanan maksimum di mana dua fase dapat eksis";i:2;s:32:"Suhu di mana gas mulai mengembun";i:3;s:49:"Tekanan di mana gelembung gas pertama kali muncul";}','','Suhu maksimum di mana dua fase dapat eksis','What is meant by cricondentherm in a hydrocarbon phase diagram?','a:4:{i:0;s:51:"Maximum temperature at which two phases can coexist";i:1;s:48:"Maximum pressure at which two phases can coexist";i:2;s:40:"Temperature where gas starts to condense";i:3;s:43:"Pressure where the first gas bubble appears";}','Maximum temperature at which two phases can coexist','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000064','Reservoir yang fluida-nya tetap dalam fase gas meskipun tekanan turun secara isotermal di bawah tekanan dew point dikenal sebagai:','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:7:"Dry gas";i:1;s:7:"Wet gas";i:2;s:12:"Volatile oil";i:3;s:9:"Black oil";}','','Dry gas','A reservoir whose fluid remains in the gas phase even if the pressure drops isothermally below the dew point is known as:','a:4:{i:0;s:7:"Dry gas";i:1;s:7:"Wet gas";i:2;s:12:"Volatile oil";i:3;s:9:"Black oil";}','Dry gas','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000065','Apa perbedaan utama antara Black Oil dan Volatile Oil dalam hal rasio gas-minyak (GOR)?','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:43:"Volatile oil memiliki GOR yang lebih tinggi";i:1;s:40:"Black oil memiliki GOR yang lebih tinggi";i:2;s:31:"Keduanya memiliki GOR yang sama";i:3;s:39:"Volatile oil memiliki GOR mendekati nol";}','','Volatile oil memiliki GOR yang lebih tinggi','What is the main difference between Black Oil and Volatile Oil in terms of gas-oil ratio (GOR)?','a:4:{i:0;s:29:"Volatile oil has a higher GOR";i:1;s:26:"Black oil has a higher GOR";i:2;s:22:"Both have the same GOR";i:3;s:32:"Volatile oil has a GOR near zero";}','Volatile oil has a higher GOR','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000066','Dalam diagram fase, garis yang memisahkan area dua fase (cair dan gas) dari area fase tunggal cair disebut sebagai:','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:17:"Bubble point line";i:1;s:14:"Dew point line";i:2;s:17:"Critical isotherm";i:3;s:17:"Cricondenbar line";}','','Bubble point line','In a phase diagram, the line separating the two-phase area (liquid and gas) from the single-phase liquid area is called:','a:4:{i:0;s:17:"Bubble point line";i:1;s:14:"Dew point line";i:2;s:17:"Critical isotherm";i:3;s:17:"Cricondenbar line";}','Bubble point line','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000067','Faktor apa saja yang memengaruhi perubahan fase fluida reservoir?','multi','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:7:"Tekanan";i:1;s:4:"Suhu";i:2;s:20:"Permeabilitas batuan";i:3;s:22:"Komposisi kimia fluida";}','','a:3:{i:0;s:7:"Tekanan";i:1;s:4:"Suhu";i:2;s:22:"Komposisi kimia fluida";}','What factors influence the phase changes of reservoir fluids?','a:4:{i:0;s:8:"Pressure";i:1;s:11:"Temperature";i:2;s:17:"Rock permeability";i:3;s:33:"Chemical composition of the fluid";}','a:3:{i:0;s:8:"Pressure";i:1;s:11:"Temperature";i:2;s:33:"Chemical composition of the fluid";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000068','Fenomena di mana cairan terbentuk dari fasa gas akibat penurunan tekanan di reservoir disebut:','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:23:"Retrograde condensation";i:1;s:18:"Flash vaporization";i:2;s:23:"Bubble point depression";i:3;s:20:"Critical fluctuation";}','','Retrograde condensation','The phenomenon where liquid forms from a gas phase due to pressure decrease in the reservoir is called:','a:4:{i:0;s:23:"Retrograde condensation";i:1;s:18:"Flash vaporization";i:2;s:23:"Bubble point depression";i:3;s:20:"Critical fluctuation";}','Retrograde condensation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000069','Karakteristik utama dari ''Wet Gas'' adalah:','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:40:"Menghasilkan kondensat cair di permukaan";i:1;s:25:"Hanya berupa metana murni";i:2;s:25:"Hanya berupa minyak berat";i:3;s:26:"Tidak memiliki titik embun";}','','Menghasilkan kondensat cair di permukaan','The main characteristic of ''Wet Gas'' is:','a:4:{i:0;s:41:"Produces liquid condensate at the surface";i:1;s:29:"Consists only of pure methane";i:2;s:26:"Consists only of heavy oil";i:3;s:16:"Has no dew point";}','Produces liquid condensate at the surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000070','Apa yang dimaksud dengan faktor volume formasi minyak (Bo)?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:96:"Perbandingan volume minyak di reservoir terhadap volume minyak di permukaan pada kondisi standar";i:1;s:72:"Perbandingan volume gas di reservoir terhadap volume minyak di permukaan";i:2;s:64:"Densitas minyak di reservoir dibagi densitas minyak di permukaan";i:3;s:45:"Kompresibilitas minyak pada tekanan reservoir";}','','Perbandingan volume minyak di reservoir terhadap volume minyak di permukaan pada kondisi standar','What is defined as the oil formation volume factor (Bo)?','a:4:{i:0;s:88:"Ratio of oil volume at reservoir conditions to oil volume at standard surface conditions";i:1;s:57:"Ratio of gas volume at reservoir to oil volume at surface";i:2;s:58:"Oil density at reservoir divided by oil density at surface";i:3;s:41:"Oil compressibility at reservoir pressure";}','Ratio of oil volume at reservoir conditions to oil volume at standard surface conditions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000071','Faktor apa saja yang mempengaruhi nilai kompresibilitas isotermal minyak (Co)?','multi','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:17:"Tekanan reservoir";i:1;s:20:"Temperatur reservoir";i:2;s:20:"Permeabilitas batuan";i:3;s:17:"Saturasi air awal";}','','a:2:{i:0;s:17:"Tekanan reservoir";i:1;s:20:"Temperatur reservoir";}','Which factors influence the isothermal oil compressibility (Co)?','a:4:{i:0;s:18:"Reservoir pressure";i:1;s:21:"Reservoir temperature";i:2;s:17:"Rock permeability";i:3;s:24:"Initial water saturation";}','a:2:{i:0;s:18:"Reservoir pressure";i:1;s:21:"Reservoir temperature";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000072','Bagaimana hubungan antara nilai Gas-Oil Ratio (GOR) dengan tekanan di atas bubble point pada minyak undersaturated?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:23:"Nilai GOR tetap konstan";i:1;s:27:"Nilai GOR meningkat drastis";i:2;s:43:"Nilai GOR menurun seiring penurunan tekanan";i:3;s:13:"Nilai GOR nol";}','','Nilai GOR tetap konstan','How does the Gas-Oil Ratio (GOR) relate to pressure above the bubble point in undersaturated oil?','a:4:{i:0;s:20:"GOR remains constant";i:1;s:25:"GOR increases drastically";i:2;s:31:"GOR decreases as pressure drops";i:3;s:11:"GOR is zero";}','GOR remains constant','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000073','Dalam uji laboratorium PVT, kondisi apa yang harus dipertahankan untuk merepresentasikan reservoir yang sebenarnya?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:24:"Isotermal (suhu konstan)";i:1;s:26:"Isobarik (tekanan konstan)";i:2;s:9:"Adiabatik";i:3;s:13:"Kondisi vakum";}','','Isotermal (suhu konstan)','In PVT laboratory tests, what condition must be maintained to represent the actual reservoir?','a:4:{i:0;s:33:"Isothermal (constant temperature)";i:1;s:28:"Isobaric (constant pressure)";i:2;s:9:"Adiabatic";i:3;s:16:"Vacuum condition";}','Isothermal (constant temperature)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000074','Pilih parameter fisik fluida yang diukur langsung dari analisis PVT di laboratorium.','multi','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:26:"Faktor volume formasi (Bo)";i:1;s:21:"Permeabilitas relatif";i:2;s:20:"Tekanan bubble point";i:3;s:15:"Densitas fluida";}','','a:3:{i:0;s:26:"Faktor volume formasi (Bo)";i:1;s:20:"Tekanan bubble point";i:2;s:15:"Densitas fluida";}','Select the fluid physical parameters measured directly from laboratory PVT analysis.','a:4:{i:0;s:28:"Formation volume factor (Bo)";i:1;s:21:"Relative permeability";i:2;s:21:"Bubble point pressure";i:3;s:13:"Fluid density";}','a:3:{i:0;s:28:"Formation volume factor (Bo)";i:1;s:21:"Bubble point pressure";i:2;s:13:"Fluid density";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000075','Apa yang terjadi pada faktor volume formasi gas (Bg) ketika tekanan reservoir menurun?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:18:"Nilai Bg meningkat";i:1;s:16:"Nilai Bg menurun";i:2;s:14:"Nilai Bg tetap";i:3;s:20:"Nilai Bg menjadi nol";}','','Nilai Bg meningkat','What happens to the gas formation volume factor (Bg) when reservoir pressure decreases?','a:4:{i:0;s:18:"Bg value increases";i:1;s:18:"Bg value decreases";i:2;s:25:"Bg value remains constant";i:3;s:21:"Bg value becomes zero";}','Bg value increases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000076','Manakah pernyataan yang benar mengenai faktor volume formasi air (Bw)?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:29:"Nilainya selalu mendekati 1.0";i:1;s:35:"Nilainya selalu lebih besar dari Bo";i:2;s:35:"Nilainya sangat bergantung pada GOR";i:3;s:31:"Nilainya tidak dipengaruhi suhu";}','','Nilainya selalu mendekati 1.0','Which statement is correct regarding the water formation volume factor (Bw)?','a:4:{i:0;s:32:"Its value is always close to 1.0";i:1;s:35:"Its value is always greater than Bo";i:2;s:31:"Its value highly depends on GOR";i:3;s:40:"Its value is not affected by temperature";}','Its value is always close to 1.0','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000077','Apa dampak peningkatan suhu reservoir terhadap densitas minyak?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:16:"Densitas menurun";i:1;s:18:"Densitas meningkat";i:2;s:22:"Densitas tidak berubah";i:3;s:30:"Densitas menjadi tak terhingga";}','','Densitas menurun','What is the effect of increasing reservoir temperature on oil density?','a:4:{i:0;s:17:"Density decreases";i:1;s:17:"Density increases";i:2;s:25:"Density remains unchanged";i:3;s:24:"Density becomes infinite";}','Density decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000078','Parameter apa yang digunakan untuk mengukur perubahan volume fluida terhadap perubahan tekanan?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:15:"Kompresibilitas";i:1;s:10:"Viskositas";i:2;s:19:"Tegangan antar muka";i:3;s:8:"Densitas";}','','Kompresibilitas','What parameter is used to measure the change in fluid volume with respect to change in pressure?','a:4:{i:0;s:15:"Compressibility";i:1;s:9:"Viscosity";i:2;s:19:"Interfacial tension";i:3;s:7:"Density";}','Compressibility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000079','Pada kondisi reservoir di bawah bubble point, apa yang terjadi pada gas dalam minyak?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:35:"Gas terbebaskan dari larutan minyak";i:1;s:40:"Gas semakin banyak terlarut dalam minyak";i:2;s:34:"Gas tidak mengalami perubahan fase";i:3;s:25:"Gas berubah menjadi padat";}','','Gas terbebaskan dari larutan minyak','Under reservoir conditions below the bubble point, what happens to the gas in the oil?','a:4:{i:0;s:38:"Gas is liberated from the oil solution";i:1;s:31:"More gas dissolves into the oil";i:2;s:33:"Gas does not undergo phase change";i:3;s:20:"Gas turns into solid";}','Gas is liberated from the oil solution','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000080','Parameter utama yang paling dominan mempengaruhi nilai resistivitas air formasi (Rw) pada kondisi suhu tertentu adalah?','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:9:"Salinitas";i:1;s:18:"Tekanan overburden";i:2;s:16:"Porositas batuan";i:3;s:17:"Viskositas minyak";}','','Salinitas','What is the primary parameter that most dominantly influences the formation water resistivity (Rw) at a given temperature?','a:4:{i:0;s:8:"Salinity";i:1;s:19:"Overburden pressure";i:2;s:13:"Rock porosity";i:3;s:13:"Oil viscosity";}','Salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000081','Bagaimana pengaruh peningkatan suhu formasi mempengaruhi nilai resistivitas air (Rw)?','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:12:"Rw meningkat";i:1;s:10:"Rw menurun";i:2;s:16:"Rw tetap konstan";i:3;s:14:"Rw menjadi nol";}','','Rw menurun','How does an increase in formation temperature affect the water resistivity (Rw) value?','a:4:{i:0;s:12:"Rw increases";i:1;s:12:"Rw decreases";i:2;s:19:"Rw remains constant";i:3;s:15:"Rw becomes zero";}','Rw decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000082','Faktor apa saja yang menyebabkan resistivitas batuan (Rt) menjadi lebih rendah dibandingkan seharusnya pada zona yang mengandung hidrokarbon?','multi','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:33:"Kehadiran mineral lempung (shale)";i:1;s:33:"Peningkatan salinitas air formasi";i:2;s:27:"Adanya air konat dalam pori";i:3;s:28:"Peningkatan porositas primer";}','','a:2:{i:0;s:33:"Kehadiran mineral lempung (shale)";i:1;s:33:"Peningkatan salinitas air formasi";}','What factors cause the rock resistivity (Rt) to be lower than expected in hydrocarbon-bearing zones?','a:4:{i:0;s:33:"Presence of clay minerals (shale)";i:1;s:36:"Increase in formation water salinity";i:2;s:34:"Presence of connate water in pores";i:3;s:28:"Increase in primary porosity";}','a:2:{i:0;s:33:"Presence of clay minerals (shale)";i:1;s:36:"Increase in formation water salinity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000083','Dalam persamaan Archie, apa yang direpresentasikan oleh faktor formasi (F)?','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:25:"Hubungan antara Ro dan Rw";i:1;s:25:"Hubungan antara Rt dan Rw";i:2;s:34:"Hubungan antara salinitas dan suhu";i:3;s:35:"Hubungan antara saturasi air dan Rw";}','','Hubungan antara Ro dan Rw','In the Archie equation, what does the formation factor (F) represent?','a:4:{i:0;s:30:"Relationship between Ro and Rw";i:1;s:30:"Relationship between Rt and Rw";i:2;s:45:"Relationship between salinity and temperature";i:3;s:44:"Relationship between water saturation and Rw";}','Relationship between Ro and Rw','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000084','Apa yang dimaksud dengan Ro dalam konteks petrofisika?','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:39:"Resistivitas batuan saat jenuh air 100%";i:1;s:42:"Resistivitas batuan saat jenuh hidrokarbon";i:2;s:24:"Resistivitas air formasi";i:3;s:24:"Resistivitas zona invasi";}','','Resistivitas batuan saat jenuh air 100%','What is meant by Ro in the context of petrophysics?','a:4:{i:0;s:44:"Resistivity of rock at 100% water saturation";i:1;s:45:"Resistivity of rock at hydrocarbon saturation";i:2;s:27:"Formation water resistivity";i:3;s:31:"Resistivity of the invaded zone";}','Resistivity of rock at 100% water saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000085','Kehadiran shale (mineral lempung) pada batuan reservoir akan menyebabkan nilai resistivitas yang terukur (Rt) menjadi:','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:41:"Lebih rendah dari resistivitas sebenarnya";i:1;s:41:"Lebih tinggi dari resistivitas sebenarnya";i:2;s:17:"Tidak terpengaruh";i:3;s:14:"Sama dengan Ro";}','','Lebih rendah dari resistivitas sebenarnya','The presence of shale (clay minerals) in a reservoir rock will cause the measured resistivity (Rt) value to be:','a:4:{i:0;s:27:"Lower than true resistivity";i:1;s:28:"Higher than true resistivity";i:2;s:10:"Unaffected";i:3;s:11:"Equal to Ro";}','Lower than true resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000086','Jika salinitas air formasi meningkat, maka resistivitas air (Rw) akan:','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:7:"Menurun";i:1;s:9:"Meningkat";i:2;s:13:"Tidak berubah";i:3;s:26:"Menjadi konduktor sempurna";}','','Menurun','If the formation water salinity increases, the water resistivity (Rw) will:','a:4:{i:0;s:8:"Decrease";i:1;s:8:"Increase";i:2;s:16:"Remain unchanged";i:3;s:26:"Become a perfect conductor";}','Decrease','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000087','Parameter manakah yang merupakan komponen utama dalam Hukum Archie untuk menghitung saturasi air (Sw)?','multi','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:29:"Resistivitas air formasi (Rw)";i:1;s:35:"Resistivitas batuan sebenarnya (Rt)";i:2;s:16:"Porositas batuan";i:3;s:17:"Tekanan reservoir";}','','a:3:{i:0;s:29:"Resistivitas air formasi (Rw)";i:1;s:35:"Resistivitas batuan sebenarnya (Rt)";i:2;s:16:"Porositas batuan";}','Which parameters are the main components in Archie''s Law for calculating water saturation (Sw)?','a:4:{i:0;s:32:"Formation water resistivity (Rw)";i:1;s:26:"True rock resistivity (Rt)";i:2;s:13:"Rock porosity";i:3;s:18:"Reservoir pressure";}','a:3:{i:0;s:32:"Formation water resistivity (Rw)";i:1;s:26:"True rock resistivity (Rt)";i:2;s:13:"Rock porosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000088','Mengapa mineral lempung (clay) bersifat konduktif secara elektrik?','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:54:"Karena adanya pertukaran kation pada permukaan lempung";i:1;s:34:"Karena sifatnya yang tidak berpori";i:2;s:41:"Karena kandungan minyak yang terperangkap";i:3;s:41:"Karena struktur kristalnya yang kedap air";}','','Karena adanya pertukaran kation pada permukaan lempung','Why are clay minerals electrically conductive?','a:4:{i:0;s:42:"Due to cation exchange on the clay surface";i:1;s:30:"Due to their non-porous nature";i:2;s:26:"Due to trapped oil content";i:3;s:48:"Due to their water-impermeable crystal structure";}','Due to cation exchange on the clay surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000089','Pada kondisi reservoir yang bersih (clean sand), nilai resistivitas (Rt) berbanding terbalik dengan:','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:17:"Saturasi air (Sw)";i:1;s:9:"Porositas";i:2;s:13:"Salinitas air";i:3;s:9:"Kedalaman";}','','Saturasi air (Sw)','In a clean sand reservoir condition, the resistivity (Rt) value is inversely proportional to:','a:4:{i:0;s:21:"Water saturation (Sw)";i:1;s:8:"Porosity";i:2;s:14:"Water salinity";i:3;s:5:"Depth";}','Water saturation (Sw)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000090','Log manakah yang diklasifikasikan sebagai log nuklir untuk mengukur porositas formasi?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:11:"Density Log";i:1;s:15:"Resistivity Log";i:2;s:9:"Sonic Log";i:3;s:6:"SP Log";}','','Density Log','Which log is classified as a nuclear log to measure formation porosity?','a:4:{i:0;s:11:"Density Log";i:1;s:15:"Resistivity Log";i:2;s:9:"Sonic Log";i:3;s:6:"SP Log";}','Density Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000091','Prinsip utama yang diukur oleh log resistivitas untuk menentukan saturasi fluida adalah?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:28:"Konduktivitas listrik batuan";i:1;s:25:"Kecepatan gelombang suara";i:2;s:17:"Densitas elektron";i:3;s:20:"Radioaktivitas alami";}','','Konduktivitas listrik batuan','What is the main principle measured by the resistivity log to determine fluid saturation?','a:4:{i:0;s:31:"Electrical conductivity of rock";i:1;s:20:"Speed of sound waves";i:2;s:16:"Electron density";i:3;s:21:"Natural radioactivity";}','Electrical conductivity of rock','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000092','Data apa saja yang umumnya diperoleh dari log Gamma Ray?','multi','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:35:"Tingkat radioaktivitas alami batuan";i:1;s:27:"Identifikasi jenis litologi";i:2;s:23:"Kadar porositas efektif";i:3;s:18:"Kadar saturasi air";}','','a:2:{i:0;s:35:"Tingkat radioaktivitas alami batuan";i:1;s:27:"Identifikasi jenis litologi";}','What data are generally obtained from the Gamma Ray log?','a:4:{i:0;s:36:"Natural radioactivity level of rocks";i:1;s:29:"Lithology type identification";i:2;s:24:"Effective porosity level";i:3;s:22:"Water saturation level";}','a:2:{i:0;s:36:"Natural radioactivity level of rocks";i:1;s:29:"Lithology type identification";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000093','Parameter utama yang diukur oleh Sonic Log untuk analisis petrofisika adalah?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:21:"Interval transit time";i:1;s:19:"Resistivitas batuan";i:2;s:13:"Densitas bulk";i:3;s:17:"Potensial spontan";}','','Interval transit time','What is the main parameter measured by the Sonic Log for petrophysical analysis?','a:4:{i:0;s:21:"Interval transit time";i:1;s:16:"Rock resistivity";i:2;s:12:"Bulk density";i:3;s:21:"Spontaneous potential";}','Interval transit time','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000094','Apa fungsi utama dari depth control pada operasi wireline logging?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:55:"Memastikan kedalaman alat akurat terhadap kedalaman bor";i:1;s:27:"Menentukan porositas batuan";i:2;s:26:"Mengukur tekanan reservoir";i:3;s:27:"Mendeteksi zona hidrokarbon";}','','Memastikan kedalaman alat akurat terhadap kedalaman bor','What is the main function of depth control in wireline logging operations?','a:4:{i:0;s:55:"Ensuring tool depth accuracy relative to drilling depth";i:1;s:25:"Determining rock porosity";i:2;s:28:"Measuring reservoir pressure";i:3;s:27:"Detecting hydrocarbon zones";}','Ensuring tool depth accuracy relative to drilling depth','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000095','Jenis log manakah yang termasuk dalam kategori log elektrik?','multi','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:13:"Induction Log";i:1;s:9:"Laterolog";i:2;s:11:"Neutron Log";i:3;s:13:"Gamma Ray Log";}','','a:2:{i:0;s:13:"Induction Log";i:1;s:9:"Laterolog";}','Which log types are categorized as electrical logs?','a:4:{i:0;s:13:"Induction Log";i:1;s:9:"Laterolog";i:2;s:11:"Neutron Log";i:3;s:13:"Gamma Ray Log";}','a:2:{i:0;s:13:"Induction Log";i:1;s:9:"Laterolog";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000096','Log densitas mengukur sifat fisik batuan berdasarkan interaksi radiasi gamma dengan?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:22:"Elektron dalam formasi";i:1;s:15:"Butiran mineral";i:2;s:12:"Saturasi air";i:3;s:20:"Permeabilitas batuan";}','','Elektron dalam formasi','The density log measures rock physical properties based on gamma radiation interaction with?','a:4:{i:0;s:26:"Electrons in the formation";i:1;s:14:"Mineral grains";i:2;s:16:"Water saturation";i:3;s:17:"Rock permeability";}','Electrons in the formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000097','Apa yang dimaksud dengan resolusi vertikal pada alat wireline logging?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:63:"Ketebalan minimum lapisan batuan yang dapat dibedakan oleh alat";i:1;s:50:"Kedalaman maksimum alat dapat mencapai dasar sumur";i:2;s:35:"Kecepatan alat saat ditarik ke atas";i:3;s:30:"Akurasi pembacaan resistivitas";}','','Ketebalan minimum lapisan batuan yang dapat dibedakan oleh alat','What is meant by vertical resolution in a wireline logging tool?','a:4:{i:0;s:56:"Minimum rock layer thickness distinguishable by the tool";i:1;s:44:"Maximum depth the tool can reach in the well";i:2;s:32:"Speed of the tool during logging";i:3;s:31:"Accuracy of resistivity reading";}','Minimum rock layer thickness distinguishable by the tool','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000098','Log yang paling sensitif terhadap kandungan serpih (shale) dalam formasi adalah?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:13:"Gamma Ray Log";i:1;s:11:"Density Log";i:2;s:9:"Sonic Log";i:3;s:15:"Resistivity Log";}','','Gamma Ray Log','Which log is the most sensitive to shale content in the formation?','a:4:{i:0;s:13:"Gamma Ray Log";i:1;s:11:"Density Log";i:2;s:9:"Sonic Log";i:3;s:15:"Resistivity Log";}','Gamma Ray Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000099','Untuk mengukur porositas dengan menggunakan log neutron, interaksi apa yang terjadi?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:35:"Hamburan neutron oleh atom hidrogen";i:1;s:28:"Absorpsi foton oleh elektron";i:2;s:26:"Refraksi gelombang akustik";i:3;s:20:"Induksi arus listrik";}','','Hamburan neutron oleh atom hidrogen','To measure porosity using a neutron log, what interaction occurs?','a:4:{i:0;s:36:"Neutron scattering by hydrogen atoms";i:1;s:30:"Photon absorption by electrons";i:2;s:24:"Acoustic wave refraction";i:3;s:28:"Electrical current induction";}','Neutron scattering by hydrogen atoms','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000100','Apa fungsi utama dari kurva Spontaneous Potential (SP) dalam evaluasi formasi?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:51:"Membedakan batuan permeabel dari batuan impermeabel";i:1;s:52:"Mengukur kadar salinitas air formasi secara langsung";i:2;s:35:"Menentukan porositas efektif batuan";i:3;s:49:"Mendeteksi keberadaan hidrokarbon secara langsung";}','','Membedakan batuan permeabel dari batuan impermeabel','What is the primary function of the Spontaneous Potential (SP) curve in formation evaluation?','a:4:{i:0;s:54:"Differentiating permeable rocks from impermeable rocks";i:1;s:43:"Measuring formation water salinity directly";i:2;s:35:"Determining effective rock porosity";i:3;s:47:"Directly detecting the presence of hydrocarbons";}','Differentiating permeable rocks from impermeable rocks','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000101','Faktor apa saja yang memengaruhi defleksi log SP dalam sebuah formasi?','multi','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:49:"Perbedaan salinitas antara lumpur dan air formasi";i:1;s:20:"Permeabilitas batuan";i:2;s:24:"Ketebalan lapisan batuan";i:3;s:32:"Tekanan hidrostatik kolom lumpur";}','','a:3:{i:0;s:49:"Perbedaan salinitas antara lumpur dan air formasi";i:1;s:20:"Permeabilitas batuan";i:2;s:24:"Ketebalan lapisan batuan";}','What factors influence SP log deflection in a formation?','a:4:{i:0;s:54:"Difference in salinity between mud and formation water";i:1;s:17:"Rock permeability";i:2;s:13:"Bed thickness";i:3;s:38:"Hydrostatic pressure of the mud column";}','a:3:{i:0;s:54:"Difference in salinity between mud and formation water";i:1;s:17:"Rock permeability";i:2;s:13:"Bed thickness";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000102','Pada zona yang terinvasi (invaded zone) oleh mud filtrate yang bersifat fresh, bagaimana respon resistivitas yang terukur?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:32:"Resistivitas cenderung meningkat";i:1;s:30:"Resistivitas cenderung menurun";i:2;s:38:"Resistivitas tidak berubah sama sekali";i:3;s:24:"Resistivitas menjadi nol";}','','Resistivitas cenderung meningkat','In a zone invaded by fresh mud filtrate, how does the measured resistivity respond?','a:4:{i:0;s:29:"Resistivity tends to increase";i:1;s:29:"Resistivity tends to decrease";i:2;s:34:"Resistivity does not change at all";i:3;s:24:"Resistivity becomes zero";}','Resistivity tends to increase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000103','Alat log yang digunakan untuk mengukur resistivitas zona dalam (deep investigation) agar meminimalkan efek invasi adalah?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:19:"Induction Log (ILD)";i:1;s:21:"Laterolog Micro (LL8)";i:2;s:14:"Microlaterolog";i:3;s:13:"Proximity Log";}','','Induction Log (ILD)','Which logging tool is used to measure deep investigation resistivity to minimize invasion effects?','a:4:{i:0;s:19:"Induction Log (ILD)";i:1;s:21:"Laterolog Micro (LL8)";i:2;s:14:"Microlaterolog";i:3;s:13:"Proximity Log";}','Induction Log (ILD)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000104','Apa keuntungan utama dari penggunaan Array Induction Tool (AIT) dibandingkan Induction Log konvensional?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:70:"Memberikan resolusi vertikal yang lebih baik dan pembacaan multi-depth";i:1;s:53:"Hanya bisa digunakan di sumur dengan lumpur oil-based";i:2;s:31:"Tidak memerlukan kalibrasi alat";i:3;s:59:"Dapat mengukur porositas secara langsung tanpa alat neutron";}','','Memberikan resolusi vertikal yang lebih baik dan pembacaan multi-depth','What is the main advantage of using the Array Induction Tool (AIT) compared to conventional Induction Logs?','a:4:{i:0;s:60:"Provides better vertical resolution and multi-depth readings";i:1;s:39:"Can only be used in oil-based mud wells";i:2;s:33:"Does not require tool calibration";i:3;s:51:"Can measure porosity directly without neutron tools";}','Provides better vertical resolution and multi-depth readings','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000105','Fenomena apa yang terjadi ketika mud filtrate masuk ke dalam formasi permeabel dan mendorong fluida asli menjauh?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:6:"Invasi";i:1;s:6:"Difusi";i:2;s:8:"Ekspansi";i:3;s:11:"Presipitasi";}','','Invasi','What phenomenon occurs when mud filtrate enters a permeable formation and pushes the original fluids away?','a:4:{i:0;s:8:"Invasion";i:1;s:9:"Diffusion";i:2;s:9:"Expansion";i:3;s:13:"Precipitation";}','Invasion','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000106','Jika formasi mengandung hidrokarbon, bagaimana karakteristik pembacaan resistivitas dalam (Rt) dibandingkan dengan resistivitas zona terinvasi (Rxo)?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:27:"Rt lebih besar daripada Rxo";i:1;s:27:"Rt lebih kecil daripada Rxo";i:2;s:18:"Rt sama dengan Rxo";i:3;s:34:"Tidak ada hubungan antara keduanya";}','','Rt lebih besar daripada Rxo','If the formation contains hydrocarbons, how does the deep resistivity (Rt) reading compare to the flushed zone resistivity (Rxo)?','a:4:{i:0;s:22:"Rt is greater than Rxo";i:1;s:19:"Rt is less than Rxo";i:2;s:18:"Rt is equal to Rxo";i:3;s:37:"There is no relationship between them";}','Rt is greater than Rxo','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000107','Laterolog (LL) lebih efektif digunakan pada kondisi sumur seperti apa?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:28:"Lumpur konduktif (mud salin)";i:1;s:36:"Lumpur non-konduktif (oil-based mud)";i:2;s:28:"Formasi dengan porositas nol";i:3;s:19:"Formasi batuan beku";}','','Lumpur konduktif (mud salin)','In what well conditions is the Laterolog (LL) more effective?','a:4:{i:0;s:27:"Conductive mud (saline mud)";i:1;s:34:"Non-conductive mud (oil-based mud)";i:2;s:23:"Zero porosity formation";i:3;s:22:"Igneous rock formation";}','Conductive mud (saline mud)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000108','Apa yang dimaksud dengan zona ''flushed'' dalam konteks invasi?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:90:"Bagian terdekat dari lubang bor di mana hampir semua fluida formasi asli telah tergantikan";i:1;s:51:"Zona yang tidak terpengaruh oleh lumpur sama sekali";i:2;s:44:"Zona di mana mud cake terbentuk paling tebal";i:3;s:55:"Bagian formasi yang memiliki resistivitas paling tinggi";}','','Bagian terdekat dari lubang bor di mana hampir semua fluida formasi asli telah tergantikan','What is meant by the ''flushed'' zone in the context of invasion?','a:4:{i:0;s:95:"The part closest to the borehole where almost all original formation fluids have been displaced";i:1;s:33:"A zone not affected by mud at all";i:2;s:35:"The zone where mud cake is thickest";i:3;s:54:"The part of the formation with the highest resistivity";}','The part closest to the borehole where almost all original formation fluids have been displaced','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000109','Mengapa kurva resistivitas dangkal (shallow resistivity) sangat penting dalam interpretasi petrofisika?','multi','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:47:"Untuk menghitung saturasi air di zona terinvasi";i:1;s:48:"Untuk mengevaluasi kedalaman invasi mud filtrate";i:2;s:39:"Untuk menentukan porositas total batuan";i:3;s:65:"Sebagai perbandingan untuk koreksi invasi pada resistivitas dalam";}','','a:3:{i:0;s:47:"Untuk menghitung saturasi air di zona terinvasi";i:1;s:48:"Untuk mengevaluasi kedalaman invasi mud filtrate";i:2;s:65:"Sebagai perbandingan untuk koreksi invasi pada resistivitas dalam";}','Why is the shallow resistivity curve very important in petrophysical interpretation?','a:4:{i:0;s:49:"To calculate water saturation in the invaded zone";i:1;s:46:"To evaluate the depth of mud filtrate invasion";i:2;s:32:"To determine total rock porosity";i:3;s:59:"As a comparison for invasion correction on deep resistivity";}','a:3:{i:0;s:49:"To calculate water saturation in the invaded zone";i:1;s:46:"To evaluate the depth of mud filtrate invasion";i:2;s:59:"As a comparison for invasion correction on deep resistivity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000110','Log neutron mengukur porositas batuan dengan cara mendeteksi konsentrasi atom apa di dalam formasi?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:8:"Hidrogen";i:1;s:6:"Karbon";i:2;s:7:"Silikon";i:3;s:7:"Kalsium";}','','Hidrogen','The neutron log measures rock porosity by detecting the concentration of which atom in the formation?','a:4:{i:0;s:8:"Hydrogen";i:1;s:6:"Carbon";i:2;s:7:"Silicon";i:3;s:7:"Calcium";}','Hydrogen','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000111','Manakah pernyataan yang benar mengenai prinsip dasar log densitas?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:53:"Mengukur atenuasi sinar gamma akibat hamburan Compton";i:1;s:37:"Mengukur waktu tempuh gelombang suara";i:2;s:34:"Mengukur penyerapan neutron termal";i:3;s:37:"Mengukur resistivitas listrik formasi";}','','Mengukur atenuasi sinar gamma akibat hamburan Compton','Which statement is correct regarding the basic principle of the density log?','a:4:{i:0;s:56:"Measures gamma ray attenuation due to Compton scattering";i:1;s:34:"Measures acoustic wave travel time";i:2;s:35:"Measures thermal neutron absorption";i:3;s:41:"Measures formation electrical resistivity";}','Measures gamma ray attenuation due to Compton scattering','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000112','Log sonic (akustik) mengukur parameter apa untuk menentukan porositas?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:31:"Interval transit time (delta t)";i:1;s:13:"Densitas bulk";i:2;s:15:"Indeks hidrogen";i:3;s:20:"Radioaktivitas alami";}','','Interval transit time (delta t)','What parameter does the sonic (acoustic) log measure to determine porosity?','a:4:{i:0;s:31:"Interval transit time (delta t)";i:1;s:12:"Bulk density";i:2;s:14:"Hydrogen index";i:3;s:21:"Natural radioactivity";}','Interval transit time (delta t)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000113','Faktor apa saja yang dapat menyebabkan pembacaan log neutron menjadi terlalu tinggi (overestimate)?','multi','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:33:"Kehadiran mineral lempung (shale)";i:1;s:24:"Adanya gas dalam formasi";i:2;s:41:"Lubang sumur yang terlalu besar (washout)";i:3;s:33:"Salinitas air formasi yang tinggi";}','','a:2:{i:0;s:33:"Kehadiran mineral lempung (shale)";i:1;s:41:"Lubang sumur yang terlalu besar (washout)";}','Which factors can cause neutron log readings to be overestimated?','a:4:{i:0;s:33:"Presence of clay minerals (shale)";i:1;s:32:"Presence of gas in the formation";i:2;s:29:"Over-sized borehole (washout)";i:3;s:29:"High formation water salinity";}','a:2:{i:0;s:33:"Presence of clay minerals (shale)";i:1;s:29:"Over-sized borehole (washout)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000114','Persamaan Wyllie Time-Average digunakan untuk menghitung porositas berdasarkan data dari log apa?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:9:"Log sonic";i:1;s:12:"Log densitas";i:2;s:11:"Log neutron";i:3;s:11:"Log kaliper";}','','Log sonic','The Wyllie Time-Average equation is used to calculate porosity based on data from which log?','a:4:{i:0;s:9:"Sonic log";i:1;s:11:"Density log";i:2;s:11:"Neutron log";i:3;s:11:"Caliper log";}','Sonic log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000115','Pada formasi batupasir yang mengandung gas, apa dampak yang terlihat pada plot silang (crossplot) densitas-neutron?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:55:"Separasi ''gas effect'' (neutron rendah, densitas rendah)";i:1;s:55:"Separasi ''gas effect'' (neutron rendah, densitas tinggi)";i:2;s:36:"Neutron dan densitas tetap berhimpit";i:3;s:43:"Peningkatan porositas densitas yang ekstrem";}','','Separasi ''gas effect'' (neutron rendah, densitas rendah)','In a gas-bearing sandstone formation, what effect is visible on the density-neutron crossplot?','a:4:{i:0;s:50:"''Gas effect'' separation (low neutron, low density)";i:1;s:51:"''Gas effect'' separation (low neutron, high density)";i:2;s:37:"Neutron and density remain coincident";i:3;s:36:"Extreme increase in density porosity";}','''Gas effect'' separation (low neutron, low density)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000116','Apa yang dimaksud dengan ''Secondary Porosity Index'' (SPI) dalam evaluasi log sonic?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:88:"Selisih antara porositas total (dari densitas/neutron) dan porositas primer (dari sonic)";i:1;s:63:"Porositas yang diukur hanya pada lubang sumur yang tidak stabil";i:2;s:42:"Porositas yang dihitung dari log gamma ray";i:3;s:42:"Porositas batuan akibat tekanan overburden";}','','Selisih antara porositas total (dari densitas/neutron) dan porositas primer (dari sonic)','What is meant by ''Secondary Porosity Index'' (SPI) in sonic log evaluation?','a:4:{i:0;s:94:"The difference between total porosity (from density/neutron) and primary porosity (from sonic)";i:1;s:44:"Porosity measured only in unstable boreholes";i:2;s:39:"Porosity calculated from gamma ray logs";i:3;s:40:"Rock porosity due to overburden pressure";}','The difference between total porosity (from density/neutron) and primary porosity (from sonic)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000117','Manakah pernyataan yang benar mengenai pengaruh litologi terhadap log densitas?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:61:"Log densitas sangat sensitif terhadap densitas matriks batuan";i:1;s:49:"Log densitas tidak terpengaruh oleh jenis mineral";i:2;s:42:"Log densitas hanya dipengaruhi oleh fluida";i:3;s:74:"Log densitas selalu memberikan porositas yang benar tanpa koreksi litologi";}','','Log densitas sangat sensitif terhadap densitas matriks batuan','Which statement is correct regarding the effect of lithology on the density log?','a:4:{i:0;s:56:"The density log is very sensitive to rock matrix density";i:1;s:45:"The density log is unaffected by mineral type";i:2;s:42:"The density log is only affected by fluids";i:3;s:77:"The density log always provides correct porosity without lithology correction";}','The density log is very sensitive to rock matrix density','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000118','Sumber radioaktif yang umumnya digunakan pada alat log densitas adalah?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:10:"Cesium-137";i:1;s:13:"Americium-241";i:2;s:9:"Cobalt-60";i:3;s:11:"Uranium-238";}','','Cesium-137','The radioactive source commonly used in density logging tools is?','a:4:{i:0;s:10:"Cesium-137";i:1;s:13:"Americium-241";i:2;s:9:"Cobalt-60";i:3;s:11:"Uranium-238";}','Cesium-137','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000119','Mengapa penggunaan log densitas dan log neutron secara bersamaan sangat krusial dalam evaluasi formasi?','multi','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:33:"Untuk menentukan litologi formasi";i:1;s:27:"Untuk mendeteksi adanya gas";i:2;s:44:"Untuk mengukur permeabilitas secara langsung";i:3;s:39:"Untuk mengidentifikasi jenis clay shale";}','','a:2:{i:0;s:33:"Untuk menentukan litologi formasi";i:1;s:27:"Untuk mendeteksi adanya gas";}','Why is the combined use of density and neutron logs crucial in formation evaluation?','a:4:{i:0;s:32:"To determine formation lithology";i:1;s:29:"To detect the presence of gas";i:2;s:32:"To measure permeability directly";i:3;s:28:"To identify shale clay types";}','a:2:{i:0;s:32:"To determine formation lithology";i:1;s:29:"To detect the presence of gas";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000120','Parameter utama yang digunakan untuk menghitung volume shale (Vsh) menggunakan log Gamma Ray adalah...','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:22:"Indeks Gamma Ray (IGR)";i:1;s:12:"Saturasi air";i:2;s:23:"Permeabilitas intrinsik";i:3;s:18:"Porositas sekunder";}','','Indeks Gamma Ray (IGR)','The main parameter used to calculate shale volume (Vsh) using Gamma Ray logs is...','a:4:{i:0;s:21:"Gamma Ray Index (IGR)";i:1;s:16:"Water saturation";i:2;s:22:"Intrinsic permeability";i:3;s:18:"Secondary porosity";}','Gamma Ray Index (IGR)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000121','Faktor apa saja yang harus dipertimbangkan saat melakukan koreksi shale pada perhitungan porositas efektif?','multi','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:18:"Volume shale (Vsh)";i:1;s:21:"Jenis mineral lempung";i:2;s:24:"Saturasi minyak residual";i:3;s:30:"Kekompakan batuan (compaction)";}','','a:2:{i:0;s:18:"Volume shale (Vsh)";i:1;s:21:"Jenis mineral lempung";}','What factors must be considered when applying shale corrections to effective porosity calculations?','a:4:{i:0;s:18:"Shale volume (Vsh)";i:1;s:17:"Clay mineral type";i:2;s:23:"Residual oil saturation";i:3;s:15:"Rock compaction";}','a:2:{i:0;s:18:"Shale volume (Vsh)";i:1;s:17:"Clay mineral type";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000122','Pada kondisi bersih (clean sand), berapakah nilai IGR yang ideal?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:1:"0";i:1;s:3:"0.5";i:2;s:1:"1";i:3;s:1:"2";}','','0','In clean sand conditions, what is the ideal IGR value?','a:4:{i:0;s:1:"0";i:1;s:3:"0.5";i:2;s:1:"1";i:3;s:1:"2";}','0','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000123','Apa dampak keberadaan shale terhadap porositas total yang terukur oleh alat logging?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:64:"Menyebabkan porositas terbaca lebih besar dari porositas efektif";i:1;s:23:"Tidak memberikan dampak";i:2;s:35:"Menghilangkan efek porositas primer";i:3;s:26:"Meningkatkan permeabilitas";}','','Menyebabkan porositas terbaca lebih besar dari porositas efektif','What is the impact of shale presence on the total porosity measured by logging tools?','a:4:{i:0;s:57:"Causes porosity to be read higher than effective porosity";i:1;s:13:"Has no impact";i:2;s:35:"Eliminates primary porosity effects";i:3;s:22:"Increases permeability";}','Causes porosity to be read higher than effective porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000124','Rumus linear sederhana untuk menghitung Vsh adalah Vsh = (GRlog - GRclean) / (GRshale - GRclean). Apa batasan utama rumus ini?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:65:"Sering memberikan nilai Vsh yang terlalu optimis (terlalu rendah)";i:1;s:31:"Tidak memerlukan nilai GR clean";i:2;s:35:"Hanya berlaku untuk batuan karbonat";i:3;s:28:"Memerlukan data tekanan pori";}','','Sering memberikan nilai Vsh yang terlalu optimis (terlalu rendah)','The simple linear formula for calculating Vsh is Vsh = (GRlog - GRclean) / (GRshale - GRclean). What is the main limitation of this formula?','a:4:{i:0;s:53:"Often provides overly optimistic (too low) Vsh values";i:1;s:32:"Does not require GR clean values";i:2;s:31:"Only applies to carbonate rocks";i:3;s:27:"Requires pore pressure data";}','Often provides overly optimistic (too low) Vsh values','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000125','Manakah pernyataan yang benar mengenai porositas efektif?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:88:"Bagian dari porositas total yang saling terhubung dan tidak terikat oleh mineral lempung";i:1;s:30:"Total volume pori dalam batuan";i:2;s:45:"Porositas yang dihitung sebelum koreksi shale";i:3;s:43:"Porositas yang hanya diukur di laboratorium";}','','Bagian dari porositas total yang saling terhubung dan tidak terikat oleh mineral lempung','Which statement is correct regarding effective porosity?','a:4:{i:0;s:80:"The part of total porosity that is interconnected and not bound by clay minerals";i:1;s:29:"The total pore volume in rock";i:2;s:43:"Porosity calculated before shale correction";i:3;s:40:"Porosity measured only in the laboratory";}','The part of total porosity that is interconnected and not bound by clay minerals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000126','Kapan penggunaan koreksi shale non-linear (seperti rumus Steiber atau Clavier) lebih disarankan?','multi','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:37:"Pada formasi muda atau unconsolidated";i:1;s:61:"Ketika data GR menunjukkan adanya variasi shale yang kompleks";i:2;s:39:"Pada formasi karbonat yang sangat murni";i:3;s:43:"Ketika nilai GR log konstan sepanjang sumur";}','','a:2:{i:0;s:37:"Pada formasi muda atau unconsolidated";i:1;s:61:"Ketika data GR menunjukkan adanya variasi shale yang kompleks";}','When is the use of non-linear shale corrections (such as Steiber or Clavier formulas) more recommended?','a:4:{i:0;s:37:"In young or unconsolidated formations";i:1;s:43:"When GR data shows complex shale variations";i:2;s:33:"In very pure carbonate formations";i:3;s:51:"When GR log values are constant throughout the well";}','a:2:{i:0;s:37:"In young or unconsolidated formations";i:1;s:43:"When GR data shows complex shale variations";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000127','Log SP (Spontaneous Potential) dapat digunakan untuk menentukan volume shale dengan cara membandingkan defleksi SP pada zona formasi dengan...','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:41:"Defleksi SP pada zona shale (SSP dan PSP)";i:1;s:19:"Resistivitas batuan";i:2;s:13:"Densitas bulk";i:3;s:22:"Nilai neutron porosity";}','','Defleksi SP pada zona shale (SSP dan PSP)','The SP log can be used to determine shale volume by comparing the SP deflection in the formation zone with...','a:4:{i:0;s:45:"SP deflection in the shale zone (SSP and PSP)";i:1;s:16:"Rock resistivity";i:2;s:12:"Bulk density";i:3;s:22:"Neutron porosity value";}','SP deflection in the shale zone (SSP and PSP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000128','Apa pengaruh air terikat lempung (bound water) pada perhitungan porositas dari log densitas?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:62:"Menyebabkan nilai porositas yang terhitung menjadi lebih besar";i:1;s:33:"Menurunkan nilai densitas matriks";i:2;s:24:"Tidak mempengaruhi hasil";i:3;s:29:"Membuat porositas menjadi nol";}','','Menyebabkan nilai porositas yang terhitung menjadi lebih besar','What is the effect of clay-bound water on porosity calculations from density logs?','a:4:{i:0;s:49:"Causes the calculated porosity value to be higher";i:1;s:31:"Lowers the matrix density value";i:2;s:27:"Does not affect the results";i:3;s:19:"Makes porosity zero";}','Causes the calculated porosity value to be higher','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000129','Untuk menghitung porositas efektif dari porositas total, parameter apa yang biasanya dikurangkan?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:62:"Produk dari volume shale (Vsh) dan porositas shale (phi_shale)";i:1;s:27:"Nilai permeabilitas absolut";i:2;s:17:"Saturasi air sisa";i:3;s:15:"Tekanan kapiler";}','','Produk dari volume shale (Vsh) dan porositas shale (phi_shale)','To calculate effective porosity from total porosity, what parameter is usually subtracted?','a:4:{i:0;s:64:"The product of shale volume (Vsh) and shale porosity (phi_shale)";i:1;s:27:"Absolute permeability value";i:2;s:25:"Residual water saturation";i:3;s:18:"Capillary pressure";}','The product of shale volume (Vsh) and shale porosity (phi_shale)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000130','Dalam persamaan Archie, berapakah nilai eksponen sementasi (m) yang umum digunakan untuk batuan pasir (sandstone) yang terkonsolidasi?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:3:"1.0";i:1;s:3:"1.5";i:2;s:3:"2.0";i:3;s:3:"3.0";}','','2.0','In the Archie equation, what is the typical cementation exponent (m) value used for consolidated sandstone?','a:4:{i:0;s:3:"1.0";i:1;s:3:"1.5";i:2;s:3:"2.0";i:3;s:3:"3.0";}','2.0','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000131','Faktor formasi (F) didefinisikan sebagai rasio antara resistivitas batuan yang jenuh air 100% (Ro) terhadap apa?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:27:"Resistivitas filtrat lumpur";i:1;s:24:"Resistivitas air formasi";i:2;s:25:"Resistivitas batuan total";i:3;s:27:"Resistivitas zona terinvasi";}','','Resistivitas air formasi','Formation factor (F) is defined as the ratio between the resistivity of a 100% water-saturated rock (Ro) and what?','a:4:{i:0;s:24:"Mud filtrate resistivity";i:1;s:27:"Formation water resistivity";i:2;s:22:"Total rock resistivity";i:3;s:24:"Invaded zone resistivity";}','Formation water resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000132','Parameter apa saja yang secara langsung mempengaruhi besarnya faktor formasi (F) dalam model Archie?','multi','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:9:"Porositas";i:1;s:22:"Eksponen sementasi (m)";i:2;s:17:"Saturasi air (Sw)";i:3;s:22:"Faktor tortuositas (a)";}','','a:3:{i:0;s:9:"Porositas";i:1;s:22:"Eksponen sementasi (m)";i:2;s:22:"Faktor tortuositas (a)";}','Which parameters directly affect the formation factor (F) in the Archie model?','a:4:{i:0;s:8:"Porosity";i:1;s:24:"Cementation exponent (m)";i:2;s:21:"Water saturation (Sw)";i:3;s:21:"Tortuosity factor (a)";}','a:3:{i:0;s:8:"Porosity";i:1;s:24:"Cementation exponent (m)";i:2;s:21:"Tortuosity factor (a)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000133','Jika resistivitas air formasi (Rw) meningkat, maka untuk nilai porositas yang tetap, bagaimanakah pengaruhnya terhadap resistivitas batuan (Ro)?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:17:"Ro akan meningkat";i:1;s:15:"Ro akan menurun";i:2;s:16:"Ro tidak berubah";i:3;s:28:"Ro menjadi tidak terdefinisi";}','','Ro akan meningkat','If the formation water resistivity (Rw) increases, what is the effect on the rock resistivity (Ro) assuming constant porosity?','a:4:{i:0;s:16:"Ro will increase";i:1;s:16:"Ro will decrease";i:2;s:24:"Ro will remain unchanged";i:3;s:20:"Ro becomes undefined";}','Ro will increase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000134','Apa yang dimaksud dengan indeks resistivitas (I) dalam hubungan Archie?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:20:"Rasio Rt terhadap Ro";i:1;s:20:"Rasio Rw terhadap Rt";i:2;s:20:"Rasio Rt terhadap Rw";i:3;s:27:"Rasio Sw terhadap porositas";}','','Rasio Rt terhadap Ro','What is meant by the resistivity index (I) in the Archie relationship?','a:4:{i:0;s:17:"Ratio of Rt to Ro";i:1;s:17:"Ratio of Rw to Rt";i:2;s:17:"Ratio of Rt to Rw";i:3;s:23:"Ratio of Sw to porosity";}','Ratio of Rt to Ro','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000135','Dalam persamaan Archie, eksponen saturasi (n) umumnya diasumsikan bernilai berapa untuk kebanyakan reservoir?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:3:"1.0";i:1;s:3:"2.0";i:2;s:3:"3.0";i:3;s:3:"0.5";}','','2.0','In the Archie equation, the saturation exponent (n) is generally assumed to be what value for most reservoirs?','a:4:{i:0;s:3:"1.0";i:1;s:3:"2.0";i:2;s:3:"3.0";i:3;s:3:"0.5";}','2.0','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000136','Batasan utama penggunaan persamaan Archie adalah?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:58:"Hanya berlaku untuk batuan dengan kandungan lempung tinggi";i:1;s:67:"Hanya berlaku untuk formasi yang tidak mengandung mineral konduktif";i:2;s:36:"Hanya berlaku pada kedalaman dangkal";i:3;s:45:"Hanya berlaku jika hidrokarbon dalam fase gas";}','','Hanya berlaku untuk formasi yang tidak mengandung mineral konduktif','What is the main limitation of using the Archie equation?','a:4:{i:0;s:38:"Only valid for high clay content rocks";i:1;s:53:"Only valid for formations without conductive minerals";i:2;s:28:"Only valid at shallow depths";i:3;s:47:"Only valid if hydrocarbons are in the gas phase";}','Only valid for formations without conductive minerals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000137','Jika nilai indeks resistivitas (I) adalah 4, dan eksponen saturasi (n) adalah 2, berapakah saturasi air (Sw) batuan tersebut?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:4:"0.25";i:1;s:4:"0.50";i:2;s:4:"0.75";i:3;s:4:"0.10";}','','0.50','If the resistivity index (I) is 4, and the saturation exponent (n) is 2, what is the water saturation (Sw) of the rock?','a:4:{i:0;s:4:"0.25";i:1;s:4:"0.50";i:2;s:4:"0.75";i:3;s:4:"0.10";}','0.50','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000138','Parameter ''a'' dalam persamaan Archie (F = a / phi^m) merepresentasikan apa?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:18:"Eksponen sementasi";i:1;s:21:"Koefisien tortuositas";i:2;s:12:"Saturasi air";i:3;s:20:"Resistivitas formasi";}','','Koefisien tortuositas','What does the parameter ''a'' in the Archie equation (F = a / phi^m) represent?','a:4:{i:0;s:20:"Cementation exponent";i:1;s:22:"Tortuosity coefficient";i:2;s:16:"Water saturation";i:3;s:21:"Formation resistivity";}','Tortuosity coefficient','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000139','Manakah pernyataan yang benar mengenai hubungan resistivitas batuan (Rt) dengan saturasi air (Sw) menurut Archie?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:29:"Rt berbanding lurus dengan Sw";i:1;s:34:"Rt berbanding terbalik dengan Sw^n";i:2;s:28:"Rt tidak dipengaruhi oleh Sw";i:3;s:31:"Rt berbanding lurus dengan Sw^2";}','','Rt berbanding terbalik dengan Sw^n','Which statement is correct regarding the relationship between rock resistivity (Rt) and water saturation (Sw) according to Archie?','a:4:{i:0;s:33:"Rt is directly proportional to Sw";i:1;s:36:"Rt is inversely proportional to Sw^n";i:2;s:26:"Rt is not influenced by Sw";i:3;s:35:"Rt is directly proportional to Sw^2";}','Rt is inversely proportional to Sw^n','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000140','Apakah perbedaan utama antara net reservoir dan net pay dalam evaluasi formasi?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:128:"Net reservoir mencakup seluruh zona berpori, sedangkan net pay mencakup zona berpori yang memiliki saturasi hidrokarbon ekonomis";i:1;s:85:"Net pay mencakup seluruh zona permeabel, sedangkan net reservoir hanya zona produktif";i:2;s:35:"Tidak ada perbedaan antara keduanya";i:3;s:63:"Net reservoir hanya mencakup batuan dengan permeabilitas tinggi";}','','Net reservoir mencakup seluruh zona berpori, sedangkan net pay mencakup zona berpori yang memiliki saturasi hidrokarbon ekonomis','What is the main difference between net reservoir and net pay in formation evaluation?','a:4:{i:0;s:113:"Net reservoir includes all porous zones, while net pay includes porous zones with economic hydrocarbon saturation";i:1;s:88:"Net pay includes all permeable zones, while net reservoir only includes productive zones";i:2;s:35:"There is no difference between them";i:3;s:51:"Net reservoir only includes high permeability rocks";}','Net reservoir includes all porous zones, while net pay includes porous zones with economic hydrocarbon saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000141','Dalam penentuan cut-off, parameter apa saja yang biasanya digunakan untuk mendefinisikan net reservoir?','multi','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:17:"Porositas minimum";i:1;s:21:"Saturasi air maksimum";i:2;s:21:"Volume shale maksimum";i:3;s:15:"Tekanan formasi";}','','a:2:{i:0;s:17:"Porositas minimum";i:1;s:21:"Volume shale maksimum";}','In determining cut-offs, which parameters are typically used to define net reservoir?','a:4:{i:0;s:16:"Minimum porosity";i:1;s:24:"Maximum water saturation";i:2;s:20:"Maximum shale volume";i:3;s:18:"Formation pressure";}','a:2:{i:0;s:16:"Minimum porosity";i:1;s:20:"Maximum shale volume";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000142','Apa tujuan utama dari korelasi log antar sumur dalam sebuah lapangan?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:46:"Untuk memahami kesinambungan lateral reservoir";i:1;s:43:"Untuk menghitung cadangan secara volumetrik";i:2;s:49:"Untuk menentukan jenis fluida di dalam lubang bor";i:3;s:32:"Untuk mengkalibrasi alat logging";}','','Untuk memahami kesinambungan lateral reservoir','What is the primary purpose of log correlation between wells in a field?','a:4:{i:0;s:53:"To understand the lateral continuity of the reservoir";i:1;s:36:"To calculate reserves volumetrically";i:2;s:40:"To determine fluid types in the borehole";i:3;s:26:"To calibrate logging tools";}','To understand the lateral continuity of the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000143','Log apa yang paling umum digunakan sebagai penanda (marker) utama dalam korelasi log untuk menentukan zonasi?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:13:"Log Gamma Ray";i:1;s:12:"Log Densitas";i:2;s:11:"Log Neutron";i:3;s:16:"Log Resistivitas";}','','Log Gamma Ray','Which log is most commonly used as a primary marker in log correlation to determine zonation?','a:4:{i:0;s:13:"Gamma Ray log";i:1;s:11:"Density log";i:2;s:11:"Neutron log";i:3;s:15:"Resistivity log";}','Gamma Ray log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000144','Mengapa penentuan cut-off saturasi air (Sw) sangat krusial dalam perhitungan net pay?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:57:"Karena Sw menentukan batas ekonomis akumulasi hidrokarbon";i:1;s:50:"Karena Sw selalu berbanding lurus dengan porositas";i:2;s:48:"Karena Sw tidak berpengaruh pada volume cadangan";i:3;s:52:"Karena Sw digunakan untuk mengkalibrasi log densitas";}','','Karena Sw menentukan batas ekonomis akumulasi hidrokarbon','Why is the determination of water saturation (Sw) cut-off crucial in net pay calculations?','a:4:{i:0;s:68:"Because Sw determines the economic limit of hydrocarbon accumulation";i:1;s:54:"Because Sw is always directly proportional to porosity";i:2;s:42:"Because Sw has no effect on reserve volume";i:3;s:47:"Because Sw is used to calibrate the density log";}','Because Sw determines the economic limit of hydrocarbon accumulation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000145','Apa dampak menetapkan nilai cut-off volume shale (Vsh) yang terlalu rendah?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:20:"Overestimasi net pay";i:1;s:21:"Underestimasi net pay";i:2;s:29:"Tidak ada dampak pada net pay";i:3;s:27:"Peningkatan porositas total";}','','Underestimasi net pay','What is the impact of setting a shale volume (Vsh) cut-off value that is too low?','a:4:{i:0;s:25:"Overestimation of net pay";i:1;s:26:"Underestimation of net pay";i:2;s:20:"No impact on net pay";i:3;s:26:"Increase in total porosity";}','Underestimation of net pay','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000146','Dalam penyajian hasil evaluasi petrofisika (composite log), data apa yang harus ditampilkan bersamaan?','multi','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:14:"Kurva log asli";i:1;s:39:"Hasil interpretasi (porositas, Sw, Vsh)";i:2;s:38:"Zona net pay yang telah diidentifikasi";i:3;s:17:"Harga jual minyak";}','','a:3:{i:0;s:14:"Kurva log asli";i:1;s:39:"Hasil interpretasi (porositas, Sw, Vsh)";i:2;s:38:"Zona net pay yang telah diidentifikasi";}','In the presentation of petrophysical evaluation results (composite log), what data should be displayed together?','a:4:{i:0;s:19:"Original log curves";i:1;s:42:"Interpretation results (porosity, Sw, Vsh)";i:2;s:24:"Identified net pay zones";i:3;s:17:"Oil selling price";}','a:3:{i:0;s:19:"Original log curves";i:1;s:42:"Interpretation results (porosity, Sw, Vsh)";i:2;s:24:"Identified net pay zones";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000147','Apa yang dimaksud dengan korelasi stratigrafi dalam konteks zonasi log?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:91:"Menghubungkan interval yang memiliki umur geologi atau karakteristik deposisional yang sama";i:1;s:56:"Menghubungkan sumur berdasarkan kedalaman yang sama saja";i:2;s:62:"Menghubungkan sumur berdasarkan tingkat resistivitas tertinggi";i:3;s:48:"Menghubungkan zona berdasarkan tekanan reservoir";}','','Menghubungkan interval yang memiliki umur geologi atau karakteristik deposisional yang sama','What is meant by stratigraphic correlation in the context of log zonation?','a:4:{i:0;s:86:"Connecting intervals that have the same geological age or depositional characteristics";i:1;s:45:"Connecting wells based on the same depth only";i:2;s:56:"Connecting wells based on the highest resistivity levels";i:3;s:44:"Connecting zones based on reservoir pressure";}','Connecting intervals that have the same geological age or depositional characteristics','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000148','Jika sebuah lapisan memiliki porositas 10% dan batas cut-off porositas perusahaan adalah 12%, maka lapisan tersebut dikategorikan sebagai apa?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:13:"Non-reservoir";i:1;s:13:"Net reservoir";i:2;s:7:"Net pay";i:3;s:22:"High-quality reservoir";}','','Non-reservoir','If a layer has a porosity of 10% and the company''s porosity cut-off is 12%, how is that layer categorized?','a:4:{i:0;s:13:"Non-reservoir";i:1;s:13:"Net reservoir";i:2;s:7:"Net pay";i:3;s:22:"High-quality reservoir";}','Non-reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000149','Apa fungsi utama dari pembuatan zonasi formasi sebelum melakukan perhitungan volumetrik?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:70:"Untuk mengelompokkan reservoir dengan properti petrofisika yang serupa";i:1;s:35:"Untuk mempercepat proses pengeboran";i:2;s:34:"Untuk meningkatkan tekanan formasi";i:3;s:29:"Untuk mengurangi saturasi air";}','','Untuk mengelompokkan reservoir dengan properti petrofisika yang serupa','What is the main function of creating formation zonation before performing volumetric calculations?','a:4:{i:0;s:57:"To group reservoirs with similar petrophysical properties";i:1;s:34:"To accelerate the drilling process";i:2;s:30:"To increase formation pressure";i:3;s:26:"To reduce water saturation";}','To group reservoirs with similar petrophysical properties','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000150','Parameter utama apa yang mendefinisikan perbedaan tekanan antara dua fluida yang tidak bercampur dalam ruang pori?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:15:"Tekanan kapiler";i:1;s:15:"Tekanan formasi";i:2;s:18:"Tekanan overburden";i:3;s:19:"Tekanan hidrostatik";}','','Tekanan kapiler','What is the main parameter that defines the pressure difference between two immiscible fluids in a pore space?','a:4:{i:0;s:18:"Capillary pressure";i:1;s:18:"Formation pressure";i:2;s:19:"Overburden pressure";i:3;s:20:"Hydrostatic pressure";}','Capillary pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000151','Faktor apa saja yang memengaruhi besarnya tekanan kapiler dalam medium berpori?','multi','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:18:"Tegangan antarmuka";i:1;s:12:"Sudut kontak";i:2;s:21:"Permeabilitas absolut";i:3;s:14:"Jari-jari pori";}','','a:3:{i:0;s:18:"Tegangan antarmuka";i:1;s:12:"Sudut kontak";i:2;s:14:"Jari-jari pori";}','What factors influence the magnitude of capillary pressure in a porous medium?','a:4:{i:0;s:19:"Interfacial tension";i:1;s:13:"Contact angle";i:2;s:21:"Absolute permeability";i:3;s:11:"Pore radius";}','a:3:{i:0;s:19:"Interfacial tension";i:1;s:13:"Contact angle";i:2;s:11:"Pore radius";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000152','Dalam sistem batuan oil-wet, manakah pernyataan yang benar mengenai sudut kontak (theta)?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:35:"Sudut kontak kurang dari 90 derajat";i:1;s:34:"Sudut kontak sama dengan 0 derajat";i:2;s:40:"Sudut kontak lebih besar dari 90 derajat";i:3;s:43:"Sudut kontak tidak mempengaruhi wettability";}','','Sudut kontak lebih besar dari 90 derajat','In an oil-wet rock system, which statement regarding the contact angle (theta) is correct?','a:4:{i:0;s:37:"Contact angle is less than 90 degrees";i:1;s:35:"Contact angle is equal to 0 degrees";i:2;s:40:"Contact angle is greater than 90 degrees";i:3;s:41:"Contact angle does not affect wettability";}','Contact angle is greater than 90 degrees','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000153','Apa yang terjadi pada ketinggian di atas Free Water Level (FWL) jika jari-jari pori batuan semakin kecil?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:30:"Ketinggian akan semakin rendah";i:1;s:30:"Ketinggian akan semakin tinggi";i:2;s:24:"Ketinggian tidak berubah";i:3;s:27:"Tekanan kapiler menjadi nol";}','','Ketinggian akan semakin tinggi','What happens to the height above the Free Water Level (FWL) if the pore radius of the rock becomes smaller?','a:4:{i:0;s:20:"Height will be lower";i:1;s:21:"Height will be higher";i:2;s:24:"Height remains unchanged";i:3;s:31:"Capillary pressure becomes zero";}','Height will be higher','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000154','Manakah pernyataan yang paling tepat mendefinisikan Free Water Level (FWL)?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:45:"Level di mana tekanan kapiler sama dengan nol";i:1;s:46:"Level di mana saturasi air mencapai 100 persen";i:2;s:56:"Level di mana minyak dan air memiliki densitas yang sama";i:3;s:56:"Level di mana tekanan hidrostatik minyak sama dengan nol";}','','Level di mana tekanan kapiler sama dengan nol','Which statement best defines the Free Water Level (FWL)?','a:4:{i:0;s:46:"The level where capillary pressure equals zero";i:1;s:52:"The level where water saturation reaches 100 percent";i:2;s:51:"The level where oil and water have the same density";i:3;s:52:"The level where oil hydrostatic pressure equals zero";}','The level where capillary pressure equals zero','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000155','Bagaimana hubungan antara tegangan antarmuka (IFT) dengan tekanan kapiler?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:16:"Berbanding lurus";i:1;s:19:"Berbanding terbalik";i:2;s:18:"Tidak ada hubungan";i:3;s:20:"Eksponensial negatif";}','','Berbanding lurus','What is the relationship between interfacial tension (IFT) and capillary pressure?','a:4:{i:0;s:21:"Directly proportional";i:1;s:22:"Inversely proportional";i:2;s:15:"No relationship";i:3;s:20:"Negative exponential";}','Directly proportional','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000156','Fenomena dimana fluida membasahi permukaan batuan lebih dominan dibandingkan fluida lainnya disebut sebagai?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:11:"Wettability";i:1;s:13:"Permeabilitas";i:2;s:9:"Porositas";i:3;s:16:"Transmisibilitas";}','','Wettability','The phenomenon where a fluid wets the rock surface more dominantly than the other fluid is called?','a:4:{i:0;s:11:"Wettability";i:1;s:12:"Permeability";i:2;s:8:"Porosity";i:3;s:16:"Transmissibility";}','Wettability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000157','Manakah dari berikut ini yang merupakan satuan umum untuk tekanan kapiler?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:3:"psi";i:1;s:5:"Darcy";i:2;s:7:"Dyne/cm";i:3;s:6:"Persen";}','','psi','Which of the following is a common unit for capillary pressure?','a:4:{i:0;s:3:"psi";i:1;s:5:"Darcy";i:2;s:7:"Dyne/cm";i:3;s:7:"Percent";}','psi','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000158','Dalam zona transisi di atas FWL, apa yang terjadi pada saturasi air terhadap ketinggian?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:52:"Saturasi air menurun seiring bertambahnya ketinggian";i:1;s:54:"Saturasi air meningkat seiring bertambahnya ketinggian";i:2;s:26:"Saturasi air tetap konstan";i:3;s:33:"Saturasi air menjadi nol seketika";}','','Saturasi air menurun seiring bertambahnya ketinggian','In the transition zone above the FWL, what happens to water saturation with respect to height?','a:4:{i:0;s:49:"Water saturation decreases with increasing height";i:1;s:49:"Water saturation increases with increasing height";i:2;s:33:"Water saturation remains constant";i:3;s:39:"Water saturation becomes zero instantly";}','Water saturation decreases with increasing height','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000159','Apa yang dimaksud dengan ''Spontaneous Imbibition'' dalam konteks wettability?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:56:"Proses masuknya fase pembasah ke dalam pori secara alami";i:1;s:46:"Proses pengeluaran minyak dengan injeksi kimia";i:2;s:58:"Pengukuran permeabilitas relatif pada kondisi steady state";i:3;s:36:"Proses penguapan fluida di reservoir";}','','Proses masuknya fase pembasah ke dalam pori secara alami','What is meant by ''Spontaneous Imbibition'' in the context of wettability?','a:4:{i:0;s:57:"The process of the wetting phase entering pores naturally";i:1;s:52:"The process of oil recovery using chemical injection";i:2;s:66:"Measurement of relative permeability under steady-state conditions";i:3;s:49:"The process of fluid evaporation in the reservoir";}','The process of the wetting phase entering pores naturally','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000160','Metode pengukuran tekanan kapiler yang menggunakan tekanan gas untuk menekan merkuri ke dalam pori-pori sampel batuan kering adalah?','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:17:"Mercury Injection";i:1;s:12:"Porous Plate";i:2;s:10:"Centrifuge";i:3;s:23:"Semi-permeable Membrane";}','','Mercury Injection','Which capillary pressure measurement method uses gas pressure to force mercury into the pores of a dry rock sample?','a:4:{i:0;s:17:"Mercury Injection";i:1;s:12:"Porous Plate";i:2;s:10:"Centrifuge";i:3;s:23:"Semi-permeable Membrane";}','Mercury Injection','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000161','Apa fungsi utama dari Leverett J-function dalam analisis petrofisika?','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:25:"Mengoreksi data porositas";i:1;s:63:"Menormalisasi data tekanan kapiler untuk berbagai permeabilitas";i:2;s:28:"Menghitung saturasi air sisa";i:3;s:38:"Menentukan viskositas fluida reservoir";}','','Menormalisasi data tekanan kapiler untuk berbagai permeabilitas','What is the primary function of the Leverett J-function in petrophysical analysis?','a:4:{i:0;s:24:"Correcting porosity data";i:1;s:64:"Normalizing capillary pressure data for different permeabilities";i:2;s:40:"Calculating irreducible water saturation";i:3;s:37:"Determining reservoir fluid viscosity";}','Normalizing capillary pressure data for different permeabilities','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000162','Pilih dua metode yang umumnya dianggap sebagai metode kesetimbangan (equilibrium method) dalam pengukuran tekanan kapiler:','multi','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:12:"Porous Plate";i:1;s:10:"Centrifuge";i:2;s:17:"Mercury Injection";i:3;s:16:"Log Resistivitas";}','','a:2:{i:0;s:12:"Porous Plate";i:1;s:10:"Centrifuge";}','Select two methods that are generally considered as equilibrium methods in capillary pressure measurement:','a:4:{i:0;s:12:"Porous Plate";i:1;s:10:"Centrifuge";i:2;s:17:"Mercury Injection";i:3;s:15:"Resistivity Log";}','a:2:{i:0;s:12:"Porous Plate";i:1;s:10:"Centrifuge";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000163','Saturasi air sisa (Swc) pada kurva tekanan kapiler tercapai ketika:','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:34:"Tekanan kapiler mencapai nilai nol";i:1;s:71:"Saturasi air tidak lagi berkurang meskipun tekanan kapiler ditingkatkan";i:2;s:45:"Permeabilitas absolut mencapai nilai maksimum";i:3;s:49:"Tekanan kapiler setara dengan tekanan hidrostatik";}','','Saturasi air tidak lagi berkurang meskipun tekanan kapiler ditingkatkan','Irreducible water saturation (Swc) on a capillary pressure curve is reached when:','a:4:{i:0;s:31:"Capillary pressure reaches zero";i:1;s:76:"Water saturation no longer decreases even if capillary pressure is increased";i:2;s:47:"Absolute permeability reaches its maximum value";i:3;s:51:"Capillary pressure is equal to hydrostatic pressure";}','Water saturation no longer decreases even if capillary pressure is increased','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000164','Parameter utama yang mempengaruhi besarnya apa saja yang diperlukan untuk menghitung Leverett J-function?','multi','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:15:"Tekanan kapiler";i:1;s:13:"Permeabilitas";i:2;s:9:"Porositas";i:3;s:14:"Viskositas air";}','','a:3:{i:0;s:15:"Tekanan kapiler";i:1;s:13:"Permeabilitas";i:2;s:9:"Porositas";}','Which parameters are required to calculate the Leverett J-function?','a:4:{i:0;s:18:"Capillary pressure";i:1;s:12:"Permeability";i:2;s:8:"Porosity";i:3;s:15:"Water viscosity";}','a:3:{i:0;s:18:"Capillary pressure";i:1;s:12:"Permeability";i:2;s:8:"Porosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000165','Dalam metode centrifuge, gaya apa yang digunakan untuk melawan gaya kapiler guna mengusir fluida dari sampel batuan?','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:14:"Gaya gravitasi";i:1;s:16:"Gaya sentrifugal";i:2;s:11:"Gaya viskos";i:3;s:20:"Gaya elektromagnetik";}','','Gaya sentrifugal','In the centrifuge method, what force is used to overcome capillary forces to displace fluids from the rock sample?','a:4:{i:0;s:13:"Gravity force";i:1;s:17:"Centrifugal force";i:2;s:13:"Viscous force";i:3;s:21:"Electromagnetic force";}','Centrifugal force','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000166','Mengapa Mercury Injection tidak disarankan untuk sampel batuan yang mengandung lempung ekspansif (swelling clays)?','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:49:"Merkuri akan bereaksi secara kimia dengan lempung";i:1;s:56:"Tekanan tinggi dapat merusak struktur pori yang sensitif";i:2;s:40:"Merkuri tidak bisa masuk ke pori lempung";i:3;s:37:"Merkuri terlalu mahal untuk digunakan";}','','Tekanan tinggi dapat merusak struktur pori yang sensitif','Why is Mercury Injection not recommended for rock samples containing swelling clays?','a:4:{i:0;s:43:"Mercury will react chemically with the clay";i:1;s:50:"High pressure can damage sensitive pore structures";i:2;s:31:"Mercury cannot enter clay pores";i:3;s:31:"Mercury is too expensive to use";}','High pressure can damage sensitive pore structures','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000167','Pada kurva tekanan kapiler, ''Entry Pressure'' didefinisikan sebagai:','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:56:"Tekanan minimum untuk memulai injeksi fluida non-wetting";i:1;s:38:"Tekanan saat saturasi air mencapai 50%";i:2;s:51:"Tekanan saat permeabilitas relatif mencapai nilai 1";i:3;s:41:"Tekanan saat batuan benar-benar jenuh air";}','','Tekanan minimum untuk memulai injeksi fluida non-wetting','On a capillary pressure curve, ''Entry Pressure'' is defined as:','a:4:{i:0;s:53:"Minimum pressure to start non-wetting fluid injection";i:1;s:42:"Pressure when water saturation reaches 50%";i:2;s:45:"Pressure when relative permeability reaches 1";i:3;s:47:"Pressure when the rock is fully water saturated";}','Minimum pressure to start non-wetting fluid injection','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000168','Manakah pernyataan yang benar mengenai Swc dan ukuran pori?','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:44:"Semakin kecil ukuran pori, semakin kecil Swc";i:1;s:44:"Semakin besar ukuran pori, semakin besar Swc";i:2;s:44:"Semakin kecil ukuran pori, semakin besar Swc";i:3;s:38:"Swc tidak dipengaruhi oleh ukuran pori";}','','Semakin kecil ukuran pori, semakin besar Swc','Which statement is correct regarding Swc and pore size?','a:4:{i:0;s:46:"The smaller the pore size, the smaller the Swc";i:1;s:44:"The larger the pore size, the larger the Swc";i:2;s:45:"The smaller the pore size, the larger the Swc";i:3;s:32:"Swc is not affected by pore size";}','The smaller the pore size, the larger the Swc','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000169','Metode Porous Plate memiliki keunggulan utama dibandingkan metode lainnya, yaitu:','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:34:"Waktu pengukuran yang sangat cepat";i:1;s:60:"Dapat mensimulasikan kondisi tekanan reservoir secara akurat";i:2;s:35:"Tidak memerlukan peralatan tambahan";i:3;s:54:"Dapat digunakan untuk semua jenis batuan tanpa batasan";}','','Dapat mensimulasikan kondisi tekanan reservoir secara akurat','The Porous Plate method has a major advantage over other methods, which is:','a:4:{i:0;s:26:"Very fast measurement time";i:1;s:53:"Can accurately simulate reservoir pressure conditions";i:2;s:37:"Does not require additional equipment";i:3;s:50:"Can be used for all rock types without limitations";}','Can accurately simulate reservoir pressure conditions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000170','Apa yang dimaksud dengan saturasi air konat (Swc) pada kurva permeabilitas relatif?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:57:"Saturasi air minimum di mana fase air tidak lagi mengalir";i:1;s:46:"Saturasi air maksimum saat minyak terperangkap";i:2;s:66:"Titik di mana permeabilitas relatif minyak mencapai nilai maksimum";i:3;s:49:"Saturasi air di mana tekanan kapiler bernilai nol";}','','Saturasi air minimum di mana fase air tidak lagi mengalir','What is meant by irreducible water saturation (Swc) on a relative permeability curve?','a:4:{i:0;s:62:"Minimum water saturation where the water phase no longer flows";i:1;s:44:"Maximum water saturation when oil is trapped";i:2;s:63:"Point where relative oil permeability reaches its maximum value";i:3;s:49:"Water saturation where capillary pressure is zero";}','Minimum water saturation where the water phase no longer flows','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000171','Manakah pernyataan yang benar mengenai hubungan antara tekanan kapiler dan permeabilitas relatif?','multi','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:60:"Tekanan kapiler mempengaruhi distribusi fluida di dalam pori";i:1;s:56:"Permeabilitas relatif adalah fungsi dari saturasi fluida";i:2;s:55:"Tekanan kapiler hanya bergantung pada viskositas fluida";i:3;s:63:"Permeabilitas relatif tidak dipengaruhi oleh wettability batuan";}','','a:2:{i:0;s:60:"Tekanan kapiler mempengaruhi distribusi fluida di dalam pori";i:1;s:56:"Permeabilitas relatif adalah fungsi dari saturasi fluida";}','Which statements are correct regarding the relationship between capillary pressure and relative permeability?','a:4:{i:0;s:61:"Capillary pressure influences fluid distribution within pores";i:1;s:55:"Relative permeability is a function of fluid saturation";i:2;s:50:"Capillary pressure depends only on fluid viscosity";i:3;s:57:"Relative permeability is not affected by rock wettability";}','a:2:{i:0;s:61:"Capillary pressure influences fluid distribution within pores";i:1;s:55:"Relative permeability is a function of fluid saturation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000172','Pada sistem aliran dua-fase minyak-air, apa yang terjadi pada permeabilitas relatif minyak (Kro) saat saturasi air meningkat?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:32:"Nilai Kro menurun secara drastis";i:1;s:33:"Nilai Kro meningkat secara linear";i:2;s:23:"Nilai Kro tetap konstan";i:3;s:39:"Nilai Kro menjadi lebih besar dari satu";}','','Nilai Kro menurun secara drastis','In a two-phase oil-water flow system, what happens to the oil relative permeability (Kro) as water saturation increases?','a:4:{i:0;s:31:"Kro values decrease drastically";i:1;s:28:"Kro values increase linearly";i:2;s:26:"Kro values remain constant";i:3;s:34:"Kro values become greater than one";}','Kro values decrease drastically','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000173','Apa yang dimaksud dengan Sor (Residual Oil Saturation) dalam konteks permeabilitas relatif?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:58:"Saturasi minyak yang tersisa setelah proses pendesakan air";i:1;s:39:"Saturasi minyak awal sebelum pendesakan";i:2;s:55:"Saturasi di mana permeabilitas relatif air bernilai nol";i:3;s:48:"Saturasi minyak pada kondisi tekanan kapiler nol";}','','Saturasi minyak yang tersisa setelah proses pendesakan air','What is meant by Sor (Residual Oil Saturation) in the context of relative permeability?','a:4:{i:0;s:59:"Oil saturation remaining after a water displacement process";i:1;s:42:"Initial oil saturation before displacement";i:2;s:52:"Saturation where water relative permeability is zero";i:3;s:51:"Oil saturation at zero capillary pressure condition";}','Oil saturation remaining after a water displacement process','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000174','Faktor apa saja yang mempengaruhi bentuk kurva permeabilitas relatif?','multi','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:18:"Wettability batuan";i:1;s:22:"Distribusi ukuran pori";i:2;s:19:"Viskositas air saja";i:3;s:41:"Sejarah saturasi (drainage vs imbibition)";}','','a:3:{i:0;s:18:"Wettability batuan";i:1;s:22:"Distribusi ukuran pori";i:2;s:41:"Sejarah saturasi (drainage vs imbibition)";}','What factors influence the shape of the relative permeability curve?','a:4:{i:0;s:16:"Rock wettability";i:1;s:22:"Pore size distribution";i:2;s:20:"Water viscosity only";i:3;s:43:"Saturation history (drainage vs imbibition)";}','a:3:{i:0;s:16:"Rock wettability";i:1;s:22:"Pore size distribution";i:2;s:43:"Saturation history (drainage vs imbibition)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000175','Dalam aliran tiga-fase (minyak, air, gas), permeabilitas relatif fase non-wetting biasanya ditentukan oleh?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:25:"Saturasi fase itu sendiri";i:1;s:34:"Saturasi ketiga fase yang terlibat";i:2;s:23:"Viskositas fase wetting";i:3;s:20:"Tekanan formasi saja";}','','Saturasi fase itu sendiri','In three-phase flow (oil, water, gas), the relative permeability of a non-wetting phase is typically determined by?','a:4:{i:0;s:34:"The saturation of the phase itself";i:1;s:43:"The saturation of all three phases involved";i:2;s:30:"Viscosity of the wetting phase";i:3;s:23:"Formation pressure only";}','The saturation of the phase itself','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000176','Apa dampak utama dari kondisi ''oil-wet'' terhadap kurva permeabilitas relatif air?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:50:"Air mulai mengalir pada saturasi yang lebih rendah";i:1;s:61:"Air lebih sulit untuk mengalir dibandingkan kondisi water-wet";i:2;s:41:"Kro akan selalu lebih tinggi daripada Krw";i:3;s:34:"Tidak ada perubahan pada kurva Krw";}','','Air lebih sulit untuk mengalir dibandingkan kondisi water-wet','What is the primary impact of an ''oil-wet'' condition on the water relative permeability curve?','a:4:{i:0;s:40:"Water starts to flow at lower saturation";i:1;s:56:"Water is harder to flow compared to water-wet conditions";i:2;s:34:"Kro will always be higher than Krw";i:3;s:35:"There is no change in the Krw curve";}','Water is harder to flow compared to water-wet conditions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000177','Mengapa kurva permeabilitas relatif drainase dan imbibisi sering kali berbeda?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:42:"Karena adanya fenomena histeresis saturasi";i:1;s:41:"Karena perubahan viskositas selama proses";i:2;s:40:"Karena tekanan kapiler tidak berpengaruh";i:3;s:36:"Karena laju alir yang selalu konstan";}','','Karena adanya fenomena histeresis saturasi','Why do drainage and imbibition relative permeability curves often differ?','a:4:{i:0;s:38:"Due to saturation hysteresis phenomena";i:1;s:43:"Due to viscosity changes during the process";i:2;s:40:"Because capillary pressure has no effect";i:3;s:38:"Because flow rates are always constant";}','Due to saturation hysteresis phenomena','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000178','Pada titik crossover di kurva Krw dan Kro, kondisi apa yang biasanya terjadi?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:64:"Saturasi air biasanya lebih besar dari 50% jika batuan water-wet";i:1;s:44:"Permeabilitas relatif keduanya bernilai satu";i:2;s:39:"Tekanan kapiler mencapai nilai maksimum";i:3;s:33:"Aliran minyak berhenti sepenuhnya";}','','Saturasi air biasanya lebih besar dari 50% jika batuan water-wet','At the crossover point on Krw and Kro curves, what condition typically occurs?','a:4:{i:0;s:69:"Water saturation is usually greater than 50% if the rock is water-wet";i:1;s:45:"Both relative permeabilities are equal to one";i:2;s:44:"Capillary pressure reaches its maximum value";i:3;s:25:"Oil flow stops completely";}','Water saturation is usually greater than 50% if the rock is water-wet','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000179','Apa yang dimaksud dengan ''End-point relative permeability''?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:43:"Nilai Kr pada saturasi batas (Swc atau Sor)";i:1;s:48:"Nilai rata-rata Kr pada seluruh rentang saturasi";i:2;s:33:"Nilai Kr saat tekanan kapiler nol";i:3;s:37:"Titik potong antara kurva Krw dan Kro";}','','Nilai Kr pada saturasi batas (Swc atau Sor)','What is meant by ''End-point relative permeability''?','a:4:{i:0;s:48:"The Kr value at boundary saturation (Swc or Sor)";i:1;s:55:"The average Kr value across the entire saturation range";i:2;s:44:"The Kr value when capillary pressure is zero";i:3;s:49:"The intersection point between Krw and Kro curves";}','The Kr value at boundary saturation (Swc or Sor)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000180','Parameter utama yang merepresentasikan fraksi dari total volume batuan yang dapat ditempati oleh fluida adalah:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:12:"Saturasi air";i:3;s:12:"Net to Gross";}','','Porositas','The primary parameter representing the fraction of total rock volume that can be occupied by fluids is:','a:4:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:16:"Water saturation";i:3;s:12:"Net to Gross";}','Porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000181','Manakah dari berikut ini yang diperlukan untuk menghitung Bulk Volume (BV) suatu reservoir?','multi','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:9:"Luas area";i:1;s:19:"Ketebalan reservoir";i:2;s:13:"Permeabilitas";i:3;s:17:"Viskositas fluida";}','','a:2:{i:0;s:9:"Luas area";i:1;s:19:"Ketebalan reservoir";}','Which of the following are required to calculate the Bulk Volume (BV) of a reservoir?','a:4:{i:0;s:12:"Surface area";i:1;s:19:"Reservoir thickness";i:2;s:12:"Permeability";i:3;s:15:"Fluid viscosity";}','a:2:{i:0;s:12:"Surface area";i:1;s:19:"Reservoir thickness";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000182','Rasio antara ketebalan formasi bersih (net) terhadap ketebalan total (gross) dikenal sebagai:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:18:"Net to Gross ratio";i:1;s:14:"Porosity ratio";i:2;s:15:"Recovery factor";i:3;s:23:"Formation Volume Factor";}','','Net to Gross ratio','The ratio between the net formation thickness and the total gross thickness is known as:','a:4:{i:0;s:18:"Net to Gross ratio";i:1;s:14:"Porosity ratio";i:2;s:15:"Recovery factor";i:3;s:23:"Formation Volume Factor";}','Net to Gross ratio','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000183','Faktor volume formasi (Bo) didefinisikan sebagai rasio volume minyak di kondisi reservoir terhadap volume minyak di kondisi:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:13:"Standar (STP)";i:1;s:17:"Tekanan geostatik";i:2;s:15:"Titik gelembung";i:3;s:13:"Kondisi jenuh";}','','Standar (STP)','Formation volume factor (Bo) is defined as the ratio of oil volume at reservoir conditions to oil volume at:','a:4:{i:0;s:25:"Standard conditions (STP)";i:1;s:18:"Geostatic pressure";i:2;s:12:"Bubble point";i:3;s:20:"Saturated conditions";}','Standard conditions (STP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000184','Rumus dasar untuk menghitung Original Oil In Place (OOIP) secara volumetrik adalah:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:38:"(BV * NTG * Porositas * (1 - Sw)) / Bo";i:1;s:31:"(BV * NTG * Permeabilitas) / Bo";i:2;s:14:"(BV * Sw) / Bo";i:3;s:26:"(BV * Porositas * Sw) / Bo";}','','(BV * NTG * Porositas * (1 - Sw)) / Bo','The basic formula to calculate the Original Oil In Place (OOIP) volumetrically is:','a:4:{i:0;s:37:"(BV * NTG * Porosity * (1 - Sw)) / Bo";i:1;s:30:"(BV * NTG * Permeability) / Bo";i:2;s:14:"(BV * Sw) / Bo";i:3;s:25:"(BV * Porosity * Sw) / Bo";}','(BV * NTG * Porosity * (1 - Sw)) / Bo','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000185','Jika 1 acre-feet setara dengan 43,560 cubic feet, berapakah perkiraan konversi ke satuan metrik barrel (1 m3 = 6.29 bbl)?','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:9:"7,758 bbl";i:1;s:9:"1,000 bbl";i:2;s:9:"5,615 bbl";i:3;s:6:"42 bbl";}','','7,758 bbl','If 1 acre-feet is equivalent to 43,560 cubic feet, what is the approximate conversion to barrels (1 m3 = 6.29 bbl)?','a:4:{i:0;s:9:"7,758 bbl";i:1;s:9:"1,000 bbl";i:2;s:9:"5,615 bbl";i:3;s:6:"42 bbl";}','7,758 bbl','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000186','Saturasi air (Sw) dalam perhitungan cadangan berfungsi untuk:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:51:"Menentukan volume ruang pori yang diisi hidrokarbon";i:1;s:28:"Menghitung tekanan reservoir";i:2;s:28:"Menentukan viskositas minyak";i:3;s:26:"Menghitung densitas batuan";}','','Menentukan volume ruang pori yang diisi hidrokarbon','Water saturation (Sw) in reserves calculation serves to:','a:4:{i:0;s:52:"Determine pore space volume filled with hydrocarbons";i:1;s:28:"Calculate reservoir pressure";i:2;s:23:"Determine oil viscosity";i:3;s:22:"Calculate rock density";}','Determine pore space volume filled with hydrocarbons','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000187','Apa yang dimaksud dengan Net Pay dalam evaluasi petrofisika?','multi','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:53:"Bagian reservoir yang mengandung hidrokarbon ekonomis";i:1;s:52:"Bagian batuan yang memiliki porositas di atas cutoff";i:2;s:41:"Bagian reservoir dengan permeabilitas nol";i:3;s:36:"Bagian reservoir yang jenuh air 100%";}','','a:2:{i:0;s:53:"Bagian reservoir yang mengandung hidrokarbon ekonomis";i:1;s:52:"Bagian batuan yang memiliki porositas di atas cutoff";}','What is meant by Net Pay in petrophysical evaluation?','a:4:{i:0;s:58:"The part of the reservoir containing economic hydrocarbons";i:1;s:43:"The rock section with porosity above cutoff";i:2;s:48:"The part of the reservoir with zero permeability";i:3;s:46:"The part of the reservoir 100% water saturated";}','a:2:{i:0;s:58:"The part of the reservoir containing economic hydrocarbons";i:1;s:43:"The rock section with porosity above cutoff";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000188','Dalam perhitungan cadangan gas, faktor volume formasi gas (Bg) biasanya meningkat seiring dengan:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:17:"Penurunan tekanan";i:1;s:16:"Peningkatan suhu";i:2;s:24:"Peningkatan saturasi air";i:3;s:19:"Penurunan porositas";}','','Penurunan tekanan','In gas reserves calculation, the gas formation volume factor (Bg) usually increases with:','a:4:{i:0;s:17:"Pressure decrease";i:1;s:20:"Temperature increase";i:2;s:25:"Water saturation increase";i:3;s:17:"Porosity decrease";}','Pressure decrease','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000189','Satuan standar yang digunakan untuk Bulk Volume (BV) dalam perhitungan cadangan di industri perminyakan adalah:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:9:"Acre-feet";i:1;s:7:"Darcies";i:2;s:10:"Centipoise";i:3;s:3:"PSI";}','','Acre-feet','The standard unit used for Bulk Volume (BV) in reserves calculation in the petroleum industry is:','a:4:{i:0;s:9:"Acre-feet";i:1;s:7:"Darcies";i:2;s:10:"Centipoise";i:3;s:3:"PSI";}','Acre-feet','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000190','Apa tujuan utama dari integrasi data log sumur dengan data inti (core) dalam evaluasi petrofisika?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:78:"Melakukan kalibrasi parameter log terhadap data laboratorium yang lebih akurat";i:1;s:42:"Mengabaikan data log karena kurang presisi";i:2;s:37:"Meningkatkan biaya operasional proyek";i:3;s:49:"Menghilangkan kebutuhan akan interpretasi geologi";}','','Melakukan kalibrasi parameter log terhadap data laboratorium yang lebih akurat','What is the primary purpose of integrating well log data with core data in petrophysical evaluation?','a:4:{i:0;s:64:"Calibrating log parameters against more accurate laboratory data";i:1;s:42:"Ignoring log data due to lack of precision";i:2;s:36:"Increasing project operational costs";i:3;s:50:"Eliminating the need for geological interpretation";}','Calibrating log parameters against more accurate laboratory data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000191','Manakah dari berikut ini yang merupakan indikator kualitas (QC) pada log Gamma Ray sebelum dilakukan interpretasi?','multi','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:43:"Adanya pergeseran baseline (baseline shift)";i:1;s:50:"Skala log yang konsisten dengan interval kedalaman";i:2;s:44:"Kecepatan logging yang tidak stabil (spikes)";i:3;s:51:"Respon yang merepresentasikan litologi secara logis";}','','a:3:{i:0;s:43:"Adanya pergeseran baseline (baseline shift)";i:1;s:44:"Kecepatan logging yang tidak stabil (spikes)";i:2;s:51:"Respon yang merepresentasikan litologi secara logis";}','Which of the following are quality control (QC) indicators for Gamma Ray logs before interpretation?','a:4:{i:0;s:26:"Presence of baseline shift";i:1;s:41:"Log scale consistency with depth interval";i:2;s:31:"Unstable logging speed (spikes)";i:3;s:41:"Response representing lithology logically";}','a:3:{i:0;s:26:"Presence of baseline shift";i:1;s:31:"Unstable logging speed (spikes)";i:2;s:41:"Response representing lithology logically";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000192','Dalam crossplot Neutron-Density, jika titik data terletak di antara garis sandstone dan limestone, apa interpretasi yang paling mungkin?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:51:"Litologi merupakan campuran sandstone dan limestone";i:1;s:34:"Lubang bor mengalami washout parah";i:2;s:45:"Formasi mengandung gas dengan saturasi tinggi";i:3;s:37:"Terjadi kerusakan alat saat perekaman";}','','Litologi merupakan campuran sandstone dan limestone','In a Neutron-Density crossplot, if the data points lie between the sandstone and limestone lines, what is the most likely interpretation?','a:4:{i:0;s:53:"The lithology is a mixture of sandstone and limestone";i:1;s:31:"The borehole has severe washout";i:2;s:47:"The formation contains gas with high saturation";i:3;s:36:"Tool failure occurred during logging";}','The lithology is a mixture of sandstone and limestone','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000193','Apa manfaat utama dari penggunaan M-N plot dalam evaluasi petrofisika?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:64:"Identifikasi litologi kompleks dengan menggunakan tiga porositas";i:1;s:38:"Estimasi permeabilitas secara langsung";i:2;s:38:"Menentukan viskositas fluida reservoir";i:3;s:42:"Menghitung tekanan kapiler secara otomatis";}','','Identifikasi litologi kompleks dengan menggunakan tiga porositas','What is the main benefit of using an M-N plot in petrophysical evaluation?','a:4:{i:0;s:61:"Identification of complex lithology using three porosity logs";i:1;s:30:"Direct permeability estimation";i:2;s:37:"Determining reservoir fluid viscosity";i:3;s:43:"Automatic calculation of capillary pressure";}','Identification of complex lithology using three porosity logs','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000194','Bagaimana pengaruh efek ''gas effect'' pada crossplot Neutron-Density?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:62:"Menyebabkan nilai porositas neutron rendah dan densitas tinggi";i:1;s:47:"Tidak memberikan perubahan pada nilai pembacaan";i:2;s:45:"Membuat nilai porositas neutron sangat tinggi";i:3;s:52:"Menyebabkan pembacaan densitas menjadi sangat rendah";}','','Menyebabkan nilai porositas neutron rendah dan densitas tinggi','How does the ''gas effect'' influence a Neutron-Density crossplot?','a:4:{i:0;s:51:"Causes low neutron porosity and high density values";i:1;s:34:"Does not change the reading values";i:2;s:39:"Makes neutron porosity values very high";i:3;s:42:"Causes density readings to become very low";}','Causes low neutron porosity and high density values','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000195','Faktor apa saja yang harus diperiksa saat melakukan Quality Control (QC) data core terhadap data log?','multi','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:46:"Kedalaman (depth shifting) antara log dan core";i:1;s:30:"Pemulihan core (core recovery)";i:2;s:34:"Orientasi core terhadap arah utara";i:3;s:37:"Tekanan formasi saat pengambilan core";}','','a:2:{i:0;s:46:"Kedalaman (depth shifting) antara log dan core";i:1;s:30:"Pemulihan core (core recovery)";}','Which factors should be checked when performing Quality Control (QC) of core data against log data?','a:4:{i:0;s:35:"Depth shifting between log and core";i:1;s:13:"Core recovery";i:2;s:34:"Core orientation relative to north";i:3;s:32:"Formation pressure during coring";}','a:2:{i:0;s:35:"Depth shifting between log and core";i:1;s:13:"Core recovery";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000196','Pada penyajian petrophysical summary, kurva apa yang paling umum digunakan untuk menentukan zona reservoir netto?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:37:"Volume lempung (Vshale) dan Porositas";i:1;s:26:"Kurva kecepatan sonik saja";i:2;s:30:"Hanya kurva resistivitas dalam";i:3;s:22:"Kurva temperatur sumur";}','','Volume lempung (Vshale) dan Porositas','In a petrophysical summary presentation, which curves are most commonly used to determine net reservoir zones?','a:4:{i:0;s:34:"Shale volume (Vshale) and Porosity";i:1;s:25:"Sonic velocity curve only";i:2;s:27:"Deep resistivity curve only";i:3;s:22:"Well temperature curve";}','Shale volume (Vshale) and Porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000197','Mengapa integrasi data geologi penting dalam interpretasi petrofisika?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:71:"Untuk memastikan model petrofisika sesuai dengan lingkungan pengendapan";i:1;s:49:"Untuk mempercepat waktu komputasi perangkat lunak";i:2;s:44:"Hanya untuk keperluan dokumentasi perusahaan";i:3;s:40:"Agar tidak perlu melakukan logging ulang";}','','Untuk memastikan model petrofisika sesuai dengan lingkungan pengendapan','Why is geological data integration important in petrophysical interpretation?','a:4:{i:0;s:74:"To ensure the petrophysical model aligns with the depositional environment";i:1;s:37:"To speed up software computation time";i:2;s:41:"Only for corporate documentation purposes";i:3;s:19:"To avoid re-logging";}','To ensure the petrophysical model aligns with the depositional environment','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000198','Dalam konteks QC log resistivitas, kondisi apa yang menunjukkan adanya invasi filtrat lumpur yang signifikan?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:48:"Separasi antara log shallow dan deep resistivity";i:1;s:48:"Kurva resistivitas yang tumpang tindih (overlay)";i:2;s:52:"Nilai resistivitas yang sangat tinggi di zona serpih";i:3;s:56:"Tidak adanya perbedaan antara log mikrolat dan lateralog";}','','Separasi antara log shallow dan deep resistivity','In the context of resistivity log QC, what condition indicates significant mud filtrate invasion?','a:4:{i:0;s:52:"Separation between shallow and deep resistivity logs";i:1;s:30:"Overlapping resistivity curves";i:2;s:46:"Very high resistivity values in the shale zone";i:3;s:50:"No difference between microlaterolog and laterolog";}','Separation between shallow and deep resistivity logs','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000199','Crossplot antara resistivitas dan porositas (Pickett Plot) digunakan untuk menentukan apa?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:49:"Saturasi air (Sw) dan parameter formasi (m, n, a)";i:1;s:21:"Permeabilitas absolut";i:2;s:17:"Tekanan reservoir";i:3;s:36:"Kecepatan perambatan gelombang suara";}','','Saturasi air (Sw) dan parameter formasi (m, n, a)','The crossplot between resistivity and porosity (Pickett Plot) is used to determine what?','a:4:{i:0;s:56:"Water saturation (Sw) and formation parameters (m, n, a)";i:1;s:21:"Absolute permeability";i:2;s:18:"Reservoir pressure";i:3;s:31:"Sound wave propagation velocity";}','Water saturation (Sw) and formation parameters (m, n, a)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000200','Jika sebuah formasi memiliki resistivitas air formasi (Rw) sebesar 0.05 ohm-m pada suhu reservoir dan resistivitas batuan (Rt) sebesar 5 ohm-m dengan faktor formasi (F) sebesar 20, berapa nilai saturasi air (Sw) menggunakan persamaan Archie (n=2)?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:4:"0.40";i:1;s:4:"0.45";i:2;s:4:"0.50";i:3;s:4:"0.60";}','','0.45','If a formation has a formation water resistivity (Rw) of 0.05 ohm-m at reservoir temperature and a true rock resistivity (Rt) of 5 ohm-m with a formation factor (F) of 20, what is the water saturation (Sw) value using the Archie equation (n=2)?','a:4:{i:0;s:4:"0.40";i:1;s:4:"0.45";i:2;s:4:"0.50";i:3;s:4:"0.60";}','0.45','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000201','Dalam studi kasus log sumur, manakah parameter yang paling berpengaruh secara langsung dalam perhitungan volume hidrokarbon awal di tempat (OOIP)?','multi','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:7:"Net pay";i:3;s:21:"Permeabilitas absolut";}','','a:3:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:7:"Net pay";}','In a well log case study, which parameters directly influence the calculation of the original oil in place (OOIP)?','a:4:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:7:"Net pay";i:3;s:21:"Absolute permeability";}','a:3:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:7:"Net pay";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000202','Pada zona sandstone bersih (clean sand), respon log Gamma Ray (GR) yang rendah mengindikasikan apa?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:36:"Kandungan serpih (shale) yang tinggi";i:1;s:36:"Kandungan serpih (shale) yang rendah";i:2;s:28:"Porositas yang sangat rendah";i:3;s:14:"Keberadaan gas";}','','Kandungan serpih (shale) yang rendah','In a clean sand zone, what does a low Gamma Ray (GR) log response indicate?','a:4:{i:0;s:18:"High shale content";i:1;s:17:"Low shale content";i:2;s:17:"Very low porosity";i:3;s:15:"Presence of gas";}','Low shale content','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000203','Sebuah reservoir memiliki porositas 20% dan ketebalan net pay 10 meter. Jika luas area adalah 1 km persegi dan saturasi air 30%, berapa estimasi volume minyak dalam meter kubik?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:9:"1,400,000";i:1;s:9:"1,800,000";i:2;s:9:"2,000,000";i:3;s:9:"2,400,000";}','','1,400,000','A reservoir has 20% porosity and 10 meters of net pay. If the area is 1 square kilometer and water saturation is 30%, what is the estimated oil volume in cubic meters?','a:4:{i:0;s:9:"1,400,000";i:1;s:9:"1,800,000";i:2;s:9:"2,000,000";i:3;s:9:"2,400,000";}','1,400,000','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000204','Manakah di antara berikut ini yang merupakan hubungan empiris utama dalam menentukan porositas dari log densitas?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:56:"Phi = (rho_matrix - rho_bulk) / (rho_matrix - rho_fluid)";i:1;s:56:"Phi = (rho_bulk - rho_matrix) / (rho_matrix - rho_fluid)";i:2;s:56:"Phi = (rho_matrix - rho_fluid) / (rho_bulk - rho_matrix)";i:3;s:54:"Phi = (rho_bulk - rho_fluid) / (rho_matrix - rho_bulk)";}','','Phi = (rho_matrix - rho_bulk) / (rho_matrix - rho_fluid)','Which of the following is the primary empirical relationship for determining porosity from the density log?','a:4:{i:0;s:56:"Phi = (rho_matrix - rho_bulk) / (rho_matrix - rho_fluid)";i:1;s:56:"Phi = (rho_bulk - rho_matrix) / (rho_matrix - rho_fluid)";i:2;s:56:"Phi = (rho_matrix - rho_fluid) / (rho_bulk - rho_matrix)";i:3;s:54:"Phi = (rho_bulk - rho_fluid) / (rho_matrix - rho_bulk)";}','Phi = (rho_matrix - rho_bulk) / (rho_matrix - rho_fluid)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000205','Apa dampak utama dari keberadaan lempung (shale) pada interpretasi resistivitas sumur?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:33:"Meningkatkan resistivitas terbaca";i:1;s:31:"Menurunkan resistivitas terbaca";i:2;s:35:"Tidak berpengaruh pada resistivitas";i:3;s:42:"Membuat resistivitas menjadi tak terhingga";}','','Menurunkan resistivitas terbaca','What is the primary impact of clay (shale) presence on well resistivity interpretation?','a:4:{i:0;s:30:"Increases apparent resistivity";i:1;s:30:"Decreases apparent resistivity";i:2;s:24:"No effect on resistivity";i:3;s:26:"Makes resistivity infinite";}','Decreases apparent resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000206','Dalam konteks evaluasi formasi, apa yang dimaksud dengan Vsh (Volume Shale)?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:38:"Volume hidrokarbon di dalam ruang pori";i:1;s:46:"Fraksi volume batuan serpih di dalam reservoir";i:2;s:40:"Kecepatan gelombang suara melalui serpih";i:3;s:36:"Kapasitas serpih untuk menyimpan air";}','','Fraksi volume batuan serpih di dalam reservoir','In the context of formation evaluation, what is Vsh (Shale Volume)?','a:4:{i:0;s:36:"Hydrocarbon volume in the pore space";i:1;s:50:"Volume fraction of shale rock within the reservoir";i:2;s:37:"Velocity of sound waves through shale";i:3;s:32:"Capacity of shale to store water";}','Volume fraction of shale rock within the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000207','Jika log neutron dan log densitas saling berhimpit (crossover) pada formasi sandstone, apa interpretasi petrofisikanya?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:15:"Adanya zona air";i:1;s:10:"Adanya gas";i:2;s:26:"Formasi yang sangat kompak";i:3;s:15:"Adanya batubara";}','','Adanya gas','If neutron and density logs crossover in a sandstone formation, what is the petrophysical interpretation?','a:4:{i:0;s:22:"Presence of water zone";i:1;s:15:"Presence of gas";i:2;s:22:"Very compact formation";i:3;s:16:"Presence of coal";}','Presence of gas','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000208','Manakah parameter yang diperlukan untuk menghitung faktor formasi (F) menggunakan rumus Archie?','multi','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:9:"Porositas";i:1;s:12:"Saturasi air";i:2;s:11:"Tortuositas";i:3;s:14:"Semenatasi (m)";}','','a:2:{i:0;s:9:"Porositas";i:1;s:14:"Semenatasi (m)";}','Which parameters are needed to calculate the formation factor (F) using the Archie formula?','a:4:{i:0;s:8:"Porosity";i:1;s:16:"Water saturation";i:2;s:10:"Tortuosity";i:3;s:24:"Cementation exponent (m)";}','a:2:{i:0;s:8:"Porosity";i:1;s:24:"Cementation exponent (m)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000209','Dalam perhitungan volumetrik, apa fungsi utama dari pemotongan (cutoff) porositas?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:36:"Untuk menentukan batas atas cadangan";i:1;s:70:"Untuk mengeliminasi batuan yang tidak berkontribusi pada aliran fluida";i:2;s:32:"Untuk menghitung tekanan kapiler";i:3;s:45:"Untuk memperbaiki akurasi pembacaan Gamma Ray";}','','Untuk mengeliminasi batuan yang tidak berkontribusi pada aliran fluida','In volumetric calculations, what is the main function of porosity cutoffs?','a:4:{i:0;s:40:"To determine the upper limit of reserves";i:1;s:56:"To eliminate rock that does not contribute to fluid flow";i:2;s:31:"To calculate capillary pressure";i:3;s:37:"To improve Gamma Ray reading accuracy";}','To eliminate rock that does not contribute to fluid flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000210','Apa mekanisme pendorong utama yang menyebabkan minyak mengalir ke lubang sumur selama tahap primary recovery?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:22:"Energi alami reservoir";i:1;s:11:"Injeksi air";i:2;s:15:"Injeksi gas CO2";i:3;s:15:"Injeksi polimer";}','','Energi alami reservoir','What is the primary driving mechanism that causes oil to flow into the wellbore during the primary recovery stage?','a:4:{i:0;s:24:"Natural reservoir energy";i:1;s:15:"Water injection";i:2;s:17:"CO2 gas injection";i:3;s:17:"Polymer injection";}','Natural reservoir energy','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000211','Manakah dari berikut ini yang termasuk dalam metode secondary recovery untuk mempertahankan tekanan reservoir?','multi','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:13:"Waterflooding";i:1;s:36:"Gas injection (pressure maintenance)";i:2;s:17:"Injeksi surfaktan";i:3;s:16:"Thermal recovery";}','','a:2:{i:0;s:13:"Waterflooding";i:1;s:36:"Gas injection (pressure maintenance)";}','Which of the following are included in secondary recovery methods to maintain reservoir pressure?','a:4:{i:0;s:13:"Waterflooding";i:1;s:36:"Gas injection (pressure maintenance)";i:2;s:20:"Surfactant injection";i:3;s:16:"Thermal recovery";}','a:2:{i:0;s:13:"Waterflooding";i:1;s:36:"Gas injection (pressure maintenance)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000212','Apa tujuan utama dari penerapan Enhanced Oil Recovery (EOR) setelah tahap secondary recovery berakhir?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:28:"Mengurangi biaya operasional";i:1;s:76:"Meningkatkan perolehan minyak dengan mengubah sifat fisik fluida atau batuan";i:2;s:26:"Mengganti pompa sucker rod";i:3;s:40:"Menutup sumur yang sudah tidak produktif";}','','Meningkatkan perolehan minyak dengan mengubah sifat fisik fluida atau batuan','What is the main purpose of applying Enhanced Oil Recovery (EOR) after the secondary recovery stage ends?','a:4:{i:0;s:24:"Reduce operational costs";i:1;s:72:"Increase oil recovery by altering physical properties of fluids or rocks";i:2;s:24:"Replace sucker rod pumps";i:3;s:26:"Shut in unproductive wells";}','Increase oil recovery by altering physical properties of fluids or rocks','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000213','Faktor perolehan (Recovery Factor) didefinisikan sebagai rasio antara:','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:58:"Minyak yang diproduksi dengan original oil in place (OOIP)";i:1;s:45:"Tekanan reservoir dengan tekanan bubble point";i:2;s:37:"Laju alir minyak dengan laju alir air";i:3;s:36:"Porositas batuan dengan saturasi air";}','','Minyak yang diproduksi dengan original oil in place (OOIP)','The Recovery Factor is defined as the ratio between:','a:4:{i:0;s:45:"Produced oil and original oil in place (OOIP)";i:1;s:44:"Reservoir pressure and bubble point pressure";i:2;s:33:"Oil flow rate and water flow rate";i:3;s:34:"Rock porosity and water saturation";}','Produced oil and original oil in place (OOIP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000214','Apa yang dimaksud dengan residual oil saturation (Sor) dalam konteks EOR?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:70:"Saturasi minyak yang tertinggal di reservoir setelah proses pendesakan";i:1;s:37:"Saturasi minyak awal sebelum produksi";i:2;s:52:"Saturasi minyak yang bisa diproduksi secara ekonomis";i:3;s:31:"Saturasi minyak di zona gas cap";}','','Saturasi minyak yang tertinggal di reservoir setelah proses pendesakan','What is meant by residual oil saturation (Sor) in the context of EOR?','a:4:{i:0;s:60:"Oil saturation remaining in the reservoir after displacement";i:1;s:40:"Initial oil saturation before production";i:2;s:48:"Oil saturation that can be economically produced";i:3;s:34:"Oil saturation in the gas cap zone";}','Oil saturation remaining in the reservoir after displacement','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000215','Manakah komponen utama yang mempengaruhi efisiensi penyapuan (sweep efficiency) dalam suatu reservoir?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:41:"Heterogenitas batuan dan mobilitas fluida";i:1;s:15:"Kedalaman sumur";i:2;s:15:"Diameter casing";i:3;s:21:"Jumlah kru pengeboran";}','','Heterogenitas batuan dan mobilitas fluida','Which main components affect sweep efficiency in a reservoir?','a:4:{i:0;s:37:"Rock heterogeneity and fluid mobility";i:1;s:10:"Well depth";i:2;s:15:"Casing diameter";i:3;s:23:"Number of drilling crew";}','Rock heterogeneity and fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000216','Metode EOR yang bekerja terutama dengan cara menurunkan tegangan antar muka (interfacial tension) antara minyak dan air adalah:','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:17:"Injeksi surfaktan";i:1;s:11:"Injeksi uap";i:2;s:15:"Injeksi polimer";i:3;s:17:"Injeksi air panas";}','','Injeksi surfaktan','The EOR method that works primarily by lowering the interfacial tension between oil and water is:','a:4:{i:0;s:20:"Surfactant injection";i:1;s:15:"Steam injection";i:2;s:17:"Polymer injection";i:3;s:19:"Hot water injection";}','Surfactant injection','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000217','Dalam konteks tahapan produksi, manakah pernyataan yang benar mengenai urutan umum pengembangan lapangan?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:32:"Primary -> Secondary -> Tertiary";i:1;s:32:"Tertiary -> Primary -> Secondary";i:2;s:32:"Secondary -> Primary -> Tertiary";i:3;s:32:"Primary -> Tertiary -> Secondary";}','','Primary -> Secondary -> Tertiary','In the context of production stages, which statement is correct regarding the general sequence of field development?','a:4:{i:0;s:32:"Primary -> Secondary -> Tertiary";i:1;s:32:"Tertiary -> Primary -> Secondary";i:2;s:32:"Secondary -> Primary -> Tertiary";i:3;s:32:"Primary -> Tertiary -> Secondary";}','Primary -> Secondary -> Tertiary','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000218','Apa fungsi utama dari penambahan polimer dalam waterflooding?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:63:"Meningkatkan viskositas air injeksi untuk memperbaiki mobilitas";i:1;s:28:"Menurunkan viskositas minyak";i:2;s:29:"Membunuh bakteri di reservoir";i:3;s:34:"Membersihkan kerak di lubang sumur";}','','Meningkatkan viskositas air injeksi untuk memperbaiki mobilitas','What is the primary function of adding polymers in waterflooding?','a:4:{i:0;s:54:"Increase injection water viscosity to improve mobility";i:1;s:22:"Decrease oil viscosity";i:2;s:30:"Kill bacteria in the reservoir";i:3;s:27:"Clean scale in the wellbore";}','Increase injection water viscosity to improve mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000219','Faktor perolehan akhir suatu lapangan minyak dipengaruhi oleh:','multi','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:32:"Efisiensi pendesakan mikroskopis";i:1;s:31:"Efisiensi penyapuan makroskopis";i:2;s:22:"Biaya sewa alat kantor";i:3;s:12:"Warna minyak";}','','a:2:{i:0;s:32:"Efisiensi pendesakan mikroskopis";i:1;s:31:"Efisiensi penyapuan makroskopis";}','The final recovery factor of an oil field is influenced by:','a:4:{i:0;s:35:"Microscopic displacement efficiency";i:1;s:28:"Macroscopic sweep efficiency";i:2;s:29:"Office equipment rental costs";i:3;s:9:"Oil color";}','a:2:{i:0;s:35:"Microscopic displacement efficiency";i:1;s:28:"Macroscopic sweep efficiency";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000220','Mekanisme pendorong utama pada reservoir yang mengandalkan ekspansi gas terlarut dalam minyak disebut sebagai','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:15:"Depletion drive";i:1;s:11:"Water drive";i:2;s:13:"Gas cap drive";i:3;s:16:"Gravity drainage";}','','Depletion drive','The primary drive mechanism in a reservoir relying on the expansion of gas dissolved in oil is called','a:4:{i:0;s:15:"Depletion drive";i:1;s:11:"Water drive";i:2;s:13:"Gas cap drive";i:3;s:16:"Gravity drainage";}','Depletion drive','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000221','Faktor apa saja yang menentukan besarnya residual oil saturation (Sor) di dalam pori batuan setelah proses pendorongan?','multi','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:21:"Kekuatan gaya kapiler";i:1;s:36:"Sifat kebasahan batuan (wettability)";i:2;s:16:"Kecepatan aliran";i:3;s:17:"Viskositas fluida";}','','a:3:{i:0;s:21:"Kekuatan gaya kapiler";i:1;s:36:"Sifat kebasahan batuan (wettability)";i:2;s:17:"Viskositas fluida";}','What factors determine the magnitude of residual oil saturation (Sor) within rock pores after a displacement process?','a:4:{i:0;s:24:"Capillary force strength";i:1;s:16:"Rock wettability";i:2;s:13:"Flow velocity";i:3;s:15:"Fluid viscosity";}','a:3:{i:0;s:24:"Capillary force strength";i:1;s:16:"Rock wettability";i:2;s:15:"Fluid viscosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000222','Pada mekanisme water drive, efisiensi penyapuan (sweep efficiency) sangat dipengaruhi oleh','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:39:"Mobilitas relatif antara air dan minyak";i:1;s:22:"Tekanan awal reservoir";i:2;s:19:"Kedalaman reservoir";i:3;s:25:"Kadar sulfur dalam minyak";}','','Mobilitas relatif antara air dan minyak','In a water drive mechanism, sweep efficiency is strongly influenced by','a:4:{i:0;s:39:"Relative mobility between water and oil";i:1;s:26:"Initial reservoir pressure";i:2;s:15:"Reservoir depth";i:3;s:21:"Sulfur content in oil";}','Relative mobility between water and oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000223','Mekanisme pendorong yang memanfaatkan perbedaan densitas antara minyak dan gas untuk mendesak minyak ke sumur produksi disebut','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:16:"Gravity drainage";i:1;s:15:"Depletion drive";i:2;s:11:"Water drive";i:3;s:13:"Gas cap drive";}','','Gravity drainage','The drive mechanism that utilizes density differences between oil and gas to push oil toward production wells is called','a:4:{i:0;s:16:"Gravity drainage";i:1;s:15:"Depletion drive";i:2;s:11:"Water drive";i:3;s:13:"Gas cap drive";}','Gravity drainage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000224','Apa dampak utama dari penurunan tekanan reservoir di bawah bubble point pada mekanisme depletion drive?','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:67:"Terbentuknya gas bebas yang menurunkan permeabilitas relatif minyak";i:1;s:44:"Peningkatan viskositas minyak secara drastis";i:2;s:38:"Peningkatan saturasi air secara instan";i:3;s:24:"Hilangnya gaya gravitasi";}','','Terbentuknya gas bebas yang menurunkan permeabilitas relatif minyak','What is the primary impact of reservoir pressure dropping below the bubble point in a depletion drive mechanism?','a:4:{i:0;s:61:"Formation of free gas which reduces oil relative permeability";i:1;s:33:"Drastic increase in oil viscosity";i:2;s:42:"Instantaneous increase in water saturation";i:3;s:21:"Loss of gravity force";}','Formation of free gas which reduces oil relative permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000225','Saturasi minyak residual (Sor) secara teknis didefinisikan sebagai','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:69:"Fraksi minyak yang terperangkap dalam pori setelah proses pendorongan";i:1;s:41:"Minyak awal di reservoir sebelum produksi";i:2;s:51:"Jumlah minyak yang dapat diproduksi secara ekonomis";i:3;s:39:"Minyak yang mengalir bebas ke permukaan";}','','Fraksi minyak yang terperangkap dalam pori setelah proses pendorongan','Residual oil saturation (Sor) is technically defined as','a:4:{i:0;s:61:"Fraction of oil trapped in pores after a displacement process";i:1;s:46:"Initial oil in the reservoir before production";i:2;s:47:"Amount of oil that can be produced economically";i:3;s:36:"Oil that flows freely to the surface";}','Fraction of oil trapped in pores after a displacement process','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000226','Manakah pernyataan yang benar mengenai mekanisme gas cap drive?','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:47:"Gas cap yang ekspansif mendesak minyak ke bawah";i:1;s:31:"Minyak mendesak gas cap ke atas";i:2;s:38:"Hanya mengandalkan tekanan air formasi";i:3;s:45:"Tidak ada gas yang terlibat dalam pendorongan";}','','Gas cap yang ekspansif mendesak minyak ke bawah','Which statement is correct regarding the gas cap drive mechanism?','a:4:{i:0;s:40:"An expansive gas cap pushes oil downward";i:1;s:29:"Oil pushes the gas cap upward";i:2;s:39:"Only relies on formation water pressure";i:3;s:38:"No gas is involved in the displacement";}','An expansive gas cap pushes oil downward','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000227','Pilih dua faktor yang dapat memperkecil nilai Sor dalam reservoir','multi','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:35:"Penurunan tegangan antar muka (IFT)";i:1;s:29:"Peningkatan viskositas minyak";i:2;s:46:"Perubahan wettability batuan menjadi water-wet";i:3;s:27:"Peningkatan tekanan kapiler";}','','a:2:{i:0;s:35:"Penurunan tegangan antar muka (IFT)";i:1;s:46:"Perubahan wettability batuan menjadi water-wet";}','Select two factors that can reduce the Sor value in a reservoir','a:4:{i:0;s:38:"Reduction in interfacial tension (IFT)";i:1;s:25:"Increase in oil viscosity";i:2;s:38:"Changing rock wettability to water-wet";i:3;s:30:"Increase in capillary pressure";}','a:2:{i:0;s:38:"Reduction in interfacial tension (IFT)";i:1;s:38:"Changing rock wettability to water-wet";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000228','Efisiensi recovery pada reservoir dengan mekanisme water drive sangat bergantung pada','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:20:"Konektivitas aquifer";i:1;s:20:"Jumlah sumur injeksi";i:2;s:24:"Kadar porositas sekunder";i:3;s:27:"Tekanan kapiler batuan saja";}','','Konektivitas aquifer','Recovery efficiency in a water drive reservoir is highly dependent on','a:4:{i:0;s:20:"Aquifer connectivity";i:1;s:25:"Number of injection wells";i:2;s:26:"Secondary porosity content";i:3;s:36:"Capillary pressure of the rock alone";}','Aquifer connectivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000229','Mengapa gravity drainage seringkali menjadi mekanisme yang paling efisien dalam pemulihan minyak?','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:67:"Karena memanfaatkan gaya alamiah yang konstan untuk drainase minyak";i:1;s:50:"Karena tekanan reservoir meningkat secara otomatis";i:2;s:54:"Karena air secara otomatis menggantikan seluruh minyak";i:3;s:38:"Karena tidak memerlukan sumur produksi";}','','Karena memanfaatkan gaya alamiah yang konstan untuk drainase minyak','Why is gravity drainage often the most efficient mechanism in oil recovery?','a:4:{i:0;s:61:"Because it utilizes a constant natural force for oil drainage";i:1;s:50:"Because reservoir pressure increases automatically";i:2;s:44:"Because water automatically replaces all oil";i:3;s:44:"Because it does not require production wells";}','Because it utilizes a constant natural force for oil drainage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000230','Metode EOR mana yang paling efektif untuk reservoir minyak berat dengan viskositas tinggi guna menurunkan viskositas minyak secara drastis?','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:15:"Injeksi Polymer";i:1;s:20:"Injeksi Gas Miscible";i:2;s:16:"Thermal Recovery";i:3;s:15:"Injeksi Mikroba";}','','Thermal Recovery','Which EOR method is most effective for heavy oil reservoirs with high viscosity to drastically reduce oil viscosity?','a:4:{i:0;s:17:"Polymer Injection";i:1;s:22:"Miscible Gas Injection";i:2;s:16:"Thermal Recovery";i:3;s:19:"Microbial Injection";}','Thermal Recovery','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000231','Faktor utama yang membatasi penerapan injeksi gas miscible pada reservoir adalah sebagai berikut','multi','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:42:"Tekanan reservoir minimum yang disyaratkan";i:1;s:19:"Kedalaman reservoir";i:2;s:16:"Komposisi minyak";i:3;s:14:"Viskositas air";}','','a:2:{i:0;s:42:"Tekanan reservoir minimum yang disyaratkan";i:1;s:16:"Komposisi minyak";}','The main factors that limit the application of miscible gas injection in a reservoir are','a:4:{i:0;s:37:"Required minimum miscibility pressure";i:1;s:15:"Reservoir depth";i:2;s:15:"Oil composition";i:3;s:15:"Water viscosity";}','a:2:{i:0;s:37:"Required minimum miscibility pressure";i:1;s:15:"Oil composition";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000232','Manakah dari berikut ini yang merupakan mekanisme utama injeksi polymer dalam meningkatkan perolehan minyak?','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:35:"Menurunkan tegangan antarmuka (IFT)";i:1;s:35:"Meningkatkan viskositas air injeksi";i:2;s:25:"Mengubah kebasahan batuan";i:3;s:28:"Meningkatkan tekanan injeksi";}','','Meningkatkan viskositas air injeksi','Which of the following is the primary mechanism of polymer flooding in improving oil recovery?','a:4:{i:0;s:34:"Reducing Interfacial Tension (IFT)";i:1;s:36:"Increasing injection water viscosity";i:2;s:25:"Altering rock wettability";i:3;s:29:"Increasing injection pressure";}','Increasing injection water viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000233','Kriteria screening untuk injeksi thermal biasanya memerlukan nilai permeabilitas yang tinggi, yakni sekitar di atas','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:5:"10 mD";i:1;s:5:"50 mD";i:2;s:6:"200 mD";i:3;s:7:"1000 mD";}','','200 mD','Screening criteria for thermal injection usually require a high permeability value, which is around above','a:4:{i:0;s:5:"10 mD";i:1;s:5:"50 mD";i:2;s:6:"200 mD";i:3;s:7:"1000 mD";}','200 mD','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000234','Injeksi surfaktan dalam CEOR berfungsi terutama untuk','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:35:"Menurunkan tegangan antarmuka (IFT)";i:1;s:30:"Meningkatkan viskositas minyak";i:2;s:17:"Membekukan minyak";i:3;s:27:"Menurunkan porositas batuan";}','','Menurunkan tegangan antarmuka (IFT)','Surfactant injection in CEOR primarily functions to','a:4:{i:0;s:32:"Reduce Interfacial Tension (IFT)";i:1;s:22:"Increase oil viscosity";i:2;s:14:"Freeze the oil";i:3;s:22:"Decrease rock porosity";}','Reduce Interfacial Tension (IFT)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000235','Metode microbial EOR (MEOR) memanfaatkan aktivitas mikroba untuk memproduksi produk sampingan berupa','multi','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:16:"Gas (CO2/Metana)";i:1;s:18:"Asam dan surfaktan";i:2;s:7:"Polimer";i:3;s:11:"Logam berat";}','','a:3:{i:0;s:16:"Gas (CO2/Metana)";i:1;s:18:"Asam dan surfaktan";i:2;s:7:"Polimer";}','Microbial EOR (MEOR) methods utilize microbial activity to produce by-products in the form of','a:4:{i:0;s:17:"Gas (CO2/Methane)";i:1;s:21:"Acids and surfactants";i:2;s:8:"Polymers";i:3;s:12:"Heavy metals";}','a:3:{i:0;s:17:"Gas (CO2/Methane)";i:1;s:21:"Acids and surfactants";i:2;s:8:"Polymers";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000236','Batas maksimum viskositas minyak untuk penerapan injeksi polymer yang umum adalah sekitar','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:5:"10 cP";i:1;s:6:"150 cP";i:2;s:6:"500 cP";i:3;s:7:"1000 cP";}','','150 cP','The typical maximum oil viscosity limit for polymer injection application is around','a:4:{i:0;s:5:"10 cP";i:1;s:6:"150 cP";i:2;s:6:"500 cP";i:3;s:7:"1000 cP";}','150 cP','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000237','Injeksi gas miscible sangat bergantung pada parameter reservoir berikut ini','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:65:"Tekanan reservoir harus di atas tekanan misibilitas minimum (MMP)";i:1;s:48:"Suhu reservoir harus di bawah 20 derajat Celcius";i:2;s:27:"Porositas harus di bawah 5%";i:3;s:34:"Permeabilitas harus di bawah 10 mD";}','','Tekanan reservoir harus di atas tekanan misibilitas minimum (MMP)','Miscible gas injection is highly dependent on the following reservoir parameter','a:4:{i:0;s:71:"Reservoir pressure must be above the Minimum Miscibility Pressure (MMP)";i:1;s:54:"Reservoir temperature must be below 20 degrees Celsius";i:2;s:25:"Porosity must be below 5%";i:3;s:32:"Permeability must be below 10 mD";}','Reservoir pressure must be above the Minimum Miscibility Pressure (MMP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000238','Mengapa injeksi thermal (seperti Steam Flooding) tidak disarankan untuk reservoir yang sangat dalam?','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:50:"Karena kehilangan panas yang besar di dalam tubing";i:1;s:29:"Karena tekanan terlalu rendah";i:2;s:38:"Karena minyak akan berubah menjadi gas";i:3;s:26:"Karena batuan akan mencair";}','','Karena kehilangan panas yang besar di dalam tubing','Why is thermal injection (such as Steam Flooding) not recommended for very deep reservoirs?','a:4:{i:0;s:42:"Because of massive heat loss in the tubing";i:1;s:31:"Because the pressure is too low";i:2;s:34:"Because the oil will turn into gas";i:3;s:26:"Because the rock will melt";}','Because of massive heat loss in the tubing','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000239','Kriteria utama untuk suksesnya penerapan chemical flooding adalah','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:76:"Suhu reservoir yang tidak terlalu tinggi agar bahan kimia tidak terdegradasi";i:1;s:40:"Salinitas air formasi yang sangat tinggi";i:2;s:32:"Keberadaan gas bebas yang banyak";i:3;s:33:"Kedalaman reservoir harus dangkal";}','','Suhu reservoir yang tidak terlalu tinggi agar bahan kimia tidak terdegradasi','The key criterion for a successful chemical flooding application is','a:4:{i:0;s:69:"Reservoir temperature is not too high to prevent chemical degradation";i:1;s:34:"Very high formation water salinity";i:2;s:32:"Presence of significant free gas";i:3;s:31:"Reservoir depth must be shallow";}','Reservoir temperature is not too high to prevent chemical degradation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000240','Apa fungsi utama penambahan polimer ke dalam fluida injeksi pada proses Polymer Flooding?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:35:"Meningkatkan viskositas air injeksi";i:1;s:33:"Mengurangi tekanan kapiler batuan";i:2;s:49:"Meningkatkan wettability batuan menjadi water-wet";i:3;s:46:"Menurunkan saturasi minyak residu di pori-pori";}','','Meningkatkan viskositas air injeksi','What is the primary function of adding polymers to the injection fluid in the Polymer Flooding process?','a:4:{i:0;s:34:"Increase injection water viscosity";i:1;s:30:"Reduce rock capillary pressure";i:2;s:36:"Change rock wettability to water-wet";i:3;s:38:"Lower residual oil saturation in pores";}','Increase injection water viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000241','Pilih faktor-faktor yang dipengaruhi langsung oleh penurunan mobility ratio (M) dalam proses Polymer Flooding.','multi','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:28:"Peningkatan sweep efficiency";i:1;s:27:"Penurunan saturasi air awal";i:2;s:40:"Perbaikan distribusi aliran di reservoir";i:3;s:40:"Peningkatan permeabilitas absolut batuan";}','','a:2:{i:0;s:28:"Peningkatan sweep efficiency";i:1;s:40:"Perbaikan distribusi aliran di reservoir";}','Select factors that are directly influenced by the reduction of mobility ratio (M) in the Polymer Flooding process.','a:4:{i:0;s:31:"Improvement in sweep efficiency";i:1;s:36:"Decrease in initial water saturation";i:2;s:49:"Improvement in flow distribution in the reservoir";i:3;s:38:"Increase in absolute rock permeability";}','a:2:{i:0;s:31:"Improvement in sweep efficiency";i:1;s:49:"Improvement in flow distribution in the reservoir";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000242','Bagaimana pengaruh peningkatan viskositas air terhadap nilai mobility ratio (M)?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:20:"Meningkatkan nilai M";i:1;s:18:"Menurunkan nilai M";i:2;s:31:"Membuat nilai M menjadi konstan";i:3;s:26:"Tidak mempengaruhi nilai M";}','','Menurunkan nilai M','How does the increase in water viscosity affect the mobility ratio (M) value?','a:4:{i:0;s:17:"Increases M value";i:1;s:17:"Decreases M value";i:2;s:22:"Makes M value constant";i:3;s:23:"Does not affect M value";}','Decreases M value','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000243','Apa yang dimaksud dengan mobility ratio (M) dalam konteks EOR?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:75:"Perbandingan mobilitas fluida pendesak dengan mobilitas fluida yang didesak";i:1;s:52:"Perbandingan viskositas minyak dengan viskositas air";i:2;s:51:"Perbandingan permeabilitas relatif dengan porositas";i:3;s:55:"Perbandingan kecepatan injeksi dengan tekanan reservoir";}','','Perbandingan mobilitas fluida pendesak dengan mobilitas fluida yang didesak','What is meant by mobility ratio (M) in the context of EOR?','a:4:{i:0;s:62:"Ratio of displacing fluid mobility to displaced fluid mobility";i:1;s:41:"Ratio of oil viscosity to water viscosity";i:2;s:42:"Ratio of relative permeability to porosity";i:3;s:45:"Ratio of injection rate to reservoir pressure";}','Ratio of displacing fluid mobility to displaced fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000244','Mengapa mobility ratio yang tidak menguntungkan (M > 1) menyebabkan penurunan sweep efficiency?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:34:"Terjadi fenomena viscous fingering";i:1;s:38:"Tekanan injeksi menjadi terlalu rendah";i:2;s:46:"Polimer teradsorpsi terlalu banyak pada batuan";i:3;s:47:"Viskositas air menjadi lebih tinggi dari minyak";}','','Terjadi fenomena viscous fingering','Why does an unfavorable mobility ratio (M > 1) lead to a decrease in sweep efficiency?','a:4:{i:0;s:35:"Viscous fingering phenomenon occurs";i:1;s:34:"Injection pressure becomes too low";i:2;s:38:"Polymer adsorbs too much onto the rock";i:3;s:39:"Water viscosity becomes higher than oil";}','Viscous fingering phenomenon occurs','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000245','Dalam desain Polymer Flooding, apa target utama dari kontrol mobilitas?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:61:"Mencapai mobility ratio yang lebih rendah atau mendekati satu";i:1;s:57:"Meningkatkan saturasi minyak residu agar mudah diproduksi";i:2;s:59:"Menghentikan aliran air di zona dengan permeabilitas tinggi";i:3;s:43:"Mempercepat waktu tembus (breakthrough) air";}','','Mencapai mobility ratio yang lebih rendah atau mendekati satu','In Polymer Flooding design, what is the main target of mobility control?','a:4:{i:0;s:51:"Achieve a mobility ratio lower than or close to one";i:1;s:54:"Increase residual oil saturation for easier production";i:2;s:42:"Stop water flow in high permeability zones";i:3;s:34:"Accelerate water breakthrough time";}','Achieve a mobility ratio lower than or close to one','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000246','Manakah pernyataan yang tepat mengenai hubungan antara viskositas polimer dan sweep efficiency?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:64:"Semakin tinggi viskositas polimer, semakin baik sweep efficiency";i:1;s:65:"Semakin tinggi viskositas polimer, semakin buruk sweep efficiency";i:2;s:57:"Sweep efficiency tidak bergantung pada viskositas polimer";i:3;s:55:"Viskositas polimer hanya mempengaruhi biaya operasional";}','','Semakin tinggi viskositas polimer, semakin baik sweep efficiency','Which statement is correct regarding the relationship between polymer viscosity and sweep efficiency?','a:4:{i:0;s:57:"Higher polymer viscosity leads to better sweep efficiency";i:1;s:56:"Higher polymer viscosity leads to worse sweep efficiency";i:2;s:53:"Sweep efficiency does not depend on polymer viscosity";i:3;s:48:"Polymer viscosity only affects operational costs";}','Higher polymer viscosity leads to better sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000247','Komponen apa saja yang menentukan besarnya mobilitas fluida (lambda) dalam hukum Darcy?','multi','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:21:"Permeabilitas efektif";i:1;s:17:"Viskositas fluida";i:2;s:16:"Porositas batuan";i:3;s:15:"Tekanan kapiler";}','','a:2:{i:0;s:21:"Permeabilitas efektif";i:1;s:17:"Viskositas fluida";}','Which components determine the magnitude of fluid mobility (lambda) in Darcy''s Law?','a:4:{i:0;s:22:"Effective permeability";i:1;s:15:"Fluid viscosity";i:2;s:13:"Rock porosity";i:3;s:18:"Capillary pressure";}','a:2:{i:0;s:22:"Effective permeability";i:1;s:15:"Fluid viscosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000248','Apa yang terjadi pada profil injeksi air di reservoir heterogen jika polimer ditambahkan?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:55:"Aliran lebih merata ke zona dengan permeabilitas rendah";i:1;s:57:"Air hanya mengalir ke zona dengan permeabilitas tertinggi";i:2;s:33:"Kecepatan injeksi menurun drastis";i:3;s:38:"Saturasi air di zona permeabel menurun";}','','Aliran lebih merata ke zona dengan permeabilitas rendah','What happens to the water injection profile in a heterogeneous reservoir if polymers are added?','a:4:{i:0;s:55:"Flow becomes more uniform into lower permeability zones";i:1;s:52:"Water only flows into the highest permeability zones";i:2;s:36:"Injection rate decreases drastically";i:3;s:45:"Water saturation in permeable zones decreases";}','Flow becomes more uniform into lower permeability zones','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000249','Manakah dari berikut ini yang merupakan tujuan utama perbaikan volumetric sweep efficiency?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:72:"Menjangkau minyak di zona yang sebelumnya tidak tersapu oleh air injeksi";i:1;s:47:"Mengubah sifat kimia minyak mentah di reservoir";i:2;s:47:"Menghilangkan efek gravitasi di dalam reservoir";i:3;s:40:"Mengurangi biaya penanganan air produksi";}','','Menjangkau minyak di zona yang sebelumnya tidak tersapu oleh air injeksi','Which of the following is a primary objective of improving volumetric sweep efficiency?','a:4:{i:0;s:61:"Contacting oil in zones previously unswept by injection water";i:1;s:62:"Changing the chemical properties of crude oil in the reservoir";i:2;s:50:"Eliminating gravitational effects in the reservoir";i:3;s:38:"Reducing produced water handling costs";}','Contacting oil in zones previously unswept by injection water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000250','Apa perbedaan utama antara polimer sintetik HPAM dan biopolimer Xanthan dalam konteks injeksi polimer?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:64:"HPAM bersifat pseudoplastik sedangkan Xanthan bersifat Newtonian";i:1;s:63:"HPAM lebih tahan terhadap salinitas tinggi dibandingkan Xanthan";i:2;s:103:"Struktur molekul HPAM berbentuk rantai linier fleksibel sedangkan Xanthan memiliki struktur heliks kaku";i:3;s:70:"Xanthan mengalami degradasi mekanik yang lebih parah dibandingkan HPAM";}','','Struktur molekul HPAM berbentuk rantai linier fleksibel sedangkan Xanthan memiliki struktur heliks kaku','What is the main difference between synthetic HPAM polymers and Xanthan biopolymers in the context of polymer injection?','a:4:{i:0;s:48:"HPAM is pseudoplastic while Xanthan is Newtonian";i:1;s:59:"HPAM is more resistant to high salinity compared to Xanthan";i:2;s:95:"HPAM molecular structure is a flexible linear chain while Xanthan has a rigid helical structure";i:3;s:62:"Xanthan undergoes more severe mechanical degradation than HPAM";}','HPAM molecular structure is a flexible linear chain while Xanthan has a rigid helical structure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000251','Sifat rheologi polimer HPAM sangat dipengaruhi oleh salinitas. Apa yang terjadi pada viskositas larutan HPAM saat salinitas air formasi meningkat?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:28:"Viskositas meningkat drastis";i:1;s:65:"Viskositas menurun karena efek pelipatan rantai polimer (coiling)";i:2;s:45:"Viskositas tetap stabil tanpa dipengaruhi ion";i:3;s:54:"Viskositas meningkat karena pemanjangan rantai polimer";}','','Viskositas menurun karena efek pelipatan rantai polimer (coiling)','The rheological properties of HPAM polymers are highly influenced by salinity. What happens to the viscosity of HPAM solutions when formation water salinity increases?','a:4:{i:0;s:31:"Viscosity increases drastically";i:1;s:59:"Viscosity decreases due to the polymer chain coiling effect";i:2;s:43:"Viscosity remains stable regardless of ions";i:3;s:51:"Viscosity increases due to polymer chain elongation";}','Viscosity decreases due to the polymer chain coiling effect','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000252','Manakah faktor-faktor berikut yang dapat menyebabkan degradasi mekanik pada polimer saat melewati media berpori?','multi','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:52:"Laju alir yang sangat tinggi melalui pori-pori kecil";i:1;s:58:"Tekanan injeksi yang melebihi batas kekuatan tarik polimer";i:2;s:40:"Kadar salinitas yang rendah dalam fluida";i:3;s:47:"Suhu reservoir yang di bawah 50 derajat Celsius";}','','a:2:{i:0;s:52:"Laju alir yang sangat tinggi melalui pori-pori kecil";i:1;s:58:"Tekanan injeksi yang melebihi batas kekuatan tarik polimer";}','Which of the following factors can cause mechanical degradation of polymers when passing through porous media?','a:4:{i:0;s:40:"Very high flow rates through small pores";i:1;s:63:"Injection pressure exceeding the polymer tensile strength limit";i:2;s:32:"Low salinity levels in the fluid";i:3;s:47:"Reservoir temperatures below 50 degrees Celsius";}','a:2:{i:0;s:40:"Very high flow rates through small pores";i:1;s:63:"Injection pressure exceeding the polymer tensile strength limit";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000253','Mengapa Xanthan Gum dianggap lebih unggul dibandingkan HPAM dalam kondisi reservoir dengan salinitas yang tinggi?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:55:"Karena Xanthan memiliki berat molekul yang lebih rendah";i:1;s:68:"Karena struktur heliks Xanthan melindunginya dari efek screening ion";i:2;s:41:"Karena Xanthan lebih murah secara ekonomi";i:3;s:49:"Karena Xanthan mudah terdegradasi secara biologis";}','','Karena struktur heliks Xanthan melindunginya dari efek screening ion','Why is Xanthan Gum considered superior to HPAM in reservoir conditions with high salinity?','a:4:{i:0;s:44:"Because Xanthan has a lower molecular weight";i:1;s:74:"Because Xanthan''s helical structure protects it from ion screening effects";i:2;s:47:"Because Xanthan is more economically affordable";i:3;s:39:"Because Xanthan is easily biodegradable";}','Because Xanthan''s helical structure protects it from ion screening effects','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000254','Dalam uji laboratorium, fenomena apa yang terjadi jika laju geser (shear rate) pada larutan polimer ditingkatkan?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:34:"Viskositas meningkat secara linier";i:1;s:64:"Larutan polimer menunjukkan sifat shear-thinning (pseudoplastik)";i:2;s:61:"Larutan polimer menunjukkan sifat dilatant (shear-thickening)";i:3;s:30:"Tidak ada perubahan viskositas";}','','Larutan polimer menunjukkan sifat shear-thinning (pseudoplastik)','In laboratory tests, what phenomenon occurs if the shear rate of a polymer solution is increased?','a:4:{i:0;s:28:"Viscosity increases linearly";i:1;s:71:"The polymer solution exhibits shear-thinning (pseudoplastic) properties";i:2;s:68:"The polymer solution exhibits dilatant (shear-thickening) properties";i:3;s:31:"There is no change in viscosity";}','The polymer solution exhibits shear-thinning (pseudoplastic) properties','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000255','Apa dampak negatif dari degradasi termal pada polimer HPAM di reservoir dengan suhu tinggi?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:44:"Peningkatan viskositas yang tidak terkendali";i:1;s:62:"Pemutusan rantai polimer yang menyebabkan penurunan viskositas";i:2;s:45:"Pembentukan endapan padat yang menyumbat pori";i:3;s:50:"Peningkatan kemampuan polimer untuk menyapu minyak";}','','Pemutusan rantai polimer yang menyebabkan penurunan viskositas','What is the negative impact of thermal degradation on HPAM polymers in high-temperature reservoirs?','a:4:{i:0;s:31:"Uncontrolled viscosity increase";i:1;s:48:"Polymer chain scission leading to viscosity loss";i:2;s:43:"Formation of solid deposits that plug pores";i:3;s:36:"Improved polymer sweeping efficiency";}','Polymer chain scission leading to viscosity loss','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000256','Manakah pernyataan yang benar mengenai sifat rheologi polimer Xanthan?','multi','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:55:"Viskositasnya tidak sensitif terhadap konsentrasi garam";i:1;s:52:"Menunjukkan viskositas tinggi pada laju geser rendah";i:2;s:64:"Sangat mudah terdegradasi oleh bakteri jika tidak diberi biosida";i:3;s:46:"Bersifat Newtonian murni pada semua laju geser";}','','a:3:{i:0;s:55:"Viskositasnya tidak sensitif terhadap konsentrasi garam";i:1;s:52:"Menunjukkan viskositas tinggi pada laju geser rendah";i:2;s:64:"Sangat mudah terdegradasi oleh bakteri jika tidak diberi biosida";}','Which statements are correct regarding the rheological properties of Xanthan polymers?','a:4:{i:0;s:50:"Its viscosity is insensitive to salt concentration";i:1;s:39:"Shows high viscosity at low shear rates";i:2;s:72:"Highly susceptible to bacterial degradation if not treated with biocides";i:3;s:38:"Is purely Newtonian at all shear rates";}','a:3:{i:0;s:50:"Its viscosity is insensitive to salt concentration";i:1;s:39:"Shows high viscosity at low shear rates";i:2;s:72:"Highly susceptible to bacterial degradation if not treated with biocides";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000257','Bagaimana pengaruh penambahan polimer terhadap mobilitas fluida di dalam reservoir?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:47:"Meningkatkan mobilitas untuk mempercepat aliran";i:1;s:59:"Menurunkan mobilitas dengan meningkatkan viskositas larutan";i:2;s:47:"Mengurangi permeabilitas batuan secara permanen";i:3;s:43:"Tidak mengubah mobilitas fluida sama sekali";}','','Menurunkan mobilitas dengan meningkatkan viskositas larutan','How does the addition of polymers affect fluid mobility within the reservoir?','a:4:{i:0;s:37:"Increases mobility to accelerate flow";i:1;s:51:"Decreases mobility by increasing solution viscosity";i:2;s:37:"Permanently reduces rock permeability";i:3;s:37:"Does not change fluid mobility at all";}','Decreases mobility by increasing solution viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000258','Faktor apa yang paling menentukan ketahanan polimer HPAM terhadap degradasi hidrolisis dalam lingkungan reservoir?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:43:"Derajat hidrolisis dan temperatur reservoir";i:1;s:34:"Tingkat kekasaran permukaan batuan";i:2;s:23:"Jumlah injeksi air laut";i:3;s:41:"Kecepatan adsorpsi pada permukaan mineral";}','','Derajat hidrolisis dan temperatur reservoir','What factor most determines the resistance of HPAM polymers to hydrolysis degradation in the reservoir environment?','a:4:{i:0;s:46:"Degree of hydrolysis and reservoir temperature";i:1;s:29:"Surface roughness of the rock";i:2;s:28:"Amount of seawater injection";i:3;s:35:"Adsorption rate on mineral surfaces";}','Degree of hydrolysis and reservoir temperature','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000259','Dalam konteks aplikasi EOR, apa yang dimaksud dengan ''adsorpsi polimer''?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:56:"Penempelan molekul polimer pada permukaan butiran batuan";i:1;s:37:"Larutnya polimer ke dalam fase minyak";i:2;s:38:"Proses penguapan polimer di dalam pori";i:3;s:34:"Pencampuran polimer dengan gas CO2";}','','Penempelan molekul polimer pada permukaan butiran batuan','In the context of EOR applications, what is meant by ''polymer adsorption''?','a:4:{i:0;s:57:"Attachment of polymer molecules to the rock grain surface";i:1;s:41:"Dissolution of polymer into the oil phase";i:2;s:47:"Process of polymer evaporation within the pores";i:3;s:31:"Mixing of polymers with CO2 gas";}','Attachment of polymer molecules to the rock grain surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000260','Apa parameter utama yang menentukan mobilitas fluida injeksi dalam desain polymer flooding?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:43:"Viskositas polimer dan permeabilitas batuan";i:1;s:37:"Tekanan injeksi dan porositas efektif";i:2;s:43:"Temperatur formasi dan saturasi minyak sisa";i:3;s:43:"Salinitas air formasi dan kelarutan polimer";}','','Viskositas polimer dan permeabilitas batuan','What is the primary parameter determining injection fluid mobility in polymer flooding design?','a:4:{i:0;s:39:"Polymer viscosity and rock permeability";i:1;s:41:"Injection pressure and effective porosity";i:2;s:49:"Formation temperature and residual oil saturation";i:3;s:47:"Formation water salinity and polymer solubility";}','Polymer viscosity and rock permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000261','Faktor apa saja yang harus dipertimbangkan dalam menentukan ukuran slug (slug size) polimer?','multi','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:38:"Efisiensi penyapuan (sweep efficiency)";i:1;s:17:"Biaya bahan kimia";i:2;s:23:"Heterogenitas reservoir";i:3;s:24:"Kecepatan injeksi fluida";}','','a:3:{i:0;s:38:"Efisiensi penyapuan (sweep efficiency)";i:1;s:17:"Biaya bahan kimia";i:2;s:23:"Heterogenitas reservoir";}','What factors must be considered when determining the polymer slug size?','a:4:{i:0;s:16:"Sweep efficiency";i:1;s:14:"Chemical costs";i:2;s:23:"Reservoir heterogeneity";i:3;s:20:"Fluid injection rate";}','a:3:{i:0;s:16:"Sweep efficiency";i:1;s:14:"Chemical costs";i:2;s:23:"Reservoir heterogeneity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000262','Bagaimana pengaruh peningkatan konsentrasi polimer terhadap injektivitas di dalam reservoir?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:48:"Injektivitas menurun karena viskositas meningkat";i:1;s:48:"Injektivitas meningkat karena viskositas menurun";i:2;s:40:"Tidak ada pengaruh terhadap injektivitas";i:3;s:55:"Injektivitas meningkat secara linier dengan konsentrasi";}','','Injektivitas menurun karena viskositas meningkat','How does increasing polymer concentration affect injectivity within the reservoir?','a:4:{i:0;s:48:"Injectivity decreases due to increased viscosity";i:1;s:48:"Injectivity increases due to decreased viscosity";i:2;s:24:"No effect on injectivity";i:3;s:49:"Injectivity increases linearly with concentration";}','Injectivity decreases due to increased viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000263','Apa yang dimaksud dengan ''adsorpsi polimer'' dalam konteks desain CEOR?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:56:"Kehilangan polimer akibat menempel pada permukaan batuan";i:1;s:48:"Peningkatan konsentrasi polimer karena penguapan";i:2;s:36:"Pengenceran polimer oleh air formasi";i:3;s:41:"Reaksi kimia polimer dengan minyak mentah";}','','Kehilangan polimer akibat menempel pada permukaan batuan','What is meant by ''polymer adsorption'' in the context of CEOR design?','a:4:{i:0;s:47:"Polymer loss due to attachment to rock surfaces";i:1;s:49:"Polymer concentration increase due to evaporation";i:2;s:35:"Polymer dilution by formation water";i:3;s:43:"Chemical reaction of polymer with crude oil";}','Polymer loss due to attachment to rock surfaces','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000264','Dalam studi kasus implementasi lapangan, apa tantangan utama penggunaan polimer HPAM pada reservoir dengan salinitas tinggi?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:50:"Degradasi viskositas akibat sensitivitas salinitas";i:1;s:30:"Polimer menjadi terlalu kental";i:2;s:30:"Polimer mengalami kristalisasi";i:3;s:44:"Kebutuhan tekanan injeksi yang sangat rendah";}','','Degradasi viskositas akibat sensitivitas salinitas','In field implementation case studies, what is the main challenge of using HPAM polymers in high-salinity reservoirs?','a:4:{i:0;s:49:"Viscosity degradation due to salinity sensitivity";i:1;s:27:"Polymer becomes too viscous";i:2;s:33:"Polymer undergoes crystallization";i:3;s:43:"Requirement for very low injection pressure";}','Viscosity degradation due to salinity sensitivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000265','Apa tujuan utama penambahan ''tracer'' dalam uji injeksi polimer?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:39:"Melacak jalur aliran (flow path) fluida";i:1;s:30:"Meningkatkan viskositas fluida";i:2;s:27:"Mengurangi adsorpsi polimer";i:3;s:24:"Mengukur tekanan kapiler";}','','Melacak jalur aliran (flow path) fluida','What is the primary purpose of adding a ''tracer'' in polymer injection tests?','a:4:{i:0;s:25:"To track fluid flow paths";i:1;s:27:"To increase fluid viscosity";i:2;s:28:"To reduce polymer adsorption";i:3;s:29:"To measure capillary pressure";}','To track fluid flow paths','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000266','Fenomena apa yang menyebabkan hambatan aliran (resistance factor) meningkat selama injeksi polimer?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:52:"Penyumbatan pori (pore plugging) dan viscoelasticity";i:1;s:29:"Penurunan tegangan antar muka";i:2;s:25:"Peningkatan kelarutan gas";i:3;s:24:"Pengurangan saturasi air";}','','Penyumbatan pori (pore plugging) dan viscoelasticity','What phenomenon causes the resistance factor to increase during polymer injection?','a:4:{i:0;s:33:"Pore plugging and viscoelasticity";i:1;s:32:"Reduction in interfacial tension";i:2;s:26:"Increase in gas solubility";i:3;s:29:"Reduction in water saturation";}','Pore plugging and viscoelasticity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000267','Manakah pernyataan yang benar mengenai desain slug polimer?','multi','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:56:"Konsentrasi polimer disesuaikan dengan viskositas minyak";i:1;s:63:"Ukuran slug biasanya berkisar antara 0.5 hingga 1.0 pore volume";i:2;s:52:"Suhu reservoir tidak mempengaruhi stabilitas polimer";i:3;s:53:"Kompatibilitas polimer dengan air formasi harus diuji";}','','a:3:{i:0;s:56:"Konsentrasi polimer disesuaikan dengan viskositas minyak";i:1;s:63:"Ukuran slug biasanya berkisar antara 0.5 hingga 1.0 pore volume";i:2;s:53:"Kompatibilitas polimer dengan air formasi harus diuji";}','Which statements are true regarding polymer slug design?','a:4:{i:0;s:50:"Polymer concentration is adjusted to oil viscosity";i:1;s:45:"Slug size is typically 0.5 to 1.0 pore volume";i:2;s:55:"Reservoir temperature does not affect polymer stability";i:3;s:57:"Polymer compatibility with formation water must be tested";}','a:3:{i:0;s:50:"Polymer concentration is adjusted to oil viscosity";i:1;s:45:"Slug size is typically 0.5 to 1.0 pore volume";i:2;s:57:"Polymer compatibility with formation water must be tested";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000268','Mengapa ''shear degradation'' menjadi perhatian serius dalam desain fasilitas permukaan injeksi polimer?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:60:"Karena dapat menurunkan berat molekul polimer dan viskositas";i:1;s:43:"Karena menyebabkan korosi pada pipa injeksi";i:2;s:43:"Karena meningkatkan biaya operasional pompa";i:3;s:44:"Karena menyebabkan pemisahan fase minyak-air";}','','Karena dapat menurunkan berat molekul polimer dan viskositas','Why is ''shear degradation'' a serious concern in the design of polymer injection surface facilities?','a:4:{i:0;s:60:"Because it can reduce polymer molecular weight and viscosity";i:1;s:46:"Because it causes corrosion in injection pipes";i:2;s:41:"Because it increases pump operating costs";i:3;s:44:"Because it causes oil-water phase separation";}','Because it can reduce polymer molecular weight and viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000269','Apa dampak utama dari keberhasilan desain mobilitas rasio dalam polymer flooding?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:46:"Peningkatan perolehan minyak (recovery factor)";i:1;s:28:"Peningkatan biaya pengeboran";i:2;s:40:"Penurunan tekanan injeksi secara drastis";i:3;s:42:"Eliminasi total dari air sisa di reservoir";}','','Peningkatan perolehan minyak (recovery factor)','What is the primary impact of a successful mobility ratio design in polymer flooding?','a:4:{i:0;s:40:"Increased oil recovery (recovery factor)";i:1;s:24:"Increased drilling costs";i:2;s:39:"Drastic reduction in injection pressure";i:3;s:52:"Total elimination of residual water in the reservoir";}','Increased oil recovery (recovery factor)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000270','Apa fungsi utama penambahan surfaktan dalam proses Chemical Enhanced Oil Recovery (CEOR)?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:58:"Menurunkan tegangan antar muka (IFT) antara minyak dan air";i:1;s:50:"Meningkatkan viskositas air injeksi secara drastis";i:2;s:43:"Mengubah wettability batuan menjadi oil-wet";i:3;s:41:"Meningkatkan permeabilitas absolut batuan";}','','Menurunkan tegangan antar muka (IFT) antara minyak dan air','What is the primary function of adding surfactants in the Chemical Enhanced Oil Recovery (CEOR) process?','a:4:{i:0;s:60:"Lowering the interfacial tension (IFT) between oil and water";i:1;s:56:"Dramatically increasing the viscosity of injection water";i:2;s:36:"Changing rock wettability to oil-wet";i:3;s:48:"Increasing the absolute permeability of the rock";}','Lowering the interfacial tension (IFT) between oil and water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000271','Faktor apa saja yang menentukan besarnya Capillary Number (Nc)?','multi','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:20:"Kecepatan aliran (v)";i:1;s:22:"Viskositas fluida (μ)";i:2;s:25:"Tegangan antar muka (IFT)";i:3;s:16:"Porositas batuan";}','','a:3:{i:0;s:20:"Kecepatan aliran (v)";i:1;s:22:"Viskositas fluida (μ)";i:2;s:25:"Tegangan antar muka (IFT)";}','What factors determine the magnitude of the Capillary Number (Nc)?','a:4:{i:0;s:17:"Flow velocity (v)";i:1;s:20:"Fluid viscosity (μ)";i:2;s:25:"Interfacial tension (IFT)";i:3;s:13:"Rock porosity";}','a:3:{i:0;s:17:"Flow velocity (v)";i:1;s:20:"Fluid viscosity (μ)";i:2;s:25:"Interfacial tension (IFT)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000272','Bagaimana hubungan antara Capillary Number dan saturasi minyak residual (Sor)?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:49:"Semakin besar Capillary Number, semakin kecil Sor";i:1;s:49:"Semakin besar Capillary Number, semakin besar Sor";i:2;s:23:"Hubungan linear positif";i:3;s:34:"Tidak ada hubungan antara keduanya";}','','Semakin besar Capillary Number, semakin kecil Sor','What is the relationship between the Capillary Number and residual oil saturation (Sor)?','a:4:{i:0;s:50:"The larger the Capillary Number, the lower the Sor";i:1;s:51:"The larger the Capillary Number, the higher the Sor";i:2;s:28:"Positive linear relationship";i:3;s:31:"No relationship between the two";}','The larger the Capillary Number, the lower the Sor','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000273','Pada kondisi reservoir normal, gaya apa yang paling dominan menahan minyak di dalam pori-pori batuan?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:12:"Gaya kapiler";i:1;s:14:"Gaya gravitasi";i:2;s:12:"Gaya inersia";i:3;s:11:"Gaya viskos";}','','Gaya kapiler','Under normal reservoir conditions, which force is most dominant in trapping oil within the rock pores?','a:4:{i:0;s:15:"Capillary force";i:1;s:13:"Gravity force";i:2;s:14:"Inertial force";i:3;s:13:"Viscous force";}','Capillary force','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000274','Berapa besaran penurunan IFT yang diperlukan agar minyak residual dapat termobilisasi secara signifikan?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:32:"Penurunan hingga orde 10^-3 mN/m";i:1;s:32:"Penurunan hingga orde 10^-1 mN/m";i:2;s:25:"Tidak perlu penurunan IFT";i:3;s:31:"Peningkatan IFT hingga 100 mN/m";}','','Penurunan hingga orde 10^-3 mN/m','What magnitude of IFT reduction is required to significantly mobilize residual oil?','a:4:{i:0;s:36:"Reduction to the order of 10^-3 mN/m";i:1;s:36:"Reduction to the order of 10^-1 mN/m";i:2;s:23:"No IFT reduction needed";i:3;s:27:"Increase in IFT to 100 mN/m";}','Reduction to the order of 10^-3 mN/m','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000275','Apa yang terjadi pada tetesan minyak residual ketika Capillary Number ditingkatkan melampaui batas kritis?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:60:"Tetesan minyak terdeformasi dan dapat bergerak melewati pori";i:1;s:53:"Tetesan minyak pecah menjadi mikro-emulsi yang stabil";i:2;s:43:"Tetesan minyak akan terperangkap lebih kuat";i:3;s:51:"Tetesan minyak akan berikatan dengan mineral batuan";}','','Tetesan minyak terdeformasi dan dapat bergerak melewati pori','What happens to residual oil droplets when the Capillary Number is increased beyond the critical limit?','a:4:{i:0;s:46:"Oil droplets deform and can move through pores";i:1;s:46:"Oil droplets break into stable micro-emulsions";i:2;s:41:"Oil droplets become more strongly trapped";i:3;s:36:"Oil droplets bond with rock minerals";}','Oil droplets deform and can move through pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000276','Manakah pernyataan yang benar mengenai mekanisme ''roll-up'' pada surfaktan?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:51:"Surfaktan menggantikan minyak dari permukaan batuan";i:1;s:51:"Surfaktan meningkatkan gaya adhesi minyak ke batuan";i:2;s:33:"Surfaktan menghentikan aliran air";i:3;s:45:"Surfaktan meningkatkan tegangan permukaan air";}','','Surfaktan menggantikan minyak dari permukaan batuan','Which statement is correct regarding the ''roll-up'' mechanism of surfactants?','a:4:{i:0;s:46:"Surfactant displaces oil from the rock surface";i:1;s:41:"Surfactant increases oil adhesion to rock";i:2;s:27:"Surfactant stops water flow";i:3;s:42:"Surfactant increases water surface tension";}','Surfactant displaces oil from the rock surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000277','Pilih parameter yang memengaruhi keberhasilan mobilisasi minyak dalam Chemical EOR:','multi','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:21:"Salinitas air formasi";i:1;s:30:"Adsorpsi surfaktan pada batuan";i:2;s:20:"Temperatur reservoir";i:3;s:15:"Densitas batuan";}','','a:3:{i:0;s:21:"Salinitas air formasi";i:1;s:30:"Adsorpsi surfaktan pada batuan";i:2;s:20:"Temperatur reservoir";}','Select the parameters that affect the success of oil mobilization in Chemical EOR:','a:4:{i:0;s:24:"Formation water salinity";i:1;s:29:"Surfactant adsorption on rock";i:2;s:21:"Reservoir temperature";i:3;s:12:"Rock density";}','a:3:{i:0;s:24:"Formation water salinity";i:1;s:29:"Surfactant adsorption on rock";i:2;s:21:"Reservoir temperature";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000278','Apakah keuntungan dari tercapainya kondisi ''ultra-low IFT'' dalam aplikasi surfaktan?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:38:"Mengurangi gaya kapiler penahan minyak";i:1;s:30:"Meningkatkan viskositas minyak";i:2;s:33:"Mempercepat pengendapan surfaktan";i:3;s:40:"Menghilangkan kebutuhan akan injeksi air";}','','Mengurangi gaya kapiler penahan minyak','What is the advantage of achieving ''ultra-low IFT'' conditions in surfactant applications?','a:4:{i:0;s:42:"Reducing capillary forces trapping the oil";i:1;s:24:"Increasing oil viscosity";i:2;s:37:"Accelerating surfactant precipitation";i:3;s:40:"Eliminating the need for water injection";}','Reducing capillary forces trapping the oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000279','Dalam konteks mobilisasi minyak, apa peran dari ''mikro-emulsi''?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:60:"Memungkinkan minyak terlarut dalam fase air untuk diproduksi";i:1;s:31:"Meningkatkan tegangan permukaan";i:2;s:26:"Menyumbat pori-pori batuan";i:3;s:37:"Meningkatkan saturasi minyak residual";}','','Memungkinkan minyak terlarut dalam fase air untuk diproduksi','In the context of oil mobilization, what is the role of ''micro-emulsion''?','a:4:{i:0;s:64:"Enabling oil to be dissolved in the aqueous phase for production";i:1;s:26:"Increasing surface tension";i:2;s:19:"Plugging rock pores";i:3;s:34:"Increasing residual oil saturation";}','Enabling oil to be dissolved in the aqueous phase for production','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000280','Proses kimia utama yang terjadi ketika agen alkali bereaksi dengan asam naftenat dalam minyak mentah untuk membentuk surfaktan in-situ adalah','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:12:"Saponifikasi";i:1;s:12:"Emulsifikasi";i:2;s:8:"Adsorpsi";i:3;s:11:"Presipitasi";}','','Saponifikasi','The primary chemical process that occurs when alkaline agents react with naphthenic acids in crude oil to form in-situ surfactants is','a:4:{i:0;s:14:"Saponification";i:1;s:14:"Emulsification";i:2;s:10:"Adsorption";i:3;s:13:"Precipitation";}','Saponification','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000281','Apa fungsi utama penambahan alkali dalam sistem ASP (Alkaline-Surfactant-Polymer) terkait dengan interaksi batuan?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:51:"Mengurangi adsorpsi surfaktan pada permukaan batuan";i:1;s:35:"Meningkatkan viskositas air injeksi";i:2;s:43:"Mengubah wettability batuan menjadi oil-wet";i:3;s:28:"Meningkatkan tekanan kapiler";}','','Mengurangi adsorpsi surfaktan pada permukaan batuan','What is the primary function of adding alkali in an ASP (Alkaline-Surfactant-Polymer) system regarding rock interaction?','a:4:{i:0;s:47:"Reducing surfactant adsorption on rock surfaces";i:1;s:36:"Increasing injection water viscosity";i:2;s:36:"Changing rock wettability to oil-wet";i:3;s:29:"Increasing capillary pressure";}','Reducing surfactant adsorption on rock surfaces','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000282','Sinergi antara alkali dan surfaktan dalam proses EOR bertujuan untuk mencapai kondisi apa?','multi','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:44:"Tegangan antar muka (IFT) yang sangat rendah";i:1;s:37:"Kelarutan surfaktan yang lebih tinggi";i:2;s:30:"Pembentukan emulsi yang stabil";i:3;s:30:"Pengurangan konsumsi surfaktan";}','','a:2:{i:0;s:44:"Tegangan antar muka (IFT) yang sangat rendah";i:1;s:30:"Pengurangan konsumsi surfaktan";}','The synergy between alkali and surfactant in an EOR process aims to achieve which conditions?','a:4:{i:0;s:35:"Ultra-low interfacial tension (IFT)";i:1;s:28:"Higher surfactant solubility";i:2;s:29:"Formation of stable emulsions";i:3;s:35:"Reduction of surfactant consumption";}','a:2:{i:0;s:35:"Ultra-low interfacial tension (IFT)";i:1;s:35:"Reduction of surfactant consumption";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000283','Manakah dari berikut ini yang merupakan kelemahan potensial dari penggunaan alkali dalam flooding?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:35:"Pembentukan kerak (scale) anorganik";i:1;s:29:"Peningkatan viskositas minyak";i:2;s:24:"Penurunan pH air formasi";i:3;s:30:"Peningkatan adsorpsi surfaktan";}','','Pembentukan kerak (scale) anorganik','Which of the following is a potential disadvantage of using alkali in flooding?','a:4:{i:0;s:25:"Inorganic scale formation";i:1;s:23:"Increased oil viscosity";i:2;s:30:"Decrease in formation water pH";i:3;s:31:"Increased surfactant adsorption";}','Inorganic scale formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000284','Pada kondisi reservoir apa alkaline flooding paling efektif digunakan?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:43:"Minyak dengan kandungan asam organik tinggi";i:1;s:45:"Reservoir dengan salinitas yang sangat rendah";i:2;s:31:"Reservoir batuan karbonat murni";i:3;s:49:"Minyak dengan viskositas sangat tinggi (>1000 cP)";}','','Minyak dengan kandungan asam organik tinggi','Under what reservoir conditions is alkaline flooding most effectively applied?','a:4:{i:0;s:40:"Crude oil with high organic acid content";i:1;s:32:"Reservoir with very low salinity";i:2;s:29:"Pure carbonate rock reservoir";i:3;s:39:"Oil with very high viscosity (>1000 cP)";}','Crude oil with high organic acid content','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000285','Bagaimana mekanisme alkali mengurangi adsorpsi surfaktan pada batuan?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:53:"Membuat muatan permukaan batuan menjadi lebih negatif";i:1;s:42:"Meningkatkan kelarutan surfaktan dalam air";i:2;s:29:"Mengurangi viskositas larutan";i:3;s:31:"Meningkatkan tegangan permukaan";}','','Membuat muatan permukaan batuan menjadi lebih negatif','How does the alkaline mechanism reduce surfactant adsorption on rocks?','a:4:{i:0;s:47:"By making the rock surface charge more negative";i:1;s:44:"By increasing surfactant solubility in water";i:2;s:30:"By reducing solution viscosity";i:3;s:29:"By increasing surface tension";}','By making the rock surface charge more negative','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000286','Dalam sistem ASP, peran polimer adalah untuk','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:27:"Mengontrol mobilitas fluida";i:1;s:30:"Mengurangi tegangan antar muka";i:2;s:25:"Menetralkan asam naftenat";i:3;s:26:"Mencegah pembentukan scale";}','','Mengontrol mobilitas fluida','In an ASP system, the role of the polymer is to','a:4:{i:0;s:22:"Control fluid mobility";i:1;s:26:"Reduce interfacial tension";i:2;s:27:"Neutralize naphthenic acids";i:3;s:23:"Prevent scale formation";}','Control fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000287','Mengapa alkali dapat membantu mengubah kebasahan (wettability) batuan?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:68:"Melalui interaksi kimia dengan komponen minyak pada permukaan batuan";i:1;s:35:"Dengan meningkatkan tekanan injeksi";i:2;s:44:"Melalui proses pelarutan batuan secara total";i:3;s:32:"Dengan menurunkan suhu reservoir";}','','Melalui interaksi kimia dengan komponen minyak pada permukaan batuan','Why can alkali help change the wettability of the rock?','a:4:{i:0;s:68:"Through chemical interaction with oil components on the rock surface";i:1;s:32:"By increasing injection pressure";i:2;s:38:"Through total rock dissolution process";i:3;s:33:"By lowering reservoir temperature";}','Through chemical interaction with oil components on the rock surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000288','Apa dampak negatif jika konsentrasi alkali terlalu tinggi dalam proses flooding?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:49:"Potensi pengendapan mineral dan kerusakan formasi";i:1;s:39:"Peningkatan drastis tegangan antar muka";i:2;s:41:"Surfaktan tidak dapat bekerja sama sekali";i:3;s:48:"Polimer kehilangan viskositasnya secara permanen";}','','Potensi pengendapan mineral dan kerusakan formasi','What is the negative impact if the alkaline concentration is too high in the flooding process?','a:4:{i:0;s:56:"Potential for mineral precipitation and formation damage";i:1;s:39:"Drastic increase in interfacial tension";i:2;s:33:"Surfactant cannot function at all";i:3;s:39:"Polymer permanently loses its viscosity";}','Potential for mineral precipitation and formation damage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000289','Sebutkan parameter yang mempengaruhi efektivitas reaksi saponifikasi in-situ','multi','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:41:"Kandungan asam dalam minyak (Acid Number)";i:1;s:38:"Ketersediaan ion kalsium dan magnesium";i:2;s:18:"pH larutan injeksi";i:3;s:16:"Porositas batuan";}','','a:3:{i:0;s:41:"Kandungan asam dalam minyak (Acid Number)";i:1;s:38:"Ketersediaan ion kalsium dan magnesium";i:2;s:18:"pH larutan injeksi";}','Mention the parameters that affect the effectiveness of in-situ saponification reactions','a:4:{i:0;s:33:"Acid content in oil (Acid Number)";i:1;s:42:"Availability of calcium and magnesium ions";i:2;s:21:"Injection solution pH";i:3;s:13:"Rock porosity";}','a:3:{i:0;s:33:"Acid content in oil (Acid Number)";i:1;s:42:"Availability of calcium and magnesium ions";i:2;s:21:"Injection solution pH";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000290','Apa fungsi utama penambahan alkaline dalam proses ASP flooding pada studi kasus lapangan mature?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:44:"Menurunkan tegangan antarmuka secara drastis";i:1;s:41:"Mengurangi adsorpsi surfaktan pada batuan";i:2;s:35:"Meningkatkan viskositas air injeksi";i:3;s:38:"Memperbesar porositas batuan reservoir";}','','Mengurangi adsorpsi surfaktan pada batuan','What is the primary function of adding alkaline in the ASP flooding process for mature field case studies?','a:4:{i:0;s:38:"Drastically reduce interfacial tension";i:1;s:40:"Reduce surfactant adsorption on the rock";i:2;s:34:"Increase injection water viscosity";i:3;s:32:"Increase reservoir rock porosity";}','Reduce surfactant adsorption on the rock','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000291','Faktor apa saja yang menjadi tantangan utama implementasi Chemical EOR di lapangan dengan salinitas tinggi?','multi','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:17:"Presipitasi kimia";i:1;s:26:"Degradasi termal surfaktan";i:2;s:33:"Peningkatan permeabilitas absolut";i:3;s:29:"Ketidakstabilan fase campuran";}','','a:2:{i:0;s:17:"Presipitasi kimia";i:1;s:29:"Ketidakstabilan fase campuran";}','What are the main challenges in implementing Chemical EOR in high salinity fields?','a:4:{i:0;s:22:"Chemical precipitation";i:1;s:30:"Thermal surfactant degradation";i:2;s:30:"Absolute permeability increase";i:3;s:17:"Phase instability";}','a:2:{i:0;s:22:"Chemical precipitation";i:1;s:17:"Phase instability";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000292','Dalam pertimbangan ekonomi CEOR, apa dampak kenaikan harga minyak dunia terhadap Net Present Value (NPV) proyek?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:44:"Menurunkan NPV karena biaya operasional naik";i:1;s:37:"Tidak berpengaruh pada ekonomi proyek";i:2;s:63:"Meningkatkan NPV karena margin keuntungan per barel lebih besar";i:3;s:53:"Meningkatkan biaya investasi awal secara proporsional";}','','Meningkatkan NPV karena margin keuntungan per barel lebih besar','In CEOR economic considerations, what is the impact of rising global oil prices on the project''s Net Present Value (NPV)?','a:4:{i:0;s:45:"Decreases NPV due to rising operational costs";i:1;s:34:"Has no effect on project economics";i:2;s:52:"Increases NPV due to higher profit margin per barrel";i:3;s:49:"Increases initial investment costs proportionally";}','Increases NPV due to higher profit margin per barrel','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000293','Mengapa adsorpsi surfaktan pada mineral lempung merupakan tantangan kritis dalam desain injeksi kimia?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:54:"Karena dapat menyebabkan penyumbatan pori secara fisik";i:1;s:71:"Karena akan menghilangkan surfaktan dari fase fluida dan menambah biaya";i:2;s:44:"Karena meningkatkan viskositas larutan kimia";i:3;s:46:"Karena mempercepat laju korosi peralatan sumur";}','','Karena akan menghilangkan surfaktan dari fase fluida dan menambah biaya','Why is surfactant adsorption on clay minerals a critical challenge in chemical injection design?','a:4:{i:0;s:43:"Because it can cause physical pore plugging";i:1;s:70:"Because it removes surfactant from the fluid phase and increases costs";i:2;s:48:"Because it increases chemical solution viscosity";i:3;s:53:"Because it accelerates well equipment corrosion rates";}','Because it removes surfactant from the fluid phase and increases costs','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000294','Manakah dari berikut ini yang merupakan indikator keberhasilan teknis dalam proyek surfaktan flooding?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:40:"Penurunan saturasi minyak residual (Sor)";i:1;s:36:"Peningkatan viskositas minyak mentah";i:2;s:30:"Penurunan densitas air injeksi";i:3;s:49:"Peningkatan tekanan injeksi di atas tekanan rekah";}','','Penurunan saturasi minyak residual (Sor)','Which of the following is a technical success indicator in a surfactant flooding project?','a:4:{i:0;s:42:"Reduction in residual oil saturation (Sor)";i:1;s:31:"Increase in crude oil viscosity";i:2;s:35:"Decrease in injection water density";i:3;s:56:"Increase in injection pressure above fracturing pressure";}','Reduction in residual oil saturation (Sor)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000295','Bagaimana pengaruh heterogenitas reservoir terhadap efisiensi perolehan minyak pada aplikasi CEOR?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:48:"Meningkatkan efisiensi sapuan (sweep efficiency)";i:1;s:56:"Menyebabkan channeling yang mengurangi efektivitas kimia";i:2;s:32:"Tidak memiliki dampak signifikan";i:3;s:39:"Membantu distribusi kimia secara merata";}','','Menyebabkan channeling yang mengurangi efektivitas kimia','How does reservoir heterogeneity affect oil recovery efficiency in CEOR applications?','a:4:{i:0;s:26:"Increases sweep efficiency";i:1;s:53:"Causes channeling that reduces chemical effectiveness";i:2;s:25:"Has no significant impact";i:3;s:33:"Helps distribute chemicals evenly";}','Causes channeling that reduces chemical effectiveness','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000296','Pada studi kasus ASP, apa yang terjadi jika konsentrasi alkaline terlalu tinggi?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:37:"Terjadi perbaikan efisiensi penyapuan";i:1;s:53:"Terjadi pembentukan kerak (scale) yang menyumbat pori";i:2;s:29:"Surfaktan menjadi lebih aktif";i:3;s:43:"Adsorpsi surfaktan justru meningkat drastis";}','','Terjadi pembentukan kerak (scale) yang menyumbat pori','In ASP case studies, what happens if the alkaline concentration is too high?','a:4:{i:0;s:32:"Improved sweep efficiency occurs";i:1;s:39:"Scale formation occurs that plugs pores";i:2;s:30:"Surfactant becomes more active";i:3;s:43:"Surfactant adsorption increases drastically";}','Scale formation occurs that plugs pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000297','Apa tujuan utama penambahan polimer dalam formulasi ASP (Alkaline-Surfactant-Polymer)?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:29:"Mengurangi tegangan antarmuka";i:1;s:35:"Mengontrol mobilitas fluida injeksi";i:2;s:31:"Mengurangi nilai pH air formasi";i:3;s:32:"Meningkatkan kelarutan surfaktan";}','','Mengontrol mobilitas fluida injeksi','What is the main purpose of adding polymer in an ASP (Alkaline-Surfactant-Polymer) formulation?','a:4:{i:0;s:26:"Reduce interfacial tension";i:1;s:32:"Control injection fluid mobility";i:2;s:25:"Reduce formation water pH";i:3;s:30:"Increase surfactant solubility";}','Control injection fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000298','Apa parameter ekonomi yang paling sensitif terhadap ketidakpastian volume perolehan minyak (incremental oil) pada proyek CEOR?','multi','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:16:"Pajak perusahaan";i:2;s:23:"Net Present Value (NPV)";i:3;s:24:"Biaya pemeliharaan rutin";}','','a:2:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:23:"Net Present Value (NPV)";}','Which economic parameters are most sensitive to the uncertainty of incremental oil volume in CEOR projects?','a:4:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:13:"Corporate tax";i:2;s:23:"Net Present Value (NPV)";i:3;s:25:"Routine maintenance costs";}','a:2:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:23:"Net Present Value (NPV)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000299','Mengapa pemilihan jenis surfaktan harus disesuaikan dengan suhu reservoir?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:58:"Suhu mempengaruhi stabilitas kimia dan aktivitas surfaktan";i:1;s:37:"Suhu mengubah nilai porositas absolut";i:2;s:33:"Suhu menentukan harga jual minyak";i:3;s:55:"Suhu tidak memiliki kaitan dengan efektivitas surfaktan";}','','Suhu mempengaruhi stabilitas kimia dan aktivitas surfaktan','Why must the type of surfactant be matched to the reservoir temperature?','a:4:{i:0;s:62:"Temperature affects chemical stability and surfactant activity";i:1;s:44:"Temperature changes absolute porosity values";i:2;s:40:"Temperature determines oil selling price";i:3;s:55:"Temperature has no relation to surfactant effectiveness";}','Temperature affects chemical stability and surfactant activity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000300','Apa mekanisme utama dalam metode thermal recovery yang menyebabkan peningkatan mobilitas minyak berat di dalam reservoir?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:54:"Penurunan viskositas minyak akibat kenaikan temperatur";i:1;s:27:"Peningkatan tekanan kapiler";i:2;s:28:"Perubahan wettability batuan";i:3;s:30:"Injeksi gas CO2 untuk swelling";}','','Penurunan viskositas minyak akibat kenaikan temperatur','What is the primary mechanism in thermal recovery methods that causes an increase in heavy oil mobility within the reservoir?','a:4:{i:0;s:51:"Oil viscosity reduction due to temperature increase";i:1;s:27:"Capillary pressure increase";i:2;s:27:"Rock wettability alteration";i:3;s:30:"CO2 gas injection for swelling";}','Oil viscosity reduction due to temperature increase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000301','Metode Cyclic Steam Stimulation (CSS) umumnya melibatkan tahapan berulang, yaitu:','multi','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:23:"Injeksi uap (injection)";i:1;s:22:"Masa perendaman (soak)";i:2;s:21:"Produksi (production)";i:3;s:17:"Injeksi surfaktan";}','','a:3:{i:0;s:23:"Injeksi uap (injection)";i:1;s:22:"Masa perendaman (soak)";i:2;s:21:"Produksi (production)";}','The Cyclic Steam Stimulation (CSS) method generally involves repeated stages, namely:','a:4:{i:0;s:15:"Steam injection";i:1;s:14:"Soaking period";i:2;s:10:"Production";i:3;s:20:"Surfactant injection";}','a:3:{i:0;s:15:"Steam injection";i:1;s:14:"Soaking period";i:2;s:10:"Production";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000302','Pada metode Steam Assisted Gravity Drainage (SAGD), bagaimana posisi sumur injeksi dan sumur produksi?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:36:"Sumur injeksi di atas sumur produksi";i:1;s:37:"Sumur injeksi di bawah sumur produksi";i:2;s:37:"Sumur injeksi sejajar secara vertikal";i:3;s:54:"Sumur injeksi dan produksi berada pada sumur yang sama";}','','Sumur injeksi di atas sumur produksi','In the Steam Assisted Gravity Drainage (SAGD) method, what is the position of the injection well and production well?','a:4:{i:0;s:36:"Injection well above production well";i:1;s:36:"Injection well below production well";i:2;s:34:"Injection well parallel vertically";i:3;s:55:"Injection and production wells are in the same wellbore";}','Injection well above production well','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000303','Parameter utama yang paling signifikan dalam keberhasilan metode steamflood adalah:','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:28:"Kualitas uap (steam quality)";i:1;s:19:"Tekanan hidrostatik";i:2;s:16:"Porositas batuan";i:3;s:29:"Kecepatan alir fluida injeksi";}','','Kualitas uap (steam quality)','What is the most significant parameter for the success of the steamflood method?','a:4:{i:0;s:13:"Steam quality";i:1;s:20:"Hydrostatic pressure";i:2;s:13:"Rock porosity";i:3;s:29:"Injection fluid flow velocity";}','Steam quality','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000304','Apa keunggulan utama dari SAGD dibandingkan dengan Cyclic Steam Stimulation (CSS)?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:44:"Laju produksi yang lebih konstan dan kontinu";i:1;s:39:"Biaya operasional yang jauh lebih murah";i:2;s:33:"Tidak memerlukan sumur horisontal";i:3;s:43:"Dapat diterapkan pada semua jenis reservoir";}','','Laju produksi yang lebih konstan dan kontinu','What is the main advantage of SAGD compared to Cyclic Steam Stimulation (CSS)?','a:4:{i:0;s:44:"More constant and continuous production rate";i:1;s:37:"Significantly lower operational costs";i:2;s:33:"Does not require horizontal wells";i:3;s:41:"Can be applied to all types of reservoirs";}','More constant and continuous production rate','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000305','Faktor apa yang membatasi kedalaman reservoir untuk penerapan thermal recovery?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:44:"Heat loss (kehilangan panas) di dalam tubing";i:1;s:16:"Ketersediaan air";i:2;s:22:"Tingginya saturasi gas";i:3;s:34:"Tekanan formasi yang sangat rendah";}','','Heat loss (kehilangan panas) di dalam tubing','What factor limits the reservoir depth for the application of thermal recovery?','a:4:{i:0;s:23:"Heat loss in the tubing";i:1;s:18:"Water availability";i:2;s:19:"High gas saturation";i:3;s:27:"Very low formation pressure";}','Heat loss in the tubing','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000306','Mengapa viskositas minyak berat sangat sensitif terhadap perubahan suhu?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:60:"Karena struktur molekul minyak berat yang kompleks dan besar";i:1;s:39:"Karena adanya kandungan air yang tinggi";i:2;s:31:"Karena pengaruh tekanan formasi";i:3;s:26:"Karena adanya gas terlarut";}','','Karena struktur molekul minyak berat yang kompleks dan besar','Why is heavy oil viscosity highly sensitive to temperature changes?','a:4:{i:0;s:62:"Because of the complex and large heavy oil molecular structure";i:1;s:29:"Because of high water content";i:2;s:39:"Because of formation pressure influence";i:3;s:24:"Because of dissolved gas";}','Because of the complex and large heavy oil molecular structure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000307','Dalam metode steamflood, zona apa yang terbentuk di sekitar sumur injeksi akibat perpindahan panas?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:21:"Steam zone (zona uap)";i:1;s:21:"Water bank (zona air)";i:2;s:22:"Oil bank (zona minyak)";i:3;s:7:"Gas cap";}','','Steam zone (zona uap)','In the steamflood method, what zone is formed around the injection well due to heat transfer?','a:4:{i:0;s:10:"Steam zone";i:1;s:10:"Water bank";i:2;s:8:"Oil bank";i:3;s:7:"Gas cap";}','Steam zone','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000308','Pilih dua kondisi reservoir yang mendukung penerapan SAGD:','multi','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:34:"Ketebalan formasi yang cukup besar";i:1;s:20:"Permeabilitas tinggi";i:2;s:13:"Porositas nol";i:3;s:34:"Tekanan formasi yang sangat tinggi";}','','a:2:{i:0;s:34:"Ketebalan formasi yang cukup besar";i:1;s:20:"Permeabilitas tinggi";}','Select two reservoir conditions that support the application of SAGD:','a:4:{i:0;s:31:"Significant formation thickness";i:1;s:17:"High permeability";i:2;s:13:"Zero porosity";i:3;s:28:"Very high formation pressure";}','a:2:{i:0;s:31:"Significant formation thickness";i:1;s:17:"High permeability";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000309','Istilah untuk periode di mana sumur ditutup setelah injeksi uap pada CSS agar panas berdifusi ke formasi adalah:','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:11:"Soak period";i:1;s:16:"Injection period";i:2;s:17:"Production period";i:3;s:18:"Steam breakthrough";}','','Soak period','The term for the period when the well is shut in after steam injection in CSS to allow heat to diffuse into the formation is:','a:4:{i:0;s:11:"Soak period";i:1;s:16:"Injection period";i:2;s:17:"Production period";i:3;s:18:"Steam breakthrough";}','Soak period','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000310','Mekanisme utama yang menyebabkan tercapainya kondisi miscible pada injeksi CO2 adalah?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:55:"Ekstraksi komponen hidrokarbon ringan ke dalam fase CO2";i:1;s:44:"Peningkatan viskositas minyak secara drastis";i:2;s:37:"Penurunan saturasi air secara mekanis";i:3;s:52:"Peningkatan tegangan antarmuka antara gas dan minyak";}','','Ekstraksi komponen hidrokarbon ringan ke dalam fase CO2','The primary mechanism that leads to achieving miscible conditions in CO2 injection is?','a:4:{i:0;s:61:"Extraction of light hydrocarbon components into the CO2 phase";i:1;s:33:"Drastic increase in oil viscosity";i:2;s:40:"Mechanical reduction of water saturation";i:3;s:51:"Increase in interfacial tension between gas and oil";}','Extraction of light hydrocarbon components into the CO2 phase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000311','Faktor-faktor yang mempengaruhi tekanan minimum miscibility (MMP) adalah?','multi','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:20:"Temperatur reservoir";i:1;s:26:"Komposisi minyak reservoir";i:2;s:14:"Viskositas air";i:3;s:20:"Permeabilitas batuan";}','','a:2:{i:0;s:20:"Temperatur reservoir";i:1;s:26:"Komposisi minyak reservoir";}','Which factors influence the Minimum Miscibility Pressure (MMP)?','a:4:{i:0;s:21:"Reservoir temperature";i:1;s:25:"Reservoir oil composition";i:2;s:15:"Water viscosity";i:3;s:17:"Rock permeability";}','a:2:{i:0;s:21:"Reservoir temperature";i:1;s:25:"Reservoir oil composition";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000312','Pada injeksi gas hidrokarbon, mekanisme ''vaporizing gas drive'' terjadi ketika?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:68:"Gas kaya (rich gas) menginjeksikan komponen menengah ke dalam minyak";i:1;s:62:"Gas kering (lean gas) menguapkan komponen menengah dari minyak";i:2;s:41:"Suhu reservoir berada di bawah titik beku";i:3;s:42:"Tekanan injeksi jauh di bawah bubble point";}','','Gas kering (lean gas) menguapkan komponen menengah dari minyak','In hydrocarbon gas injection, the ''vaporizing gas drive'' mechanism occurs when?','a:4:{i:0;s:53:"Rich gas injects intermediate components into the oil";i:1;s:55:"Lean gas vaporizes intermediate components from the oil";i:2;s:45:"Reservoir temperature is below freezing point";i:3;s:44:"Injection pressure is far below bubble point";}','Lean gas vaporizes intermediate components from the oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000313','Apa dampak utama dari injeksi gas secara immiscible ke dalam reservoir minyak?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:53:"Pendorongan minyak melalui ekspansi gas dan gravitasi";i:1;s:37:"Penyatuan total antara gas dan minyak";i:2;s:45:"Penghilangan tegangan antarmuka secara instan";i:3;s:42:"Peningkatan saturasi air secara signifikan";}','','Pendorongan minyak melalui ekspansi gas dan gravitasi','What is the primary impact of immiscible gas injection into an oil reservoir?','a:4:{i:0;s:59:"Oil displacement through gas expansion and gravity drainage";i:1;s:34:"Total blending between gas and oil";i:2;s:48:"Instantaneous elimination of interfacial tension";i:3;s:40:"Significant increase in water saturation";}','Oil displacement through gas expansion and gravity drainage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000314','Apa yang dimaksud dengan ''Multiple Contact Miscibility'' pada proses CO2 flooding?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:75:"Miscibility yang dicapai melalui kontak berulang antara fase gas dan minyak";i:1;s:53:"Miscibility yang terjadi seketika pada kontak pertama";i:2;s:52:"Pencampuran yang hanya terjadi di zona sumur injeksi";i:3;s:39:"Hilangnya miscibility akibat adanya air";}','','Miscibility yang dicapai melalui kontak berulang antara fase gas dan minyak','What is meant by ''Multiple Contact Miscibility'' in the CO2 flooding process?','a:4:{i:0;s:72:"Miscibility achieved through repeated contact between gas and oil phases";i:1;s:56:"Miscibility that occurs instantaneously on first contact";i:2;s:50:"Mixing that only occurs in the injection well zone";i:3;s:48:"Loss of miscibility due to the presence of water";}','Miscibility achieved through repeated contact between gas and oil phases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000315','Manakah pernyataan yang benar mengenai injeksi gas hidrokarbon kaya (enriched gas)?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:58:"Mengandung komponen intermediate (C2-C6) yang cukup tinggi";i:1;s:35:"Hanya terdiri dari gas metana murni";i:2;s:35:"Selalu tidak miscible dengan minyak";i:3;s:43:"Tidak terpengaruh oleh temperatur reservoir";}','','Mengandung komponen intermediate (C2-C6) yang cukup tinggi','Which statement is correct regarding enriched hydrocarbon gas injection?','a:4:{i:0;s:55:"Contains high levels of intermediate components (C2-C6)";i:1;s:33:"Consists only of pure methane gas";i:2;s:29:"Is always immiscible with oil";i:3;s:40:"Is not affected by reservoir temperature";}','Contains high levels of intermediate components (C2-C6)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000316','Dalam konteks CO2 flooding, apa fungsi utama dari sifat ''swelling'' minyak?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:55:"Meningkatkan volume minyak dan menurunkan viskositasnya";i:1;s:37:"Memperbesar tegangan permukaan minyak";i:2;s:38:"Mengurangi mobilitas gas di dalam pori";i:3;s:37:"Mempercepat pembentukan scale di pipa";}','','Meningkatkan volume minyak dan menurunkan viskositasnya','In the context of CO2 flooding, what is the primary function of the oil ''swelling'' property?','a:4:{i:0;s:46:"Increases oil volume and reduces its viscosity";i:1;s:29:"Increases oil surface tension";i:2;s:33:"Reduces gas mobility within pores";i:3;s:36:"Accelerates scale formation in pipes";}','Increases oil volume and reduces its viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000317','Mengapa injeksi CO2 immiscible masih bisa meningkatkan perolehan minyak?','multi','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:29:"Pengurangan viskositas minyak";i:1;s:41:"Pengembangan volume minyak (oil swelling)";i:2;s:49:"Peningkatan permeabilitas absolut secara permanen";i:3;s:41:"Pembentukan emulsi air-minyak yang stabil";}','','a:2:{i:0;s:29:"Pengurangan viskositas minyak";i:1;s:41:"Pengembangan volume minyak (oil swelling)";}','Why can immiscible CO2 injection still increase oil recovery?','a:4:{i:0;s:26:"Reduction of oil viscosity";i:1;s:35:"Oil volume expansion (oil swelling)";i:2;s:43:"Permanent increase in absolute permeability";i:3;s:39:"Formation of stable water-oil emulsions";}','a:2:{i:0;s:26:"Reduction of oil viscosity";i:1;s:35:"Oil volume expansion (oil swelling)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000318','Apa kelemahan utama dari injeksi gas (termasuk CO2) dalam hal efisiensi penyapuan?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:53:"Mobility ratio yang buruk (gas mudah menyalip minyak)";i:1;s:45:"Gas terlalu berat untuk bergerak di reservoir";i:2;s:46:"Terlalu banyak bereaksi dengan batuan karbonat";i:3;s:48:"Mengakibatkan korosi pada seluruh formasi batuan";}','','Mobility ratio yang buruk (gas mudah menyalip minyak)','What is the main drawback of gas injection (including CO2) in terms of sweep efficiency?','a:4:{i:0;s:45:"Poor mobility ratio (gas easily bypasses oil)";i:1;s:41:"Gas is too heavy to move in the reservoir";i:2;s:36:"Reacts too much with carbonate rocks";i:3;s:45:"Causes corrosion in the entire rock formation";}','Poor mobility ratio (gas easily bypasses oil)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000319','Proses miscibility di mana gas menyerap komponen hidrokarbon ke dalam fase gas disebut?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:16:"Vaporizing drive";i:1;s:16:"Condensing drive";i:2;s:16:"Gravity drainage";i:3;s:21:"Water-alternating-gas";}','','Vaporizing drive','The miscibility process where gas absorbs hydrocarbon components into the gas phase is called?','a:4:{i:0;s:16:"Vaporizing drive";i:1;s:16:"Condensing drive";i:2;s:16:"Gravity drainage";i:3;s:21:"Water-alternating-gas";}','Vaporizing drive','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000320','Metode Thermal EOR manakah yang paling efektif untuk reservoir minyak berat dengan viskositas tinggi guna menurunkan viskositas secara drastis melalui pemanasan?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:14:"Steam flooding";i:1;s:21:"CO2 miscible flooding";i:2;s:16:"Polymer flooding";i:3;s:19:"Surfactant flooding";}','','Steam flooding','Which Thermal EOR method is most effective for heavy oil reservoirs with high viscosity to drastically reduce viscosity through heating?','a:4:{i:0;s:14:"Steam flooding";i:1;s:21:"CO2 miscible flooding";i:2;s:16:"Polymer flooding";i:3;s:19:"Surfactant flooding";}','Steam flooding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000321','Pilihlah karakteristik reservoir yang umumnya menjadi syarat utama untuk implementasi Gas Miscible Flooding (CO2).','multi','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:47:"Kedalaman reservoir yang cukup (tekanan tinggi)";i:1;s:39:"Minyak ringan dengan API gravity tinggi";i:2;s:29:"Permeabilitas rendah (< 1 mD)";i:3;s:58:"Temperatur reservoir sangat tinggi (> 200 derajat Celsius)";}','','a:2:{i:0;s:47:"Kedalaman reservoir yang cukup (tekanan tinggi)";i:1;s:39:"Minyak ringan dengan API gravity tinggi";}','Select the reservoir characteristics that are generally the main requirements for the implementation of Gas Miscible Flooding (CO2).','a:4:{i:0;s:42:"Sufficient reservoir depth (high pressure)";i:1;s:31:"Light oil with high API gravity";i:2;s:25:"Low permeability (< 1 mD)";i:3;s:55:"Very high reservoir temperature (> 200 degrees Celsius)";}','a:2:{i:0;s:42:"Sufficient reservoir depth (high pressure)";i:1;s:31:"Light oil with high API gravity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000322','Apa dampak utama dari injeksi uap (steam injection) terhadap sifat fisik fluida di dalam reservoir?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:37:"Meningkatkan tegangan antarmuka (IFT)";i:1;s:28:"Menurunkan viskositas minyak";i:2;s:37:"Meningkatkan saturasi air irreducible";i:3;s:36:"Mengubah wettability menjadi oil-wet";}','','Menurunkan viskositas minyak','What is the primary impact of steam injection on the physical properties of fluids within the reservoir?','a:4:{i:0;s:35:"Increases interfacial tension (IFT)";i:1;s:23:"Decreases oil viscosity";i:2;s:38:"Increases irreducible water saturation";i:3;s:30:"Changes wettability to oil-wet";}','Decreases oil viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000323','Metode EOR mana yang lebih disukai jika reservoir memiliki heterogenitas tinggi dan membutuhkan kontrol mobilitas?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:14:"Steam flooding";i:1;s:16:"Polymer flooding";i:2;s:18:"In-situ combustion";i:3;s:22:"Miscible gas injection";}','','Polymer flooding','Which EOR method is preferred if the reservoir has high heterogeneity and requires mobility control?','a:4:{i:0;s:14:"Steam flooding";i:1;s:16:"Polymer flooding";i:2;s:18:"In-situ combustion";i:3;s:22:"Miscible gas injection";}','Polymer flooding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000324','Pada kondisi reservoir apa metode In-Situ Combustion (ISC) sering dianggap sebagai alternatif thermal EOR yang potensial?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:36:"Reservoir dalam dengan minyak ringan";i:1;s:37:"Reservoir dangkal dengan minyak berat";i:2;s:44:"Reservoir dengan permeabilitas sangat rendah";i:3;s:43:"Reservoir dengan saturasi air sangat tinggi";}','','Reservoir dangkal dengan minyak berat','Under what reservoir conditions is In-Situ Combustion (ISC) often considered as a potential thermal EOR alternative?','a:4:{i:0;s:30:"Deep reservoirs with light oil";i:1;s:33:"Shallow reservoirs with heavy oil";i:2;s:37:"Reservoirs with very low permeability";i:3;s:42:"Reservoirs with very high water saturation";}','Shallow reservoirs with heavy oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000325','Faktor utama yang membatasi efisiensi dari Gas Miscible Flooding adalah:','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:38:"Gravity override (segregasi gravitasi)";i:1;s:22:"Ketersediaan air tawar";i:2;s:30:"Tingginya konsumsi bahan kimia";i:3;s:35:"Sensitivitas formasi terhadap panas";}','','Gravity override (segregasi gravitasi)','The main factor limiting the efficiency of Gas Miscible Flooding is:','a:4:{i:0;s:16:"Gravity override";i:1;s:24:"Fresh water availability";i:2;s:25:"High chemical consumption";i:3;s:29:"Formation sensitivity to heat";}','Gravity override','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000326','Manakah dari berikut ini yang merupakan keuntungan menggunakan Gas EOR dibandingkan Thermal EOR?','multi','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:48:"Dapat diterapkan pada reservoir yang lebih dalam";i:1;s:43:"Tidak memerlukan panas tinggi untuk operasi";i:2;s:41:"Dapat menurunkan IFT hingga mendekati nol";i:3;s:60:"Lebih efektif untuk minyak dengan viskositas di atas 1000 cP";}','','a:3:{i:0;s:48:"Dapat diterapkan pada reservoir yang lebih dalam";i:1;s:43:"Tidak memerlukan panas tinggi untuk operasi";i:2;s:41:"Dapat menurunkan IFT hingga mendekati nol";}','Which of the following are advantages of using Gas EOR compared to Thermal EOR?','a:4:{i:0;s:35:"Can be applied in deeper reservoirs";i:1;s:41:"Does not require high heat for operations";i:2;s:27:"Can reduce IFT to near zero";i:3;s:51:"More effective for oil with viscosity above 1000 cP";}','a:3:{i:0;s:35:"Can be applied in deeper reservoirs";i:1;s:41:"Does not require high heat for operations";i:2;s:27:"Can reduce IFT to near zero";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000327','Apa peran utama surfaktan dalam Chemical EOR untuk meningkatkan recovery factor?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:35:"Meningkatkan viskositas air injeksi";i:1;s:46:"Menurunkan tegangan antarmuka (IFT) minyak-air";i:2;s:26:"Menambah tekanan reservoir";i:3;s:27:"Meningkatkan suhu reservoir";}','','Menurunkan tegangan antarmuka (IFT) minyak-air','What is the main role of surfactants in Chemical EOR to improve recovery factor?','a:4:{i:0;s:36:"Increasing injection water viscosity";i:1;s:44:"Reducing oil-water interfacial tension (IFT)";i:2;s:29:"Increasing reservoir pressure";i:3;s:32:"Increasing reservoir temperature";}','Reducing oil-water interfacial tension (IFT)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000328','Metode thermal mana yang melibatkan pembakaran sebagian minyak di dalam reservoir?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:38:"Steam Assisted Gravity Drainage (SAGD)";i:1;s:24:"Cyclic Steam Stimulation";i:2;s:18:"In-situ combustion";i:3;s:18:"Hot water flooding";}','','In-situ combustion','Which thermal method involves burning a portion of the oil inside the reservoir?','a:4:{i:0;s:38:"Steam Assisted Gravity Drainage (SAGD)";i:1;s:24:"Cyclic Steam Stimulation";i:2;s:18:"In-situ combustion";i:3;s:18:"Hot water flooding";}','In-situ combustion','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000329','Pemilihan metode EOR harus mempertimbangkan aspek teknis dan ekonomi. Faktor ekonomi utama dalam proyek Gas EOR adalah:','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:55:"Biaya penyediaan gas injeksi dan infrastruktur kompresi";i:1;s:31:"Biaya pemanasan air untuk steam";i:2;s:45:"Harga polimer sintetis di pasar internasional";i:3;s:28:"Pajak emisi karbon per barel";}','','Biaya penyediaan gas injeksi dan infrastruktur kompresi','EOR method selection must consider technical and economic aspects. The main economic factor in Gas EOR projects is:','a:4:{i:0;s:63:"Cost of supply for injection gas and compression infrastructure";i:1;s:31:"Cost of heating water for steam";i:2;s:55:"Price of synthetic polymers in the international market";i:3;s:30:"Carbon emission tax per barrel";}','Cost of supply for injection gas and compression infrastructure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000330','Data reservoir apa yang paling krusial untuk menentukan kesesuaian lapangan terhadap metode Chemical EOR (CEOR)?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:46:"Temperatur reservoir dan salinitas air formasi";i:1;s:22:"Warna batuan reservoir";i:2;s:26:"Jumlah sumur injeksi aktif";i:3;s:25:"Lokasi geografis lapangan";}','','Temperatur reservoir dan salinitas air formasi','Which reservoir data is most crucial for determining the suitability of a field for Chemical EOR (CEOR) methods?','a:4:{i:0;s:50:"Reservoir temperature and formation water salinity";i:1;s:20:"Reservoir rock color";i:2;s:32:"Number of active injection wells";i:3;s:34:"Geographical location of the field";}','Reservoir temperature and formation water salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000331','Manakah dari berikut ini yang merupakan tujuan utama dari kajian laboratorium (core flooding) dalam proyek CEOR?','multi','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:38:"Menentukan efisiensi pendesakan minyak";i:1;s:43:"Menentukan adsorpsi bahan kimia pada batuan";i:2;s:43:"Mengukur tekanan kapiler di permukaan tanah";i:3;s:30:"Memprediksi harga minyak dunia";}','','a:2:{i:0;s:38:"Menentukan efisiensi pendesakan minyak";i:1;s:43:"Menentukan adsorpsi bahan kimia pada batuan";}','Which of the following are the primary objectives of laboratory (core flooding) studies in a CEOR project?','a:4:{i:0;s:39:"Determining oil displacement efficiency";i:1;s:39:"Determining chemical adsorption on rock";i:2;s:36:"Measuring surface capillary pressure";i:3;s:28:"Predicting global oil prices";}','a:2:{i:0;s:39:"Determining oil displacement efficiency";i:1;s:39:"Determining chemical adsorption on rock";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000332','Apa fungsi utama dari pemodelan simulasi reservoir sebelum implementasi proyek CEOR skala penuh?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:56:"Memprediksi kinerja injeksi dan memitigasi risiko teknis";i:1;s:50:"Menggantikan kebutuhan akan pengujian laboratorium";i:2;s:44:"Menentukan lokasi pengeboran eksplorasi baru";i:3;s:44:"Menghitung biaya pembersihan lingkungan saja";}','','Memprediksi kinerja injeksi dan memitigasi risiko teknis','What is the primary function of reservoir simulation modeling before full-scale CEOR project implementation?','a:4:{i:0;s:63:"Predicting injection performance and mitigating technical risks";i:1;s:41:"Replacing the need for laboratory testing";i:2;s:50:"Determining locations for new exploration drilling";i:3;s:44:"Calculating environmental cleanup costs only";}','Predicting injection performance and mitigating technical risks','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000333','Apa tujuan utama dari pelaksanaan proyek percontohan (pilot project) sebelum skala penuh?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:59:"Validasi efektivitas metode di skala lapangan yang terbatas";i:1;s:35:"Meningkatkan harga saham perusahaan";i:2;s:39:"Mengurangi pajak produksi secara instan";i:3;s:41:"Menguji peralatan pengeboran konvensional";}','','Validasi efektivitas metode di skala lapangan yang terbatas','What is the primary objective of implementing a pilot project before full-scale deployment?','a:4:{i:0;s:56:"Validating method effectiveness at a limited field scale";i:1;s:31:"Increasing company stock prices";i:2;s:35:"Reducing production taxes instantly";i:3;s:39:"Testing conventional drilling equipment";}','Validating method effectiveness at a limited field scale','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000334','Parameter laboratorium apa yang diukur untuk mengevaluasi kemampuan bahan kimia dalam menurunkan Interfacial Tension (IFT)?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:25:"Spinning drop tensiometer";i:1;s:15:"Porosimeter gas";i:2;s:17:"Permeameter udara";i:3;s:23:"Viskosimeter Brookfield";}','','Spinning drop tensiometer','What laboratory parameter is measured to evaluate the ability of chemicals to reduce Interfacial Tension (IFT)?','a:4:{i:0;s:25:"Spinning drop tensiometer";i:1;s:15:"Gas porosimeter";i:2;s:15:"Air permeameter";i:3;s:21:"Brookfield viscometer";}','Spinning drop tensiometer','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000335','Dalam perencanaan CEOR, mengapa pemahaman mengenai heterogenitas reservoir sangat penting?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:58:"Mempengaruhi pola penyapuan (sweep efficiency) bahan kimia";i:1;s:40:"Tidak berpengaruh terhadap hasil injeksi";i:2;s:45:"Hanya relevan untuk pengeboran sumur vertikal";i:3;s:34:"Hanya relevan untuk metode thermal";}','','Mempengaruhi pola penyapuan (sweep efficiency) bahan kimia','In CEOR planning, why is understanding reservoir heterogeneity very important?','a:4:{i:0;s:44:"It affects the sweep efficiency of chemicals";i:1;s:37:"It has no effect on injection results";i:2;s:46:"It is only relevant for vertical well drilling";i:3;s:39:"It is only relevant for thermal methods";}','It affects the sweep efficiency of chemicals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000336','Faktor apa saja yang harus dipertimbangkan dalam transisi dari pilot ke skala lapangan penuh?','multi','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:47:"Integritas fasilitas surface dan logistik kimia";i:1;s:50:"Ketersediaan volume bahan kimia dalam jumlah besar";i:2;s:63:"Biaya operasional dibandingkan dengan tambahan perolehan minyak";i:3;s:22:"Warna fluida reservoir";}','','a:3:{i:0;s:47:"Integritas fasilitas surface dan logistik kimia";i:1;s:50:"Ketersediaan volume bahan kimia dalam jumlah besar";i:2;s:63:"Biaya operasional dibandingkan dengan tambahan perolehan minyak";}','What factors must be considered in the transition from pilot to full-scale field operations?','a:4:{i:0;s:49:"Surface facility integrity and chemical logistics";i:1;s:38:"Availability of large chemical volumes";i:2;s:52:"Operating costs compared to incremental oil recovery";i:3;s:21:"Reservoir fluid color";}','a:3:{i:0;s:49:"Surface facility integrity and chemical logistics";i:1;s:38:"Availability of large chemical volumes";i:2;s:52:"Operating costs compared to incremental oil recovery";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000337','Apa dampak negatif yang mungkin terjadi jika kompatibilitas kimiawi tidak diuji terhadap air formasi?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:63:"Terjadinya presipitasi (pengendapan) yang menyumbat pori batuan";i:1;s:48:"Meningkatkan permeabilitas batuan secara drastis";i:2;s:34:"Memperbaiki kualitas minyak mentah";i:3;s:41:"Menurunkan viskositas minyak secara alami";}','','Terjadinya presipitasi (pengendapan) yang menyumbat pori batuan','What negative impact might occur if chemical compatibility is not tested against formation water?','a:4:{i:0;s:35:"Precipitation that plugs rock pores";i:1;s:37:"Drastic increase in rock permeability";i:2;s:32:"Improvement of crude oil quality";i:3;s:34:"Natural reduction of oil viscosity";}','Precipitation that plugs rock pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000338','Mengapa simulasi reservoir membutuhkan data tekanan dan laju alir historis lapangan?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:74:"Untuk melakukan history matching agar model merepresentasikan kondisi asli";i:1;s:43:"Untuk menghitung harga jual minyak saat ini";i:2;s:36:"Untuk menentukan lokasi kantor pusat";i:3;s:32:"Untuk menggantikan studi geologi";}','','Untuk melakukan history matching agar model merepresentasikan kondisi asli','Why does reservoir simulation require historical pressure and flow rate data from the field?','a:4:{i:0;s:69:"To perform history matching so the model represents actual conditions";i:1;s:45:"To calculate the current selling price of oil";i:2;s:34:"To determine headquarters location";i:3;s:29:"To replace geological studies";}','To perform history matching so the model represents actual conditions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000339','Manakah instrumen laboratorium yang digunakan untuk menentukan mobilitas fluida dalam media berpori?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:23:"Core flooding apparatus";i:1;s:13:"Refraktometer";i:2;s:13:"Density meter";i:3;s:18:"Mikroskop elektron";}','','Core flooding apparatus','Which laboratory instrument is used to determine fluid mobility in porous media?','a:4:{i:0;s:23:"Core flooding apparatus";i:1;s:13:"Refractometer";i:2;s:13:"Density meter";i:3;s:19:"Electron microscope";}','Core flooding apparatus','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000340','Apa indikator ekonomi utama yang digunakan untuk mengukur nilai tambah bersih suatu proyek EOR dengan mendiskon arus kas masa depan?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";i:2;s:14:"Payback Period";i:3;s:28:"Operating Expenditure (OPEX)";}','','Net Present Value (NPV)','What is the primary economic indicator used to measure the net added value of an EOR project by discounting future cash flows?','a:4:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";i:2;s:14:"Payback Period";i:3;s:28:"Operating Expenditure (OPEX)";}','Net Present Value (NPV)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000341','Manakah dari faktor berikut yang secara langsung meningkatkan keuntungan ekonomi dari proyek EOR?','multi','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:55:"Peningkatan perolehan minyak tambahan (incremental oil)";i:1;s:37:"Penurunan biaya operasional per barel";i:2;s:38:"Peningkatan harga minyak mentah global";i:3;s:34:"Kenaikan biaya injeksi bahan kimia";}','','a:3:{i:0;s:55:"Peningkatan perolehan minyak tambahan (incremental oil)";i:1;s:37:"Penurunan biaya operasional per barel";i:2;s:38:"Peningkatan harga minyak mentah global";}','Which of the following factors directly increase the economic profitability of an EOR project?','a:4:{i:0;s:36:"Increase in incremental oil recovery";i:1;s:37:"Decrease in operating cost per barrel";i:2;s:34:"Increase in global crude oil price";i:3;s:32:"Rise in chemical injection costs";}','a:3:{i:0;s:36:"Increase in incremental oil recovery";i:1;s:37:"Decrease in operating cost per barrel";i:2;s:34:"Increase in global crude oil price";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000342','Dalam analisis ekonomi EOR, apa yang dimaksud dengan incremental oil?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:109:"Tambahan produksi minyak yang diperoleh akibat implementasi metode EOR dibandingkan dengan skenario base case";i:1;s:48:"Total volume minyak di tempat (OOIP) sebelum EOR";i:2;s:47:"Volume air yang terproduksi selama fase injeksi";i:3;s:67:"Total cadangan minyak yang tersisa di reservoir setelah EOR selesai";}','','Tambahan produksi minyak yang diperoleh akibat implementasi metode EOR dibandingkan dengan skenario base case','In EOR economic analysis, what is meant by incremental oil?','a:4:{i:0;s:95:"Additional oil production obtained due to EOR implementation compared to the base case scenario";i:1;s:45:"Total original oil in place (OOIP) before EOR";i:2;s:51:"Volume of water produced during the injection phase";i:3;s:68:"Total oil reserves remaining in the reservoir after EOR is completed";}','Additional oil production obtained due to EOR implementation compared to the base case scenario','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000343','Parameter ekonomi mana yang menunjukkan tingkat pengembalian modal tahunan (annualized rate of return) dari investasi proyek EOR?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:27:"Capital Expenditure (CAPEX)";i:2;s:28:"Operating Expenditure (OPEX)";i:3;s:20:"Break-even Oil Price";}','','Internal Rate of Return (IRR)','Which economic parameter indicates the annualized rate of return on an EOR project investment?','a:4:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:27:"Capital Expenditure (CAPEX)";i:2;s:28:"Operating Expenditure (OPEX)";i:3;s:20:"Break-even Oil Price";}','Internal Rate of Return (IRR)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000344','Dalam analisis risiko proyek EOR, ketidakpastian apa yang paling berpengaruh terhadap volatilitas pendapatan?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:28:"Fluktuasi harga minyak dunia";i:1;s:27:"Viskositas fluida reservoir";i:2;s:23:"Kedalaman sumur injeksi";i:3;s:23:"Jumlah crew di lapangan";}','','Fluktuasi harga minyak dunia','In EOR project risk analysis, which uncertainty has the most significant impact on revenue volatility?','a:4:{i:0;s:28:"World oil price fluctuations";i:1;s:25:"Reservoir fluid viscosity";i:2;s:20:"Injection well depth";i:3;s:20:"Number of field crew";}','World oil price fluctuations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000345','Mengapa analisis sensitivitas penting dilakukan dalam perencanaan proyek EOR?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:80:"Untuk memahami dampak perubahan variabel input terhadap kelayakan ekonomi proyek";i:1;s:53:"Untuk menghitung jumlah cadangan minyak secara akurat";i:2;s:45:"Untuk menentukan lokasi pengeboran sumur baru";i:3;s:49:"Untuk mengukur tekanan reservoir secara real-time";}','','Untuk memahami dampak perubahan variabel input terhadap kelayakan ekonomi proyek','Why is sensitivity analysis important in EOR project planning?','a:4:{i:0;s:90:"To understand the impact of changes in input variables on the project''s economic viability";i:1;s:36:"To calculate oil reserves accurately";i:2;s:35:"To determine new drilling locations";i:3;s:42:"To measure reservoir pressure in real-time";}','To understand the impact of changes in input variables on the project''s economic viability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000346','Biaya yang dikeluarkan untuk pengadaan fasilitas injeksi (seperti pompa, pipa, dan unit pengolahan kimia) dikategorikan sebagai:','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:27:"Capital Expenditure (CAPEX)";i:1;s:28:"Operating Expenditure (OPEX)";i:2;s:35:"General and Administrative Expenses";i:3;s:19:"Incremental Revenue";}','','Capital Expenditure (CAPEX)','Costs incurred for the procurement of injection facilities (such as pumps, pipelines, and chemical processing units) are categorized as:','a:4:{i:0;s:27:"Capital Expenditure (CAPEX)";i:1;s:28:"Operating Expenditure (OPEX)";i:2;s:35:"General and Administrative Expenses";i:3;s:19:"Incremental Revenue";}','Capital Expenditure (CAPEX)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000347','Manakah faktor yang mencakup biaya operasional (OPEX) dalam proyek EOR?','multi','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:29:"Pembelian bahan kimia injeksi";i:1;s:33:"Biaya listrik untuk pompa injeksi";i:2;s:28:"Biaya pemeliharaan fasilitas";i:3;s:30:"Biaya eksplorasi lapangan baru";}','','a:3:{i:0;s:29:"Pembelian bahan kimia injeksi";i:1;s:33:"Biaya listrik untuk pompa injeksi";i:2;s:28:"Biaya pemeliharaan fasilitas";}','Which factors are included in operating expenditures (OPEX) for an EOR project?','a:4:{i:0;s:31:"Purchase of injection chemicals";i:1;s:37:"Electricity costs for injection pumps";i:2;s:26:"Facility maintenance costs";i:3;s:27:"New field exploration costs";}','a:3:{i:0;s:31:"Purchase of injection chemicals";i:1;s:37:"Electricity costs for injection pumps";i:2;s:26:"Facility maintenance costs";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000348','Apa arti dari Break-even Oil Price dalam ekonomi proyek EOR?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:47:"Harga minyak di mana NPV proyek sama dengan nol";i:1;s:42:"Harga minyak terendah yang pernah tercatat";i:2;s:44:"Harga minyak yang diinginkan oleh pemerintah";i:3;s:41:"Harga jual minyak setelah dikurangi pajak";}','','Harga minyak di mana NPV proyek sama dengan nol','What is the meaning of Break-even Oil Price in EOR project economics?','a:4:{i:0;s:50:"The oil price at which the project NPV equals zero";i:1;s:34:"The lowest oil price ever recorded";i:2;s:39:"The oil price desired by the government";i:3;s:45:"The selling price of oil after tax deductions";}','The oil price at which the project NPV equals zero','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000349','Risiko teknis dalam proyek EOR yang dapat menyebabkan kegagalan ekonomi meliputi:','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:58:"Injeksi tidak mencapai zona target (poor sweep efficiency)";i:1;s:44:"Terlalu banyak cadangan minyak yang tersedia";i:2;s:31:"Harga minyak yang sangat tinggi";i:3;s:28:"Pajak pemerintah yang rendah";}','','Injeksi tidak mencapai zona target (poor sweep efficiency)','Technical risks in an EOR project that can lead to economic failure include:','a:4:{i:0;s:66:"Injection failing to reach the target zone (poor sweep efficiency)";i:1;s:31:"Too much oil reserves available";i:2;s:20:"Very high oil prices";i:3;s:20:"Low government taxes";}','Injection failing to reach the target zone (poor sweep efficiency)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000350','Metode penyuntikan air dengan salinitas rendah (Low Salinity Waterflooding) umumnya bertujuan untuk meningkatkan perolehan minyak melalui mekanisme apa?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:52:"Perubahan wettability batuan menjadi lebih water-wet";i:1;s:36:"Peningkatan viskositas minyak mentah";i:2;s:35:"Penurunan densitas batuan reservoir";i:3;s:42:"Peningkatan tekanan kapiler secara drastis";}','','Perubahan wettability batuan menjadi lebih water-wet','Low Salinity Waterflooding generally aims to increase oil recovery through which mechanism?','a:4:{i:0;s:51:"Alteration of rock wettability to be more water-wet";i:1;s:31:"Increase in crude oil viscosity";i:2;s:34:"Decrease in reservoir rock density";i:3;s:38:"Drastic increase in capillary pressure";}','Alteration of rock wettability to be more water-wet','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000351','Manakah pernyataan yang benar mengenai peran utama CO2-EOR dalam hubungannya dengan CCS?','multi','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:80:"Mengurangi emisi gas rumah kaca ke atmosfer melalui penyimpanan CO2 di reservoir";i:1;s:72:"Meningkatkan perolehan minyak melalui mekanisme miscible atau immiscible";i:2;s:71:"Menambah viskositas minyak secara signifikan hingga mencapai fase padat";i:3;s:57:"Menghilangkan kebutuhan akan fasilitas produksi permukaan";}','','a:2:{i:0;s:80:"Mengurangi emisi gas rumah kaca ke atmosfer melalui penyimpanan CO2 di reservoir";i:1;s:72:"Meningkatkan perolehan minyak melalui mekanisme miscible atau immiscible";}','Which statements are correct regarding the primary role of CO2-EOR in relation to CCS?','a:4:{i:0;s:88:"Reducing greenhouse gas emissions to the atmosphere through CO2 storage in the reservoir";i:1;s:65:"Increasing oil recovery through miscible or immiscible mechanisms";i:2;s:55:"Significantly increasing oil viscosity to a solid phase";i:3;s:54:"Eliminating the need for surface production facilities";}','a:2:{i:0;s:88:"Reducing greenhouse gas emissions to the atmosphere through CO2 storage in the reservoir";i:1;s:65:"Increasing oil recovery through miscible or immiscible mechanisms";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000352','Penerapan digitalisasi dalam manajemen proyek CEOR sering melibatkan penggunaan teknologi apa?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:59:"Artificial Intelligence untuk pemodelan reservoir real-time";i:1;s:43:"Penggunaan pompa manual untuk injeksi kimia";i:2;s:42:"Penyimpanan data fisik dalam bentuk kertas";i:3;s:46:"Metode penentuan saturasi minyak secara manual";}','','Artificial Intelligence untuk pemodelan reservoir real-time','The application of digitalization in CEOR project management often involves the use of which technology?','a:4:{i:0;s:56:"Artificial Intelligence for real-time reservoir modeling";i:1;s:46:"The use of manual pumps for chemical injection";i:2;s:37:"Physical data storage in paper format";i:3;s:43:"Manual oil saturation determination methods";}','Artificial Intelligence for real-time reservoir modeling','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000353','Faktor utama yang menentukan keberhasilan injeksi CO2 miscible di lapangan adalah?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:43:"Mencapai Minimum Miscibility Pressure (MMP)";i:1;s:42:"Menjaga tekanan di bawah tekanan gelembung";i:2;s:39:"Menggunakan air dengan salinitas tinggi";i:3;s:36:"Menghindari penggunaan gas CO2 murni";}','','Mencapai Minimum Miscibility Pressure (MMP)','The main factor determining the success of miscible CO2 injection in the field is?','a:4:{i:0;s:44:"Achieving Minimum Miscibility Pressure (MMP)";i:1;s:43:"Maintaining pressure below the bubble point";i:2;s:25:"Using high salinity water";i:3;s:32:"Avoiding the use of pure CO2 gas";}','Achieving Minimum Miscibility Pressure (MMP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000354','Dalam studi kasus lapangan CEOR, apa tantangan teknis utama dari implementasi polimer flooding?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:60:"Degradasi polimer akibat suhu tinggi dan salinitas reservoir";i:1;s:34:"Polimer yang terlalu mudah menguap";i:2;s:50:"Peningkatan permeabilitas batuan secara berlebihan";i:3;s:31:"Harga polimer yang sangat murah";}','','Degradasi polimer akibat suhu tinggi dan salinitas reservoir','In CEOR field case studies, what is the main technical challenge of polymer flooding implementation?','a:4:{i:0;s:66:"Polymer degradation due to high reservoir temperature and salinity";i:1;s:26:"Polymer being too volatile";i:2;s:39:"Excessive increase in rock permeability";i:3;s:21:"Very low polymer cost";}','Polymer degradation due to high reservoir temperature and salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000355','Apa dampak positif dari integrasi CCS dengan proyek CO2-EOR dari sisi ekonomi?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:64:"Pemberian kredit karbon atau insentif pajak atas penyimpanan CO2";i:1;s:37:"Penghapusan biaya operasional injeksi";i:2;s:55:"Peningkatan drastis harga minyak global secara otomatis";i:3;s:41:"Pengurangan volume minyak yang dihasilkan";}','','Pemberian kredit karbon atau insentif pajak atas penyimpanan CO2','What is the positive impact of CCS integration with CO2-EOR projects from an economic perspective?','a:4:{i:0;s:61:"Provision of carbon credits or tax incentives for CO2 storage";i:1;s:40:"Elimination of injection operating costs";i:2;s:47:"Automatic drastic increase in global oil prices";i:3;s:32:"Reduction in oil volume produced";}','Provision of carbon credits or tax incentives for CO2 storage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000356','Teknologi digital ''Digital Twin'' dalam CEOR digunakan untuk tujuan apa?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:65:"Simulasi performa reservoir secara virtual sebelum tindakan nyata";i:1;s:36:"Mengganti peran geologis di lapangan";i:2;s:44:"Meningkatkan porositas batuan secara digital";i:3;s:43:"Mengurangi laju alir fluida secara permanen";}','','Simulasi performa reservoir secara virtual sebelum tindakan nyata','What is the ''Digital Twin'' technology in CEOR used for?','a:4:{i:0;s:60:"Virtual reservoir performance simulation before real actions";i:1;s:45:"Replacing the role of geologists in the field";i:2;s:34:"Digitally increasing rock porosity";i:3;s:36:"Permanently reducing fluid flow rate";}','Virtual reservoir performance simulation before real actions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000357','Manakah parameter yang paling dipengaruhi oleh penambahan surfaktan dalam metode CEOR?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:63:"Tegangan antar muka (Interfacial Tension) antara minyak dan air";i:1;s:28:"Permeabilitas absolut batuan";i:2;s:23:"Densitas batuan sedimen";i:3;s:21:"Kedalaman total sumur";}','','Tegangan antar muka (Interfacial Tension) antara minyak dan air','Which parameter is most affected by the addition of surfactants in CEOR methods?','a:4:{i:0;s:41:"Interfacial Tension between oil and water";i:1;s:26:"Absolute rock permeability";i:2;s:24:"Sedimentary rock density";i:3;s:16:"Total well depth";}','Interfacial Tension between oil and water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000358','Dalam konteks masa depan CEOR, mengapa pemantauan (monitoring) secara real-time menjadi krusial?','multi','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:61:"Untuk optimasi injeksi secara dinamis berdasarkan data sensor";i:1;s:60:"Mendeteksi adanya kebocoran atau masalah injeksi secara dini";i:2;s:55:"Menggantikan fungsi pengujian laboratorium secara total";i:3;s:49:"Menghilangkan kebutuhan akan personel di lapangan";}','','a:2:{i:0;s:61:"Untuk optimasi injeksi secara dinamis berdasarkan data sensor";i:1;s:60:"Mendeteksi adanya kebocoran atau masalah injeksi secara dini";}','In the context of the future of CEOR, why is real-time monitoring crucial?','a:4:{i:0;s:55:"For dynamic injection optimization based on sensor data";i:1;s:41:"Detecting leaks or injection issues early";i:2;s:49:"Completely replacing laboratory testing functions";i:3;s:47:"Eliminating the need for personnel in the field";}','a:2:{i:0;s:55:"For dynamic injection optimization based on sensor data";i:1;s:41:"Detecting leaks or injection issues early";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000359','Apa tujuan utama dari proses ''screening'' dalam pemilihan metode CEOR untuk suatu lapangan?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:84:"Memastikan metode yang dipilih sesuai dengan karakteristik fisik dan kimia reservoir";i:1;s:75:"Memilih metode berdasarkan biaya paling murah tanpa mempertimbangkan teknis";i:2;s:48:"Memastikan proyek selesai dalam waktu satu bulan";i:3;s:35:"Menghindari penggunaan data seismik";}','','Memastikan metode yang dipilih sesuai dengan karakteristik fisik dan kimia reservoir','What is the primary purpose of the ''screening'' process in selecting a CEOR method for a field?','a:4:{i:0;s:95:"Ensuring the selected method matches the physical and chemical characteristics of the reservoir";i:1;s:74:"Selecting the method based on lowest cost without technical considerations";i:2;s:50:"Ensuring the project is completed within one month";i:3;s:32:"Avoiding the use of seismic data";}','Ensuring the selected method matches the physical and chemical characteristics of the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
